// נוצר אוטומטית מ-sims-src/ ע"י tools/build-sims.js. לא לערוך כאן.
const SIMS = [{"id":"s1","title":"בסיס · מבחן 1","tier":0,"tierHe":"בסיס","hi":118,"chapters":[{"type":"sc","qs":[{"q":"Many students drink coffee in the evening ___ they have to study late for their exams.","o":["unless","because","although","whereas"],"a":1,"ex":"«because» = כי, מפני ש. החלק השני (צריך ללמוד עד מאוחר) הוא הסיבה לחלק הראשון (שותים קפה בערב). «although» היה יוצר ניגוד, אבל אין כאן שום ניגוד.","w":[["because","כי, מפני ש..."],["although","למרות ש..."]]},{"q":"Doctors say that regular exercise can ___ your sleep, so people who walk every day often rest better at night.","o":["improve","avoid","delay","waste"],"a":0,"ex":"«improve» = לשפר. סוף המשפט אומר שמי שהולך כל יום ישן טוב יותר, ולכן הפעילות משפרת את השינה. «delay» (לדחות) או «waste» (לבזבז) היו אומרים שהשינה נפגעת.","w":[["improve","לשפר"],["regular","קבוע, סדיר"]]},{"q":"___ the museum is free on Sundays, very few people visit it during the winter.","o":["Since","Unless","As soon as","Although"],"a":3,"ex":"«Although» = למרות ש. היינו מצפים שכניסה חינם תביא הרבה מבקרים, אבל מגיעים מעט: זה ניגוד, ולכן צריך מילת ויתור. «Since» (מכיוון ש) היה אומר שהכניסה החינמית היא הסיבה לכך שמעטים מגיעים, וזה לא הגיוני.","w":[["although","למרות ש..."],["since","מכיוון ש..."]]},{"q":"The number of small shops in the town center has ___ sharply in recent years, as more people now buy everything online.","o":["appeared","repaired","declined","celebrated"],"a":2,"ex":"«decline» = לרדת, לפחות. אנשים קונים באינטרנט, ולכן מספר החנויות ירד. «sharply» (בחדות) מתאר שינוי בכמות, וזה מתאים רק ל-«declined».","w":[["decline","לרדת, לפחות"],["sharply","בחדות"]]}]},{"type":"sc","qs":[{"q":"To save money, Dana decided to cook dinner at home ___ eating at an expensive restaurant every night.","o":["because of","in addition to","instead of","as a result of"],"a":2,"ex":"«instead of» = במקום. כדי לחסוך, דנה מבשלת בבית במקום לאכול במסעדה יקרה. «in addition to» (בנוסף ל) היה אומר שהיא גם אוכלת במסעדה כל ערב, וזה לא חוסך כסף.","w":[["instead of","במקום (+שם עצם / ing)"],["in addition to","בנוסף ל... (+שם עצם)"]]},{"q":"Because infections spread easily, most hospitals ___ visitors to wash their hands; anyone who refuses is not allowed to enter.","o":["forbid","require","pay","encourage"],"a":1,"ex":"«require» = לדרוש, לחייב. מי שמסרב לא נכנס, כלומר זו חובה ולא המלצה. «encourage» (לעודד) מפתה, אבל עידוד לא בא עם עונש למי שמסרב.","w":[["require","לדרוש, לחייב"],["refuse","לסרב"]]},{"q":"You will not be able to join the trip ___ you return the signed form by Friday.","o":["unless","because","so that","although"],"a":0,"ex":"«unless» = אלא אם כן. לא תוכל להצטרף לטיול אלא אם תחזיר את הטופס: זה תנאי. «because» היה אומר שהחזרת הטופס היא הסיבה שלא תצטרף, וזה הפוך מההיגיון.","w":[["unless","אלא אם כן"],["so that","כדי ש... (+משפט)"]]},{"q":"Archaeologists found ___ coins in the desert that were used by traders more than two thousand years ago.","o":["modern","plastic","electronic","ancient"],"a":3,"ex":"«ancient» = עתיק. מטבעות שהשתמשו בהם לפני יותר מאלפיים שנה הם עתיקים. «modern» (מודרני) הוא בדיוק ההפך.","w":[["ancient","עתיק"],["trader","סוחר"]]}]},{"type":"rc","title":"Travelers in the Dark","text":["Every spring and autumn, billions of birds travel thousands of kilometers between their summer and winter homes. What surprises many people is that a large number of these birds, including most small songbirds, make their journeys at night. While we sleep, the sky above us may be full of tiny travelers that we never see.","Scientists believe there are several reasons for this behavior. First, the air at night is usually cooler and calmer than during the day. Flying is hard work, and small birds can easily lose too much water if they fly under a hot sun. Cool night air helps them avoid this danger. In addition, the dark sky protects them from hawks and other hunters, which mostly look for food in daylight.","Night travel also allows birds to use their time well. During the day, they can rest and eat in fields and forests, so they replace the energy they used the night before. Without these daily stops, few birds would have enough strength to complete such a long trip.","But how do birds find their way in the dark? Research shows that they use several tools at once. Some young birds learn the pattern of the stars, especially the stars around the North Star, which hardly moves during the night. Birds can also sense the earth's magnetic field, which works for them like a natural compass. Unfortunately, bright city lights can confuse them, and many birds crash into tall buildings. For this reason, some cities now ask building owners to turn off unnecessary lights during migration season."],"qs":[{"q":"The passage mainly discusses","o":["the dangers that hawks present to small songbirds","why many birds migrate at night and how they find their way","how cities have reduced the number of birds in the sky","the differences between the summer and winter homes of birds"],"a":1,"ex":"הקטע כולו עוסק בשתי שאלות: למה ציפורים נודדות בלילה (פסקאות 2-3) ואיך הן מוצאות את הדרך בחושך (פסקה 4). הנצים מוזכרים רק במשפט אחד, ולכן זו לא התשובה הכללית.","w":[["migrate","לנדוד"],["mainly","בעיקר"]]},{"q":"According to the second paragraph, one advantage of flying at night is that","o":["birds can find more food in the dark","the stars are easier to see in autumn","hawks are more active after sunset","birds lose less water in the cool air"],"a":3,"ex":"בפסקה 2 כתוב שבשמש חמה ציפורים קטנות מאבדות יותר מדי מים, ושאוויר הלילה הקריר עוזר להן להימנע מזה. לגבי הנצים כתוב ההפך: הם צדים בעיקר ביום.","w":[["advantage","יתרון"],["avoid","להימנע מ..."]]},{"q":"In the third paragraph, the word 'they' in 'so they replace the energy' refers to","o":["the birds","the fields and forests","the days","the hunters"],"a":0,"ex":"מי שנח ואוכל ביום וכך ממלא את האנרגיה שבזבז בלילה הן הציפורים. שדות ויערות הם רק המקום שבו הן נחות.","w":[["replace","להחליף, למלא מחדש"],["energy","אנרגיה, כוח"]]},{"q":"The main purpose of the last sentence of the passage is to","o":["explain why birds prefer to fly near big cities","show that the North Star is difficult to see from cities","describe one step that is taken to protect migrating birds","prove that birds cannot use the earth's magnetic field"],"a":2,"ex":"המשפט האחרון מתחיל ב-«For this reason» (מסיבה זו): בגלל שהאורות מבלבלים את הציפורים, ערים מבקשות לכבות אורות מיותרים. זה צעד שנועד להגן עליהן. הקטע לא אומר שציפורים מעדיפות ערים.","w":[["for this reason","מסיבה זו"],["unnecessary","מיותר"]]},{"q":"It can be inferred from paragraph 3 that if birds could not stop during the day,","o":["they would fly faster at night","most of them would not finish their journey","they would learn the stars more quickly","hunters would stop looking for them"],"a":1,"ex":"בפסקה 3 כתוב שבלי העצירות היומיות מעט ציפורים (few birds) היו מצליחות להשלים את המסע. כלומר רובן לא היו מסיימות אותו. אין בקטע שום דבר על טיסה מהירה יותר.","w":[["infer","להסיק"],["few","מעט (כמעט אין)"]]}]},{"type":"rs","qs":[{"q":"Although the new bridge cost much more than planned, most residents believe it was worth the money because it cut their travel time in half.","o":["Because the new bridge cost much more than planned, most residents believe it was not worth the money, even though it cut their travel time.","Most residents believe the new bridge was worth the money, since it cost less than planned and cut their travel time in half.","The new bridge was far more expensive than expected; nevertheless, most residents think it was a good investment, since it halved their travel time.","Only a few residents think the new bridge was a good investment, even though it cost more than planned and cut their travel time in half."],"a":2,"ex":"«Although» הוחלף ב-«nevertheless» (למרות זאת), ו-«cut in half» הוחלף ב-«halved». המשמעות זהה: הגשר יקר, ובכל זאת רוב התושבים חושבים שהוא שווה. בתשובה האחרונה «Only a few» (רק מעטים) הופך את «most» (רוב).","w":[["nevertheless","למרות זאת, אף על פי כן"],["worth","שווה"],["resident","תושב"]]},{"q":"Unless farmers receive more rain this winter, they will have to plant fewer crops next year, which may raise food prices.","o":["If it does not rain more this winter, farmers will have to grow fewer crops next year, and food may get more expensive.","Even if much more rain falls this winter, farmers will still plant fewer crops next year, so food prices will certainly go down.","Farmers will plant more crops next year only if food prices rise sharply during this winter, regardless of the rain.","Because farmers received a lot of rain this winter, they will plant fewer crops next year, and food prices may fall as a result."],"a":0,"ex":"«Unless» = אלא אם כן, ובמילים אחרות «If ... not». התשובה הנכונה שומרת את התנאי (בלי גשם), את התוצאה (פחות גידולים) ואת האפשרות שהמחירים יעלו. «Even if» (גם אם) מבטל את התנאי, ושם המחירים גם יורדים.","w":[["unless","אלא אם כן"],["even if","גם אם, אפילו אם"],["crop","יבול, גידול חקלאי"]]},{"q":"Children who read for pleasure every day tend to develop a richer vocabulary than children who read only for school assignments.","o":["Children who read only for their school assignments usually know more words than children who read for fun every day.","Reading every day for pleasure makes it harder for children to finish their school assignments.","All children develop the same vocabulary, whether they read for fun or only for school.","Children who read daily for enjoyment usually know more words than those who read just for school tasks."],"a":3,"ex":"«for pleasure» = «for enjoyment», ו-«tend to develop a richer vocabulary» = בדרך כלל יודעים יותר מילים. התשובה הראשונה הופכת את ההשוואה, כאילו מי שקורא רק לבית הספר יודע יותר מילים.","w":[["tend to","נוטה ל..."],["vocabulary","אוצר מילים"],["assignment","מטלה"]]}]},{"type":"rs","qs":[{"q":"Many people avoid going to the dentist because they are afraid of pain, even though modern treatments are usually quick and almost painless.","o":["Modern dental treatments are often slow and painful, which is why many people refuse to visit the dentist at all.","Fear of pain keeps many people away from the dentist, although today's treatments are usually fast and nearly painless.","Many people visit the dentist often and without fear, because modern treatments are quick and almost painless.","Few people are afraid of the dentist today, since modern treatments have become quick and almost painless for most patients."],"a":1,"ex":"«even though» הוחלף ב-«although» (שתיהן: למרות ש), ו-«avoid going» הוחלף ב-«keeps away». הפחד מרחיק אנשים למרות שהטיפולים כמעט לא כואבים. בתשובה הראשונה הטיפולים כואבים, וזה ההפך מהמקור.","w":[["even though","אף על פי ש..."],["although","למרות ש..."],["avoid","להימנע מ..."]]},{"q":"The company decided to improve its training program after a survey showed that new workers did not understand many of their basic tasks.","o":["A survey found that new workers understood their basic tasks well, so the company kept its training program as it was.","The company improved its training program, and as a result, new workers began to complete a survey about their tasks.","New workers asked the company to cancel its training program because they already understood their basic tasks.","When a survey revealed that new employees were confused about many basic duties, the company chose to make its training better."],"a":3,"ex":"קודם הסקר הראה שהעובדים לא מבינים, ורק אחר כך החברה החליטה לשפר את ההדרכה. «improve» = «make better», ו-«did not understand» = «were confused». בתשובה השנייה הסדר הפוך: הסקר מופיע כתוצאה של השיפור.","w":[["improve","לשפר"],["after","אחרי"],["survey","סקר"]]},{"q":"Ancient sailors could cross wide seas without modern tools, since they learned to read the positions of the sun and the stars.","o":["Because they knew how to navigate by the sun and stars, sailors long ago could cross large seas without modern equipment.","Sailors long ago could not cross wide seas, because without modern tools they had no reliable way to find their direction.","Ancient sailors used modern tools to study the positions of the sun and the stars before they crossed wide seas.","Although ancient sailors studied the sun and the stars carefully, this knowledge rarely helped them when they tried to cross wide seas."],"a":0,"ex":"«since» כאן = מכיוון ש, ובתשובה הנכונה הוא הוחלף ב-«Because». «Ancient» = «long ago», ו-«tools» = «equipment». התשובה האחרונה הופכת את הסיבה לניגוד ואומרת שהידע כמעט לא עזר.","w":[["since","מכיוון ש..."],["ancient","עתיק, מימי קדם"],["rarely","לעיתים רחוקות"]]}]},{"type":"sc","qs":[{"q":"The road to the village was blocked by snow; ___, the doctor had to reach the patient by helicopter.","o":["however","for example","therefore","in contrast"],"a":2,"ex":"«therefore» = לכן. הכביש חסום, ולכן הרופא הגיע במסוק: זו תוצאה. «however» (עם זאת) היה יוצר ניגוד, אבל אין כאן ניגוד.","w":[["therefore","לכן"],["however","עם זאת, אולם"],["block","לחסום"]]},{"q":"Many drivers leave home before 7 a.m. in order to ___ the heavy traffic that fills the roads later in the morning.","o":["avoid","enjoy","create","measure"],"a":0,"ex":"«avoid» = להימנע מ. נהגים יוצאים מוקדם כדי לא להיתקע בפקקים. «create» (ליצור) או «enjoy» (ליהנות) לא מתאימים, כי אף אחד לא יוצא מוקדם כדי ליצור פקקים או ליהנות מהם.","w":[["avoid","להימנע מ..."],["in order to","כדי ל... (+פועל)"]]},{"q":"The new medicine must be tested on thousands of patients before doctors can ___ that it is safe.","o":["forget","hide","doubt","confirm"],"a":3,"ex":"«confirm» = לאשר, לוודא. בודקים את התרופה על אלפי חולים כדי לדעת בוודאות שהיא בטוחה. «doubt» (לפקפק) הוא ההפך: לא עושים ניסויים ארוכים כדי להתחיל לפקפק.","w":[["confirm","לאשר, לוודא"],["doubt","לפקפק"]]},{"q":"The old bus was so ___ that it broke down almost every week, and passengers often arrived late.","o":["popular","unreliable","expensive","comfortable"],"a":1,"ex":"«unreliable» = לא אמין. אוטובוס שמתקלקל כל שבוע ומאחר הוא לא אמין. «so ... that» (כל כך... ש) מחייב שהתכונה תסביר את התקלות, ו-«popular» או «comfortable» לא מסבירים אותן.","w":[["unreliable","לא אמין"],["so... that","כל כך... ש..."],["break down","להתקלקל"]]}]}]},{"id":"s2","title":"בסיס · מבחן 2","tier":0,"tierHe":"בסיס","hi":118,"chapters":[{"type":"sc","qs":[{"q":"Many students are ___ to ask questions in class because they are afraid of looking foolish.","o":["reluctant","eager","proud","certain"],"a":0,"ex":"«Reluctant» = לא ששׂ, מהסס. הסיבה (הם מפחדים להיראות טיפשים) מסבירה למה הם לא רוצים לשאול. «Eager» (להוט) הוא ההפך ולא מתאים לפחד.","w":[["reluctant","מסרב, לא ששׂ"],["eager","להוט"],["because","כי, מפני ש..."]]},{"q":"Tom prefers quiet mornings, ___ his sister enjoys loud music as soon as she wakes up.","o":["so that","whereas","as a result","because"],"a":1,"ex":"«Whereas» = ואילו. משווים בין שני אנשים שונים: טום אוהב שקט, ואילו אחותו אוהבת מוזיקה רועשת. «Because» היה אומר שהמוזיקה שלה היא הסיבה שהוא אוהב שקט, וזה לא מה שהמשפט אומר.","w":[["whereas","בעוד ש..., ואילו"],["as soon as","ברגע ש..., מיד כש..."]]},{"q":"The number of people who smoke has ___ steadily over the last twenty years, thanks to strong public health campaigns.","o":["increased","doubled","declined","appeared"],"a":2,"ex":"«Declined» = ירד. קמפיינים לבריאות הציבור אמורים להוריד את מספר המעשנים, ו«thanks to» (בזכות) מראה שזו תוצאה טובה. «Increased» ו«doubled» (עלה, הכפיל את עצמו) הם תוצאה רעה, ולא מתאימים ל«בזכות».","w":[["decline","לרדת, לפחות"],["thanks to","הודות ל..., בזכות"],["steadily","בהתמדה, בהדרגה"]]},{"q":"You should save your work every few minutes; ___, you may lose everything if the computer crashes.","o":["moreover","similarly","for instance","otherwise"],"a":3,"ex":"«Otherwise» = אחרת. אם לא תשמור, תאבד הכול. החלק השני מתאר מה יקרה אם לא נעשה את מה שבחלק הראשון. «Moreover» (יתרה מזאת) רק מוסיף מידע ולא מתאים לאזהרה.","w":[["otherwise","אחרת"],["moreover","יתרה מזאת"]]}]},{"type":"sc","qs":[{"q":"The museum staff check the temperature in each room every day to ___ that the old paintings are not damaged.","o":["doubt","ensure","forget","deny"],"a":1,"ex":"«Ensure» = לוודא, להבטיח. הצוות בודק את הטמפרטורה כדי לוודא שהציורים לא ייפגעו. «Doubt» (לפקפק) ו«deny» (להכחיש) לא מסבירים למה בודקים כל יום.","w":[["ensure","לוודא, להבטיח"],["damage","לגרום נזק"]]},{"q":"___ the long delay at the airport, the passengers remained calm and polite.","o":["Despite","Because of","Instead of","In addition to"],"a":0,"ex":"«Despite» = למרות. עיכוב ארוך בדרך כלל מעצבן, ובכל זאת הנוסעים נשארו רגועים: זה ניגוד. «Because of» היה אומר שהעיכוב גרם להם להיות רגועים, וזה לא הגיוני.","w":[["despite","למרות (+שם עצם)"],["because of","בגלל (+שם עצם)"],["remain","להישאר"]]},{"q":"Snow is ___ in this part of the country; most people who live here have seen it only once or twice in their lives.","o":["common","heavy","welcome","rare"],"a":3,"ex":"«Rare» = נדיר. אם רוב התושבים ראו שלג רק פעם או פעמיים, השלג נדיר שם. «Common» (נפוץ) ו«heavy» (כבד) סותרים את החלק השני של המשפט.","w":[["rare","נדיר"],["common","נפוץ"]]},{"q":"You may borrow my car this weekend, ___ you return it with a full tank of gas.","o":["even though","whereas","provided that","so that"],"a":2,"ex":"«Provided that» = בתנאי ש. מותר לקחת את הרכב בתנאי שתחזיר אותו עם מיכל מלא. «Even though» (אף על פי ש) מראה ניגוד, ואין כאן ניגוד אלא תנאי.","w":[["provided that","בתנאי ש..."],["even though","אף על פי ש..."]]}]},{"type":"rc","title":"From Private Shelves to Public Spaces","text":["For most of history, books were rare and expensive. Before the invention of the printing press, each copy had to be written by hand, a process that could take months. As a result, collections of books belonged mainly to kings, religious institutions and wealthy families. Ordinary people were seldom allowed to enter these collections, and many of them could not read in any case.","This situation began to change in the nineteenth century. As cities grew and more children attended school, reformers argued that knowledge should not be limited to the rich. They believed that a free library would help workers improve themselves and become better citizens. In the middle of the century, Britain passed a law that allowed towns to use public money to open libraries, and the United States soon followed. Some officials were reluctant to spend tax money on books, but the idea gradually spread.","For about a hundred years, the main role of the public library was simple: to lend books and to provide a quiet place to read. In the late twentieth century, however, this role was challenged. Television, and later the internet, gave people new ways to find information and entertainment. Many experts predicted that the number of visitors would decline and that libraries would eventually disappear.","That prediction has not come true. Instead, libraries have changed their role. Today, many of them offer free internet access, classes in computer skills and help for people who are looking for work. In addition, they serve as meeting places for local groups and as safe spaces for children after school. Whereas the early library was mainly a storehouse of books, the modern library is closer to a community center. Its goal, however, remains the same: to ensure that everyone, whatever their income, has access to knowledge."],"qs":[{"q":"The passage mainly discusses","o":["why the printing press made books cheaper","why the internet will soon replace public libraries","how public libraries began and how their role has changed over time","the differences between libraries in Britain and the United States"],"a":2,"ex":"הקטע עובר מההיסטוריה (ספרים נדירים, ספריות ציבוריות במאה ה-19) אל השינוי בתפקיד הספרייה היום. האפשרות על האינטרנט סותרת את הפסקה האחרונה, שאומרת שהתחזית לא התגשמה.","w":[["role","תפקיד"],["mainly","בעיקר"]]},{"q":"According to the first paragraph, collections of books belonged mainly to the rich because","o":["books were copied slowly by hand and were therefore expensive","the law did not allow ordinary people to buy books","religious institutions refused to share their books","most ordinary people preferred to listen to stories"],"a":0,"ex":"בפסקה 1: כל עותק נכתב ביד ולקח חודשים, ולכן «As a result» הספרים היו של מלכים ועשירים. אין בפסקה שום חוק שאסר לקנות ספרים.","w":[["as a result","כתוצאה מכך"],["wealthy","עשיר"],["seldom","לעיתים רחוקות"]]},{"q":"In the second paragraph, the word 'They' (in 'They believed that...') refers to","o":["cities","children","workers","reformers"],"a":3,"ex":"המשפט הקודם אומר ש«reformers» (אנשי רפורמה) טענו שידע לא צריך להיות רק לעשירים, והם אלה ש«האמינו» שספרייה חינמית תעזור לפועלים. «Workers» מופיעים באותו משפט, אבל הם מי שעוזרים לו, לא מי שמאמין.","w":[["reformer","מתקן חברתי, איש רפורמה"],["argue","לטעון"]]},{"q":"According to the third paragraph, many experts expected that","o":["television would make people read more books","libraries would lose visitors and finally close","libraries would start to lend computers","the number of public libraries would grow quickly"],"a":1,"ex":"בפסקה 3 כתוב שהמומחים חזו שמספר המבקרים «would decline» (ירד) ושהספריות «would eventually disappear» (ייעלמו בסוף). «Grow quickly» הוא ההפך.","w":[["predict","לחזות"],["eventually","בסופו של דבר"],["decline","לרדת, לפחות"]]},{"q":"The main purpose of the last paragraph is to","o":["explain why the experts' prediction was correct","describe how libraries have adapted to people's new needs","argue that libraries should stop lending books","compare libraries in poor and rich neighborhoods"],"a":1,"ex":"הפסקה האחרונה מתארת מה הספריות מציעות היום (אינטרנט, קורסים, מקום מפגש) כלומר איך הן השתנו. היא פותחת במילים «That prediction has not come true», ולכן היא לא מסבירה שהתחזית הייתה נכונה.","w":[["instead","במקום זאת"],["in addition","בנוסף"],["whereas","בעוד ש..., ואילו"]]}]},{"type":"rs","qs":[{"q":"Although the new highway shortened the trip to the city, many local residents were unhappy with it because it brought noise and pollution to their neighborhood.","o":["Because the new highway made the trip to the city shorter, local residents were pleased with it in spite of the noise and pollution it brought.","Many local residents opposed the new highway because it made the trip to the city longer and their area noisier.","The new highway made the trip to the city shorter; nevertheless, many people living nearby disliked it, since it caused noise and pollution in their area.","The noise and pollution in the neighborhood were caused mainly by local residents who used the new highway every day to travel to the city."],"a":2,"ex":"במקור: הכביש קיצר את הדרך, ובכל זאת התושבים לא מרוצים בגלל רעש וזיהום. «nevertheless» שומר על אותו ניגוד כמו «Although». התשובה הראשונה הופכת את המשמעות (התושבים מרוצים), והשנייה אומרת שהדרך התארכה.","w":[["although","למרות ש... (+משפט)"],["nevertheless","למרות זאת, אף על פי כן"],["resident","תושב"]]},{"q":"Scientists rarely agree on the exact causes of climate change in a particular region, since local weather is influenced by many factors at the same time.","o":["Because many factors affect local weather simultaneously, scientists seldom reach agreement about what exactly causes climate change in a specific region.","Scientists usually agree on the exact causes of climate change in a region, even though local weather is affected by many factors.","Since scientists rarely agree with each other, local weather in a particular region is influenced by many different factors.","Scientists rarely study local weather, because climate change in a particular region has only one main cause."],"a":0,"ex":"«rarely» = «seldom» (לעיתים רחוקות), ו«since» = «because» (מכיוון ש). התשובה השנייה משנה את «rarely» ל«usually», והשלישית הופכת סיבה ותוצאה: כאילו חוסר ההסכמה גורם למזג האוויר.","w":[["rarely","לעיתים רחוקות"],["seldom","לעיתים רחוקות"],["simultaneously","בו זמנית"]]},{"q":"Unless the city council finds additional funding by the end of the year, the plan to build a new public swimming pool will be canceled.","o":["The city council will find additional funding by the end of the year, so the new public swimming pool will be built.","Even if the city council finds more money by the end of the year, the plan for the new swimming pool will be canceled.","The plan to build a new swimming pool was canceled because the city council spent its money before the end of the year.","The plan for a new public swimming pool will be canceled if the city council does not find more money before the year ends."],"a":3,"ex":"«Unless» = אלא אם כן, כלומר «if ... not». התוכנית תבוטל אם לא יימצא כסף. «Even if» (גם אם) אומר שהיא תבוטל בכל מקרה, וזו משמעות אחרת. התשובה הראשונה טוענת בוודאות שהכסף יימצא, וזה לא כתוב במקור.","w":[["unless","אלא אם כן"],["even if","גם אם, אפילו אם"],["funding","מימון"]]}]},{"type":"rs","qs":[{"q":"Unlike earlier studies, the new research found that children who read for pleasure every day also tend to perform better in mathematics.","o":["Like earlier studies, the new research found that children who are good at mathematics usually enjoy reading every day.","Unlike earlier studies, the new research found that children who read every day for pleasure tend to do worse in mathematics.","Earlier studies found that daily reading improves mathematics, but the new research found no connection between the two.","The new research, unlike previous studies, showed that children who read for enjoyment every day generally do better in math as well."],"a":3,"ex":"«Unlike» = בניגוד ל. רק המחקר החדש מצא שילדים שקוראים להנאה כל יום מצליחים יותר במתמטיקה. התשובה השנייה משנה «better» ל«worse», והשלישית מחליפה בין המחקר החדש למחקרים הקודמים.","w":[["unlike","בניגוד ל... (+שם עצם)"],["tend to","נוטה ל..."],["perform","לבצע, להצליח (במשימה)"]]},{"q":"Demand for the company's products grew rapidly in the north; as a result, the company decided to open a second factory in that region.","o":["The company decided to open another factory in the north because demand for its products in that area had increased quickly.","Because the company opened a second factory in the north, demand for its products in that region grew rapidly.","Although demand for its products grew in the north, the company decided not to open a second factory there.","The company closed its factory in the north and opened a second one elsewhere, since demand in the north was falling."],"a":0,"ex":"במקור: הביקוש עלה (סיבה), ולכן נפתח מפעל שני (תוצאה). «because» בתשובה הנכונה שומר על אותו סדר הגיוני. התשובה השנייה הופכת סיבה ותוצאה: כאילו המפעל גרם לביקוש.","w":[["as a result","כתוצאה מכך"],["demand","ביקוש"],["rapidly","במהירות"]]},{"q":"Despite being one of the oldest buildings in town, the library is visited by hundreds of young people every week, many of whom come to study for exams.","o":["Because the library is one of the oldest buildings in town, very few young people visit it, except those who come to study for exams.","Hundreds of young people visit the library every week in order to see one of the oldest and most famous buildings in town.","Although the library is among the oldest buildings in town, hundreds of young people go there each week, many of them to study for exams.","The library, which was built only a few years ago, is visited every week by hundreds of young people, many of whom come to study for exams."],"a":2,"ex":"«Despite» = «Although» (למרות). הבניין ישן, ובכל זאת מאות צעירים מגיעים, ורבים מהם לומדים למבחנים. התשובה הראשונה אומרת שמעט מבקרים, והרביעית אומרת שהבניין חדש.","w":[["despite","למרות (+שם עצם)"],["although","למרות ש... (+משפט)"],["in order to","כדי ל... (+פועל)"]]}]},{"type":"sc","qs":[{"q":"Driving while very tired can have serious ___, such as accidents that hurt both the driver and other people on the road.","o":["benefits","consequences","habits","reasons"],"a":1,"ex":"«Consequences» = השלכות, תוצאות. תאונות הן תוצאה של נהיגה בעייפות. «Benefits» (יתרונות) הוא ההפך, ו«reasons» (סיבות) לא מתאים כי התאונה באה אחרי הנהיגה ולא לפניה.","w":[["consequence","תוצאה, השלכה"],["such as","כגון, כמו"],["benefit","יתרון, תועלת"]]},{"q":"The old bridge was in such poor ___ that the city closed it to traffic until the repairs were finished.","o":["condition","position","attention","opinion"],"a":0,"ex":"«Condition» = מצב. הגשר היה במצב כל כך גרוע שסגרו אותו עד סוף התיקונים. «Position» (מיקום) לא מסביר למה צריך תיקונים.","w":[["condition","מצב"],["so... that","כל כך... ש..."],["until","עד ש..."]]},{"q":"Because the road was icy, the driver tried to ___ sudden stops, which could cause the car to slide.","o":["practice","enjoy","require","avoid"],"a":3,"ex":"«Avoid» = להימנע מ. עצירות פתאומיות על כביש קפוא מסוכנות, ולכן הנהג ניסה להימנע מהן. «Practice» (להתאמן) או «enjoy» (ליהנות) לא הגיוניים כשמדובר בסכנה.","w":[["avoid","להימנע מ..."],["because","כי, מפני ש... (+משפט)"]]},{"q":"The team trained hard for months; ___, they won the national championship for the first time.","o":["nevertheless","for instance","as a result","in contrast"],"a":2,"ex":"«As a result» = כתוצאה מכך. האימונים הקשים (סיבה) הובילו לזכייה (תוצאה). «Nevertheless» (למרות זאת) מתאים רק כשיש ניגוד, ואין ניגוד בין אימון קשה לניצחון.","w":[["as a result","כתוצאה מכך"],["nevertheless","למרות זאת, אף על פי כן"]]}]}]},{"id":"s6","title":"בסיס · מבחן 3","tier":0,"tierHe":"בסיס","hi":118,"chapters":[{"type":"sc","qs":[{"q":"Most of the city's parks are crowded on weekends; ___, on weekday mornings they are almost empty.","o":["however","moreover","therefore","for example"],"a":0,"ex":"«however» = עם זאת. בסופי שבוע הפארקים מלאים, ובבקרים של ימי חול הם כמעט ריקים: זה ניגוד. «therefore» (לכן) היה הופך את החלק השני לתוצאה של הראשון, וזה לא הגיוני.","w":[["however","עם זאת, אולם"],["crowded","צפוף, מלא אנשים"]]},{"q":"The doctor told Maya to drink more water, because her headaches were probably ___ by not drinking enough on hot days.","o":["prevented","solved","caused","ignored"],"a":2,"ex":"«caused by» = נגרם על ידי. הרופא חושב שחוסר שתייה הוא הסיבה לכאבי הראש, ולכן הוא אומר לה לשתות יותר. «prevented» (נמנע) הפוך במשמעות: חוסר שתייה לא מונע כאבי ראש.","w":[["cause","לגרום"],["prevent","למנוע"]]},{"q":"The library stayed open later in the evening ___ students could study there before their exams.","o":["even though","unless","whereas","so that"],"a":3,"ex":"«so that» = כדי ש. הספרייה נשארה פתוחה מאוחר יותר במטרה שהסטודנטים יוכלו ללמוד. «even though» (אף על פי ש) יוצר ניגוד, ואין כאן ניגוד בין שני החלקים.","w":[["so that","כדי ש... (+משפט)"],["even though","אף על פי ש..."]]},{"q":"Vegetables stay fresh for many days in a cool, dry place, but in a warm kitchen they ___ quickly.","o":["freeze","spoil","recover","shine"],"a":1,"ex":"«spoil» = להתקלקל. המשפט מנגיד (but) בין מקום קריר שבו הירקות נשארים טריים לבין מטבח חם, ולכן שם הם מתקלקלים. «freeze» (לקפוא) לא קורה במטבח חם.","w":[["spoil","להתקלקל"],["fresh","טרי"]]}]},{"type":"sc","qs":[{"q":"The outdoor concert was ___ because of the storm, so the band promised to play again next month.","o":["recorded","enjoyed","canceled","repeated"],"a":2,"ex":"«canceled» = בוטל. בגלל הסערה ההופעה בוטלה, ולכן הלהקה הבטיחה לנגן שוב בחודש הבא. «enjoyed» (נהנו ממנו) לא מסביר למה צריך לנגן שוב.","w":[["cancel","לבטל"],["because of","בגלל (+שם עצם)"]]},{"q":"Many teenagers stay up late looking at their phones; ___, some of them sleep only five or six hours a night.","o":["as a result","in contrast","for instance","on the other hand"],"a":0,"ex":"«as a result» = כתוצאה מכך. השינה הקצרה היא התוצאה של השימוש בטלפון עד מאוחר. «in contrast» ו-«on the other hand» יוצרים ניגוד, ואין כאן ניגוד.","w":[["as a result","כתוצאה מכך"],["in contrast","לעומת זאת"]]},{"q":"The teacher gave a clear ___ of the problem, and after that everyone in the class understood how to solve it.","o":["complaint","mistake","question","explanation"],"a":3,"ex":"«explanation» = הסבר. אחרי הסבר ברור כולם הבינו איך לפתור את הבעיה. «mistake» (טעות) לא הייתה עוזרת לכיתה להבין.","w":[["explanation","הסבר"],["solve","לפתור"]]},{"q":"___ Sam had trained for months, he did not finish the race because he hurt his leg.","o":["Since","Even though","So that","As soon as"],"a":1,"ex":"«Even though» = אף על פי ש. הוא התאמן חודשים, ובכל זאת לא סיים את המרוץ: זה ניגוד. «Since» (מכיוון ש) היה אומר שהאימונים הם הסיבה שלא סיים, וזה לא הגיוני.","w":[["even though","אף על פי ש..."],["since","מכיוון ש..."]]}]},{"type":"rc","title":"Trees on City Streets","text":["In many cities around the world, local governments plant thousands of trees along streets every year. At first, this may seem like a simple way to make neighborhoods look nicer. However, city planners say that street trees offer much more than beauty. They help people, buildings and even the city budget.","The most obvious benefit is shade. On a hot summer day, a sidewalk under a row of trees can be several degrees cooler than a sidewalk in full sun. Trees also release water through their leaves, and this water cools the air around them. As a result, people who live on green streets often use their air conditioners less, which lowers their electricity bills. In addition, leaves and roots catch rainwater, so less water floods the streets after a storm.","Street trees, however, are not free. A young tree must be watered regularly during its first few years, and older trees need to be cut back so that their branches do not hit buses or power lines. Roots can also cause problems. As they grow, they sometimes push up the sidewalk and damage pipes under the street. For this reason, some cities choose smaller trees for narrow streets, and they plant them in larger holes so that the roots have enough room.","Despite these costs, most studies find that street trees are a good investment. One city calculated that every dollar it spent on caring for its trees returned more than two dollars in savings, mainly from lower energy use and less damage from rainwater. Because of such findings, many cities now plan to plant even more trees in the coming years."],"qs":[{"q":"The passage mainly discusses","o":["how trees release water through their leaves","the benefits and the costs of trees along city streets","why some cities have stopped planting trees","the best kinds of trees for narrow streets"],"a":1,"ex":"הקטע מסביר את היתרונות של עצים ברחוב (צל, אוויר קריר, חיסכון) וגם את הבעיות והעלויות שלהם. שחרור מים דרך העלים הוא רק פרט אחד בפסקה 2, ולא הנושא של כל הקטע.","w":[["benefit","יתרון, תועלת"],["cost","עלות, מחיר"]]},{"q":"According to the second paragraph, people who live on green streets","o":["drive more often than other people","rarely go outside in the summer","must water the trees every day","often pay less for electricity"],"a":3,"ex":"בפסקה 2 כתוב שהם משתמשים פחות במזגן, ולכן חשבונות החשמל שלהם יורדים («lowers their electricity bills»). שאר התשובות לא כתובות בפסקה.","w":[["lower","להוריד, להפחית"],["bill","חשבון (לתשלום)"]]},{"q":"In the third paragraph, the word 'they' in 'As they grow' refers to","o":["branches","buses","roots","power lines"],"a":2,"ex":"המשפט שלפני אומר «Roots can also cause problems», ומיד אחריו «As they grow, they sometimes push up the sidewalk». השורשים הם אלה שגדלים, מרימים את המדרכה ופוגעים בצינורות.","w":[["root","שורש"],["damage","לפגוע, להזיק; נזק"]]},{"q":"The main purpose of the last paragraph is to","o":["show that street trees save more money than they cost","explain how roots damage pipes under the street","describe the work of watering young trees","suggest that cities should plant fewer trees"],"a":0,"ex":"הפסקה האחרונה אומרת שלמרות העלויות, העצים הם השקעה טובה: כל דולר מחזיר יותר משני דולרים. «plant fewer trees» הפוך ממה שכתוב, כי ערים מתכננות לשתול עוד עצים.","w":[["despite","למרות (+שם עצם)"],["investment","השקעה"]]},{"q":"According to the third paragraph, some cities plant trees in larger holes in order to","o":["keep the branches away from buses","make the trees grow more quickly","use less water for young trees","give the roots enough space"],"a":3,"ex":"בסוף פסקה 3 כתוב שהם שותלים בבורות גדולים יותר «so that the roots have enough room», כלומר כדי שלשורשים יהיה מספיק מקום. הענפים והאוטובוסים מוזכרים בפסקה, אבל קשורים לגיזום ולא לבורות.","w":[["in order to","כדי ל... (+פועל)"],["room","מקום, מרחב"]]}]},{"type":"rs","qs":[{"q":"Although the new phone is cheaper than the old model, most customers prefer the old one because its battery lasts longer.","o":["Most customers prefer the new phone, because it is cheaper and its battery lasts longer.","Since the new phone is cheaper than the old model, its battery also lasts longer than the old model's battery.","Most customers like the old model better since its battery lasts longer, even though the new phone costs less.","Few customers prefer the old model, although its battery lasts longer than the new phone's battery."],"a":2,"ex":"«Although» הוחלף ב-«even though», «prefer» ב-«like better» ו-«cheaper» ב-«costs less». המשמעות זהה: רוב הלקוחות מעדיפים את הדגם הישן בגלל הסוללה. «Few customers» (מעט לקוחות) הופך את «most» (רוב).","w":[["although","למרות ש... (+משפט)"],["even though","אף על פי ש..."],["prefer","להעדיף"]]},{"q":"If students do not hand in their projects by Thursday, they will not be allowed to take part in the science fair.","o":["Students may take part in the science fair only if they hand in their projects by Thursday.","Students who hand in their projects after Thursday will get extra time for the science fair.","Students will be allowed to take part in the science fair even if they hand in their projects late.","Because the science fair is on Thursday, students must hand in their projects before it starts."],"a":0,"ex":"«only if» = רק אם. מי שלא מגיש עד יום חמישי לא משתתף, כלומר משתתפים רק אם מגישים בזמן. «even if they hand in late» אומר את ההפך, והתשובה האחרונה מוסיפה מידע שלא היה (שהיריד ביום חמישי).","w":[["only if","רק אם"],["if","אם"],["hand in","להגיש"]]},{"q":"Fewer tourists visited the island this year, mainly because flights became much more expensive after the airline raised its prices.","o":["More tourists visited the island this year, even though flights became much more expensive after the airline raised its prices.","The main reason for the drop in the number of tourists on the island this year was the airline's higher prices.","The airline raised its prices this year mainly because fewer tourists wanted to fly to the island than in the past.","Flights to the island became much cheaper this year after the airline lowered its prices, so the number of tourists fell."],"a":1,"ex":"«Fewer tourists» הפך ל-«drop in the number of tourists» (ירידה במספר התיירים), ו-«mainly because» הפך ל-«the main reason». התשובה השלישית הופכת סיבה ותוצאה: לפי המקור המחירים גרמו לירידה, ולא להפך.","w":[["mainly","בעיקר"],["because","כי, מפני ש... (+משפט)"],["raise","להעלות"]]}]},{"type":"rs","qs":[{"q":"Many young people hardly ever read newspapers; instead, they get most of their news from short videos on social media.","o":["Many young people often read newspapers, and they also watch short news videos on social media every day.","Short videos on social media have made many young people more interested in reading newspapers than they used to be.","Newspapers are rarely read by older people, who get most of their news from short videos on social media.","Many young people rarely read newspapers; most of the news they receive comes from short videos on social media."],"a":3,"ex":"«hardly ever» = כמעט אף פעם לא, כמו «rarely». המשמעות נשמרת: צעירים כמעט לא קוראים עיתונים ומקבלים חדשות מסרטונים. בתשובה הראשונה «often» (לעיתים קרובות) הופך את המשמעות, ובשלישית מדובר באנשים מבוגרים במקום בצעירים.","w":[["hardly","כמעט לא"],["rarely","לעיתים רחוקות"],["instead","במקום זאת"]]},{"q":"The community center closed for six months so that workers could repair its roof, which had been damaged in a heavy storm.","o":["A heavy storm damaged the community center's roof, but the center stayed open for the whole six months while workers repaired it.","The community center was shut for six months in order to allow workers to fix the roof damaged in a heavy storm.","Workers accidentally damaged the roof of the community center during the six months that it was closed after a heavy storm.","The community center closed for six months because of a heavy storm, but workers will only repair its damaged roof next year."],"a":1,"ex":"«so that workers could repair» הפך ל-«in order to allow workers to fix»: שתיהן מילות מטרה. «closed» הפך ל-«was shut». בתשובה השלישית הפועלים הם שגרמו לנזק, וזה משנה מי עשה מה.","w":[["so that","כדי ש... (+משפט)"],["in order to","כדי ל... (+פועל)"],["repair","לתקן"]]},{"q":"Unlike her older brother, who enjoys cooking, Noa prefers to eat simple meals and rarely spends time in the kitchen.","o":["Noa seldom spends time in the kitchen and likes simple meals, whereas her older brother enjoys cooking.","Like her older brother, Noa enjoys cooking and often spends time in the kitchen.","Noa's older brother prefers simple meals, while Noa enjoys spending time in the kitchen.","Noa rarely spends time in the kitchen because her older brother does all the cooking for her."],"a":0,"ex":"«Unlike» (בניגוד ל) הוחלף ב-«whereas» (ואילו), ו-«rarely» ב-«seldom». שני המשפטים אומרים שאחיה אוהב לבשל והיא לא. התשובה השלישית מחליפה בין נועה לאחיה, והאחרונה מוסיפה סיבה שלא הייתה במקור.","w":[["unlike","בניגוד ל... (+שם עצם)"],["whereas","בעוד ש..., ואילו"],["seldom","לעיתים רחוקות"]]}]},{"type":"sc","qs":[{"q":"Our neighbors are very ___; they often bring us food from their garden and lend us tools without asking for anything.","o":["rude","lazy","generous","careless"],"a":2,"ex":"«generous» = נדיב. השכנים נותנים אוכל ומשאילים כלים בלי לבקש דבר בתמורה. «rude» (גס רוח) סותר את מה שמתואר אחרי הנקודה-פסיק.","w":[["generous","נדיב"],["lend","להשאיל"]]},{"q":"The factory put solar panels on its roof; ___ the sun, it now pays much less for electricity than it did five years ago.","o":["thanks to","instead of","in spite of","except for"],"a":0,"ex":"«thanks to» = הודות ל, בזכות. השמש היא הסיבה הטובה לכך שהמפעל משלם פחות על חשמל. «in spite of» (למרות) היה יוצר ניגוד, אבל השמש עוזרת לחסוך ולא מפריעה.","w":[["thanks to","הודות ל..., בזכות"],["in spite of","למרות (+שם עצם)"]]},{"q":"Before you buy a used car, it is wise to ___ it carefully to make sure that the engine and the brakes work well.","o":["ignore","borrow","paint","examine"],"a":3,"ex":"«examine» = לבדוק היטב. כדי לוודא שהמנוע והבלמים תקינים צריך לבדוק את המכונית. «ignore» (להתעלם) הפוך ממה שצריך לעשות.","w":[["examine","לבדוק, לבחון"],["wise","נבון, חכם"]]},{"q":"Some fruits, ___ bananas and oranges, have a thick skin, so they do not need to be washed before you eat them.","o":["unlike","such as","rather than","instead of"],"a":1,"ex":"«such as» = כגון, כמו. בננות ותפוזים הם דוגמאות לפירות עם קליפה עבה. «unlike» (בניגוד ל) היה אומר שלבננות ולתפוזים אין קליפה עבה, וזה לא נכון.","w":[["such as","כגון, כמו"],["unlike","בניגוד ל... (+שם עצם)"]]}]}]},{"id":"s3","title":"בינוני · מבחן 1","tier":1,"tierHe":"בינוני","hi":132,"chapters":[{"type":"sc","qs":[{"q":"Scientists warn that, unless action is taken soon, the loss of several coral reefs will become ___.","o":["reversible","voluntary","inevitable","temporary"],"a":2,"ex":"«inevitable» = בלתי נמנע. המדענים מזהירים שאם לא יפעלו מהר, האובדן של השוניות כמעט בטוח יקרה. «reversible» (הפיך) הפוך מהכוונה של האזהרה.","w":[["inevitable","בלתי נמנע"],["unless","אלא אם כן"]]},{"q":"The museum's new exhibition received poor reviews from critics; ___, it attracted a record number of visitors.","o":["nevertheless","consequently","similarly","for instance"],"a":0,"ex":"«nevertheless» = למרות זאת. הביקורות היו רעות, ובכל זאת הגיע מספר שיא של מבקרים: יש כאן ניגוד. «consequently» (כתוצאה מכך) לא מתאים, כי ביקורות רעות לא גורמות לשיא מבקרים.","w":[["nevertheless","למרות זאת, אף על פי כן"],["record","שיא"]]},{"q":"Rising rents have forced many young families to leave the city center, a trend that threatens to ___ the area's sense of community.","o":["strengthen","celebrate","imitate","undermine"],"a":3,"ex":"«undermine» = לערער, להחליש. עזיבת המשפחות הצעירות פוגעת בתחושת הקהילה, ולכן המגמה «מאיימת לערער» אותה. «strengthen» (לחזק) הפוך: מגמה מאיימת לא מחזקת.","w":[["undermine","לערער, להחליש"],["threaten","לאיים"]]},{"q":"Few of the volunteers could afford a car, ___ a house of their own.","o":["rather than","let alone","in order to","as well as"],"a":1,"ex":"«let alone» = ובטח שלא, קל וחומר. רובם לא יכלו להרשות לעצמם אפילו מכונית, ובטח שלא בית, שהוא יקר הרבה יותר. «as well as» (וגם) לא מוסיף את הרעיון של «ובטח שלא», שהוא כל הטעם של המשפט.","w":[["let alone","ובטח שלא, קל וחומר"],["afford","להרשות לעצמו (כלכלית)"]]}]},{"type":"sc","qs":[{"q":"The professor's theory was once rejected by most of her colleagues, but today it enjoys ___ support across the field.","o":["reluctant","widespread","scarce","hidden"],"a":1,"ex":"«widespread» = נפוץ, רחב. פעם רוב העמיתים דחו את התיאוריה, «but» היום היא נהנית מתמיכה רחבה: זה הניגוד ש-«but» דורש. «scarce» (מועט) לא יוצר ניגוד לעבר.","w":[["widespread","נפוץ, רחב היקף"],["reject","לדחות"]]},{"q":"The northern region receives heavy rainfall throughout the year, ___ the south remains dry for most months.","o":["so that","because","unless","whereas"],"a":3,"ex":"«whereas» = ואילו, בעוד ש. משווים בין הצפון הגשום לדרום היבש, כלומר ניגוד בין שני צדדים. «because» היה אומר שהגשם בצפון גורם ליובש בדרום, וזה לא הגיוני.","w":[["whereas","בעוד ש..., ואילו"],["throughout","לאורך, במשך כל"]]},{"q":"Children who grow up speaking two languages often ___ a third one more easily than those who speak only one.","o":["acquire","abandon","ignore","conceal"],"a":0,"ex":"«acquire» = לרכוש (ידע, שפה). ילדים דו-לשוניים לומדים שפה שלישית בקלות רבה יותר. «abandon» (לנטוש) לא מתאים ל-«more easily» ולהקשר של יתרון.","w":[["acquire","לרכוש"],["abandon","לנטוש, לזנוח"]]},{"q":"The bridge had not been inspected for over a decade; ___, nobody was surprised when engineers declared it unsafe.","o":["in contrast","even so","consequently","otherwise"],"a":2,"ex":"«consequently» = כתוצאה מכך. הגשר לא נבדק יותר מעשר שנים, ולכן אף אחד לא הופתע שהוכרז מסוכן: סיבה ותוצאה. «even so» (למרות זאת) היה רומז שהיה צפוי שיופתעו, וזה הפוך.","w":[["consequently","כתוצאה מכך, לפיכך"],["inspect","לבדוק, לפקח"]]}]},{"type":"rc","title":"The Story That Changes Each Time","text":["Most people assume that a memory works like a recording: once an event is stored, it can be played back whenever it is needed. Psychologists who study memory, however, have found that this common belief is largely mistaken. Rather than retrieving a fixed copy, the brain rebuilds an experience each time we recall it, using fragments of the original event together with our current knowledge, feelings and expectations. As a result, a story that we have told many times may differ substantially from what actually happened.","One explanation for this effect is a process known as reconsolidation. When a memory is brought to mind, it becomes unstable for a short period before it is stored again. During this window, new information can be added and old details can be lost. If, for example, a listener reacts with surprise to a particular part of a story, the speaker may emphasize that part the next time and gradually drop details that seemed less interesting. Each retelling, in other words, becomes the new \"original.\"","Experiments support this idea. In one type of study, volunteers watch a short film and are later asked to describe it to different listeners. Those who describe it to a listener who is believed to dislike the main character tend to present that character more negatively. Weeks later, even when asked to recall the film itself rather than their own description, they still remember the character in the less favorable way. Their memory has apparently been shaped by the version they chose to tell.","These findings have important consequences. In courts, witnesses who have repeated their account many times may feel highly confident even though their memories have shifted. Nevertheless, researchers stress that the flexibility of memory is not simply a flaw. A system that constantly updates itself allows people to connect past experiences to new situations and to learn from them. The price of this flexibility is that our most cherished stories are, to some degree, always being rewritten."],"qs":[{"q":"Which of the following is the best title for the passage?","o":["Why Children Forget Their Early Years","How Retelling a Story Reshapes Our Memories","The Role of Witnesses in Modern Courts","A Simple Method for Improving Memory"],"a":1,"ex":"הקטע כולו עוסק בכך שכל פעם שמספרים סיפור, הזיכרון נבנה מחדש ומשתנה. עדים בבית משפט מוזכרים רק בפסקה האחרונה כדוגמה, ולכן זו לא כותרת לכל הקטע.","w":[["retell","לספר מחדש"],["reshape","לעצב מחדש"]]},{"q":"According to the second paragraph, while a memory is being recalled, it","o":["is permanently erased from the brain","becomes more accurate than before","is passed on unchanged to the listener","can be altered before it is stored again"],"a":3,"ex":"בפסקה 2 כתוב שכשנזכרים, הזיכרון «becomes unstable» לזמן קצר לפני שהוא נשמר שוב, ובחלון הזה אפשר להוסיף פרטים ולאבד אחרים. אין שם טענה שהוא נמחק לגמרי או נעשה מדויק יותר.","w":[["unstable","לא יציב"],["alter","לשנות"]]},{"q":"In paragraph 3, the word \"Their\" (in \"Their memory has apparently been shaped\") refers to","o":["the listeners","the main characters","the volunteers","the films"],"a":2,"ex":"המשפט מתאר את המתנדבים שתיארו את הסרט, ושאחרי שבועות זכרו את הדמות באופן שלילי יותר. «Their memory» = הזיכרון של המתנדבים. המאזינים לא זוכרים את הסרט, כי הם לא ראו אותו.","w":[["volunteer","מתנדב"],["apparently","ככל הנראה"]]},{"q":"What does the experiment described in paragraph 3 suggest?","o":["The way people describe an event can later change how they remember it.","People remember films more accurately than real-life events.","Listeners usually adopt the speaker's opinion of a character.","Volunteers deliberately lied in order to please their listeners."],"a":0,"ex":"המתנדבים שתיארו את הדמות באופן שלילי זכרו אותה כך גם שבועות אחר כך, «even when asked to recall the film itself». כלומר הגרסה שסיפרו שינתה את הזיכרון. לא נאמר שהם שיקרו בכוונה.","w":[["favorable","חיובי, אוהד"],["deliberately","בכוונה"]]},{"q":"The main purpose of the last paragraph is to","o":["describe a new experiment carried out on witnesses","prove that human memory should never be trusted","point out both a practical risk and an advantage of memory's flexibility","argue that courts should stop relying on witnesses"],"a":2,"ex":"הפסקה האחרונה מציגה סיכון (עדים בטוחים בעצמם למרות שהזיכרון שלהם השתנה), ואז «Nevertheless» מביאה יתרון: גמישות שמאפשרת ללמוד. «should never be trusted» קיצוני מדי, כי נאמר במפורש שזה «not simply a flaw».","w":[["nevertheless","למרות זאת, אף על פי כן"],["flaw","פגם"]]}]},{"type":"rs","qs":[{"q":"Although the new medication reduced symptoms in most patients, doctors remain cautious because its long-term effects have not yet been studied in sufficient depth.","o":["Because the new medication reduced symptoms in most patients, doctors are confident that its long-term effects will also be safe for them.","The new medication helped only a few patients, so doctors will remain cautious until its long-term effects are studied in depth.","Doctors have stopped prescribing the new medication to most patients, since recent studies have shown that its long-term effects are harmful.","Doctors are still careful about the new medication, even though it helped most patients, since its long-term effects have not been studied enough."],"a":3,"ex":"במקור: התרופה עזרה לרוב החולים, אבל הרופאים זהירים כי ההשפעות ארוכות הטווח לא נחקרו מספיק. התשובה הנכונה מחליפה «Although» ב-«even though» ומשנה את סדר החלקים. «only a few patients» משנה את הכמות (במקור «most»).","w":[["cautious","זהיר"],["even though","אף על פי ש..."],["sufficient","מספיק"]]},{"q":"The ancient city was eventually abandoned, not because of a sudden invasion, as was once widely believed, but as a result of a slow decline in its water supply.","o":["Contrary to a once common view, a gradual shortage of water, rather than an unexpected attack, finally led people to leave the ancient city.","As was once widely believed, the ancient city was abandoned after a sudden invasion by its enemies, which also damaged its water supply.","Many people once believed that the ancient city had a serious water problem, but it was actually destroyed by invaders who attacked it suddenly.","Although its water supply was declining slowly, the ancient city was never abandoned by its people, who found new sources of water nearby."],"a":0,"ex":"במקור: העיר ננטשה לא בגלל פלישה, כפי שחשבו פעם, אלא בגלל ירידה איטית באספקת המים. התשובה הנכונה אומרת את זה עם «rather than» ועם «Contrary to a once common view». האפשרויות על הפולשים הופכות את הסיבה.","w":[["abandon","לנטוש"],["as a result of","כתוצאה מ..."],["rather than","במקום, ולא"]]},{"q":"Few employees took advantage of the flexible working hours, since most of them feared that their managers would regard it as a lack of commitment.","o":["Many employees used the flexible working hours, although they feared that their managers would view it as a lack of commitment.","Worried that their managers might see it as low commitment, only a small number of employees used the flexible working hours.","Most managers feared that employees who used the flexible hours would show a lack of commitment, so they cancelled the option.","Because their managers already considered them uncommitted to the company, only a few employees were ever offered the chance to work flexible hours."],"a":1,"ex":"«Few» = מעט מאוד עובדים השתמשו בשעות הגמישות, כי פחדו שהמנהלים יראו בזה חוסר מחויבות. התשובה הנכונה מעבירה את הסיבה לתחילת המשפט ואומרת «only a small number». «Many employees» הופך את הכמות.","w":[["few","מעט (כמעט אין)"],["take advantage of","לנצל, להשתמש ב..."],["commitment","מחויבות"]]}]},{"type":"rs","qs":[{"q":"Even though online courses are cheaper and more convenient, many students still prefer traditional classes, in which they can interact directly with teachers and classmates.","o":["Because online courses are cheaper and more convenient, most students have stopped attending traditional classes and now study only from home.","Many students now prefer online courses to traditional classes, since online courses allow them to interact more directly with teachers and classmates.","Many students still choose traditional classes, which allow face-to-face contact with teachers and classmates, despite the lower cost and greater convenience of online courses.","Traditional classes are actually cheaper and more convenient than online courses, so many students still prefer them in order to meet their teachers."],"a":2,"ex":"במקור: למרות שקורסים מקוונים זולים ונוחים יותר, הרבה סטודנטים עדיין מעדיפים כיתות רגילות, שבהן יש קשר ישיר עם המרצים. התשובה הנכונה מחליפה «Even though» ב-«despite» ומעבירה אותו לסוף. האפשרות הראשונה הופכת את הוויתור לסיבה.","w":[["even though","אף על פי ש..."],["despite","למרות (+שם עצם)"],["still","ובכל זאת; עדיין"]]},{"q":"The government introduced a tax on sugary drinks so as to reduce their consumption, and within two years, sales of such drinks had fallen considerably.","o":["The government decided to introduce a tax on sugary drinks because their sales had already fallen considerably over the previous two years.","In order to cut consumption of sugary drinks, a tax was placed on them by the government; within two years, sales had dropped sharply.","Although the government taxed sugary drinks in order to reduce their consumption, sales of these drinks hardly changed at all within the next two years.","Drink companies themselves raised the price of sugary drinks so as to reduce their consumption, and within two years sales had fallen considerably."],"a":1,"ex":"במקור: הממשלה הטילה מס על משקאות ממותקים כדי להפחית את הצריכה, ותוך שנתיים המכירות ירדו מאוד. התשובה הנכונה עוברת לסביל («a tax was placed on them by the government») ו-«so as to» הופך ל-«In order to». באפשרות הראשונה הירידה במכירות היא הסיבה למס, וזה הפוך.","w":[["so as to","כדי ל..."],["in order to","כדי ל... (+פועל)"],["considerably","במידה ניכרת"]]},{"q":"Whereas earlier researchers relied mainly on questionnaires, today's scientists can observe brain activity directly, which allows them to test theories that were once impossible to examine.","o":["Both earlier and modern researchers have relied mainly on questionnaires rather than on brain activity, which is why some important theories still cannot be tested today.","Today's scientists still rely mainly on questionnaires, just as earlier researchers did, since observing brain activity directly has turned out to be impossible.","Earlier researchers were able to observe brain activity directly, whereas today's scientists prefer to use questionnaires in order to test theories that were once impossible to examine.","Unlike past researchers, who depended mostly on questionnaires, modern scientists can watch the brain at work, which lets them test theories that could not be tested before."],"a":3,"ex":"במקור: חוקרים בעבר הסתמכו בעיקר על שאלונים, ואילו היום אפשר לצפות במוח ישירות ולבדוק תיאוריות שלא היה אפשר לבדוק קודם. התשובה הנכונה מחליפה «Whereas» ב-«Unlike». האפשרות השלישית מחליפה בין העבר להווה.","w":[["whereas","בעוד ש..., ואילו"],["unlike","בניגוד ל... (+שם עצם)"],["rely","להסתמך"]]}]},{"type":"sc","qs":[{"q":"The two reports differ ___ in their conclusions: one predicts steady growth, while the other predicts a deep recession.","o":["substantially","slightly","barely","equally"],"a":0,"ex":"«substantially» = באופן משמעותי. דוח אחד צופה צמיחה והשני מיתון עמוק, כלומר הבדל גדול. «slightly» (מעט) ו-«barely» (בקושי) סותרים את ההבדל החד שמתואר אחרי הנקודתיים.","w":[["substantially","באופן משמעותי, ניכר"],["recession","מיתון"]]},{"q":"The athlete continued to train every morning ___ she had been told by her doctor to rest.","o":["so that","as long as","even though","in case"],"a":2,"ex":"«even though» = אף על פי ש. הרופא אמר לה לנוח, ובכל זאת היא המשיכה להתאמן: ויתור. «as long as» (כל עוד) היה הופך את הוראת הרופא לתנאי לאימון, וזה לא הגיוני.","w":[["even though","אף על פי ש..."],["as long as","כל עוד, בתנאי ש..."]]},{"q":"Since the original documents were destroyed in a fire, historians are forced to ___ later copies whose accuracy cannot be fully confirmed.","o":["do without","dispose of","apply for","rely on"],"a":3,"ex":"«rely on» = להסתמך על. המסמכים המקוריים נשרפו, ולכן ההיסטוריונים נאלצים להסתמך על העותקים המאוחרים. «do without» (להסתדר בלי) הפוך: אין להם ברירה אלא להשתמש בעותקים.","w":[["rely on","להסתמך על"],["accuracy","דיוק"]]},{"q":"Many students record their lectures ___ review the material later at their own pace.","o":["let alone","so as to","rather than","so as not to"],"a":1,"ex":"«so as to» = כדי ל. מקליטים את ההרצאה כדי לחזור על החומר אחר כך: מטרה. «so as not to» אומר «כדי לא לחזור על החומר», וזה הפוך מהסיבה שמקליטים. «rather than» (במקום) ו-«let alone» (ועל אחת כמה וכמה לא) לא מתאימים למשמעות.","w":[["so as to","כדי ל..."],["at one's own pace","בקצב של עצמו"]]}]}]},{"id":"s7","title":"בינוני · מבחן 2","tier":1,"tierHe":"בינוני","hi":132,"chapters":[{"type":"sc","qs":[{"q":"The committee's report was truly ___: it covered every aspect of the problem and left no important question unanswered.","o":["superficial","comprehensive","ambiguous","premature"],"a":1,"ex":"«comprehensive» = מקיף. אחרי הנקודתיים מוסבר שהדוח כיסה כל היבט ולא השאיר שאלה פתוחה, כלומר הוא מקיף. «superficial» (שטחי) אומר בדיוק את ההפך.","w":[["comprehensive","מקיף"],["superficial","שטחי"],["aspect","היבט"]]},{"q":"Many small shops in the old market have closed in recent years, ___ the rise of large supermarkets on the edge of town.","o":["in spite of","regardless of","instead of","owing to"],"a":3,"ex":"«owing to» = בשל, עקב. עליית הסופרמרקטים הגדולים היא הסיבה לסגירת החנויות הקטנות. «in spite of» (למרות) היה אומר שהחנויות נסגרו למרות הסופרמרקטים, וזה לא הגיוני.","w":[["owing to","בשל, עקב"],["in spite of","למרות (+שם עצם)"]]},{"q":"The ancient manuscript is extremely ___, so visitors are allowed to view it only through a sealed glass case.","o":["fragile","durable","ordinary","accessible"],"a":0,"ex":"«fragile» = שביר, עדין. בגלל שכתב היד עדין, מותר להסתכל עליו רק מבעד לזכוכית. «durable» (עמיד) הוא ההפך, ואז לא הייתה סיבה להגן עליו.","w":[["fragile","שביר, עדין"],["durable","עמיד"],["manuscript","כתב יד"]]},{"q":"The new policy was meant to reduce traffic in the city center; ___, it simply moved the congestion to the surrounding neighborhoods.","o":["likewise","furthermore","accordingly","instead"],"a":3,"ex":"«instead» = במקום זאת. המדיניות הייתה אמורה להפחית את התנועה, ובמקום זה רק העבירה את הפקקים לשכונות אחרות. «accordingly» (בהתאם לכך) מציג תוצאה צפויה, אבל כאן התוצאה הפוכה למטרה.","w":[["instead","במקום זאת"],["congestion","עומס, פקקים"],["accordingly","בהתאם לכך, לכן"]]}]},{"type":"sc","qs":[{"q":"The witness's description of the accident was so ___ that the police could not tell which car had entered the junction first.","o":["precise","vague","detailed","reliable"],"a":1,"ex":"«vague» = מעורפל, לא ברור. בגלל שהעדות הייתה מעורפלת, המשטרה לא הצליחה לקבוע מי נכנס ראשון לצומת. «precise» ו-«detailed» (מדויק, מפורט) היו מאפשרים לקבוע בדיוק את זה.","w":[["vague","מעורפל, לא ברור"],["precise","מדויק"]]},{"q":"Students may submit their essays after the deadline, ___ they inform the lecturer in advance and explain the reason for the delay.","o":["so that","unless","provided that","even though"],"a":2,"ex":"«provided that» = בתנאי ש. מותר להגיש באיחור בתנאי שמודיעים מראש. «unless» (אלא אם כן) היה אומר שמי שמודיע מראש דווקא לא יכול להגיש באיחור, וזה הפוך.","w":[["provided that","בתנאי ש..."],["unless","אלא אם כן"],["in advance","מראש"]]},{"q":"In order to ___ the spread of the disease, the authorities closed schools and banned large public gatherings.","o":["encourage","describe","curb","predict"],"a":2,"ex":"«curb» = לרסן, לבלום. סגירת בתי ספר ואיסור התקהלויות נועדו לבלום את התפשטות המחלה. «encourage» (לעודד) הוא ההפך הגמור.","w":[["curb","לרסן, לבלום"],["in order to","כדי ל... (+פועל)"],["ban","לאסור"]]},{"q":"The professor rarely praises her students' work; ___, when she called one thesis \"excellent\", everyone understood how impressive it must have been.","o":["otherwise","for instance","similarly","hence"],"a":3,"ex":"«hence» = מכאן, ולכן. מכיוון שהיא כמעט אף פעם לא משבחת, כולם הבינו שאם שיבחה, העבודה באמת מצוינת: זו תוצאה. «for instance» (למשל) לא מתאים, כי שבח הוא לא דוגמה לכך שהיא כמעט לא משבחת.","w":[["hence","מכאן, ולכן"],["rarely","לעיתים רחוקות"],["praise","לשבח"]]}]},{"type":"rc","title":"The Language of the Hive","text":["For centuries, beekeepers noticed that once a single honeybee discovers a rich patch of flowers, many others from the same hive soon arrive there. How the first bee manages to share this information remained a puzzle, since bees can neither draw maps nor point the way. The answer, it turned out, lay in a series of movements that the returning bee performs on the vertical walls of the hive, in the dark.","The scientist who decoded these movements was the Austrian biologist Karl von Frisch. Beginning in the 1920s, he trained bees to visit dishes of sugar water and watched them through glass-walled hives. He observed that when the food was close to the hive, the returning bee simply ran around in small circles. When the food was farther away, however, she performed what he called a \"waggle dance\": she ran forward in a straight line while shaking her body from side to side, then circled back and repeated the run.","After years of measurement, von Frisch realized that each part of the dance carried a precise message. The angle of the straight run, measured against the vertical, matched the angle between the food source and the sun. A bee running straight upward was telling her sisters to fly directly toward the sun, while a run tilted to the right indicated a direction to the right of it. The length of the waggling, in turn, signaled distance: the longer it lasted, the farther away the flowers were.","Not every scientist accepted these conclusions. In the 1960s, several researchers argued that bees located food mainly by following its smell, and that the dance was merely a sign of excitement. The debate was finally settled decades later, when engineers placed a small dancing robot bee inside a hive. Bees that watched the robot flew in the direction and to the distance it had indicated, even though the robot had never visited any flowers. Von Frisch, who shared the Nobel Prize in 1973, did not live to see this proof that the dancer is, in effect, giving directions."],"qs":[{"q":"Which of the following is the best title for the passage?","o":["How Flowers Attract Honeybees","The Early Life of Karl von Frisch","Cracking the Code of the Honeybee Dance","Why Bees Prefer Sugar Water"],"a":2,"ex":"כל הקטע עוסק בריקוד של הדבורים: מה השאלה, איך פון פריש פענח את המשמעות שלו, ואיך הממצא אושר. «The Early Life of Karl von Frisch» מפתה, אבל הקטע לא מספר על חייו, רק על המחקר שלו.","w":[["decode","לפענח"],["crack a code","לפצח צופן"]]},{"q":"According to paragraph 2, a bee that has found food very close to the hive","o":["runs around in small circles","shakes her body while running in a straight line","leads the other bees to the food herself","does not return to the hive at all"],"a":0,"ex":"בפסקה 2 כתוב שכשהאוכל קרוב לכוורת, הדבורה רק רצה במעגלים קטנים. ריצה בקו ישר עם ניעור הגוף («waggle dance») מתוארת רק כשהאוכל רחוק יותר.","w":[["observe","להבחין, לצפות"],["farther","רחוק יותר"]]},{"q":"Based on paragraph 3, a bee whose straight run points directly downward is most probably indicating food that is","o":["very close to the hive","exactly in the direction of the sun","slightly to the right of the sun","in the opposite direction from the sun"],"a":3,"ex":"לפי פסקה 3, ריצה ישר למעלה פירושה לעוף ישר לכיוון השמש. לכן ריצה ישר למטה (הכיוון ההפוך) פירושה לעוף בכיוון ההפוך לשמש. «exactly in the direction of the sun» מתאים לריצה למעלה, לא למטה.","w":[["indicate","להצביע על, לסמן"],["opposite","הפוך, נגדי"],["tilted","נטוי, מוטה"]]},{"q":"In paragraph 4, the word \"settled\" (in \"The debate was finally settled\") could best be replaced by","o":["started","resolved","ignored","repeated"],"a":1,"ex":"«settled» כאן = הוכרע, נפתר. הוויכוח הוכרע כשניסוי רובוט הדבורה הראה שהריקוד מעביר הוראות. «started» (התחיל) לא נכון, כי הוויכוח התחיל כבר בשנות ה-60.","w":[["settle","להכריע, ליישב (ויכוח)"],["resolve","לפתור, ליישב"],["debate","ויכוח, דיון"]]},{"q":"The main purpose of the last paragraph is to","o":["explain why bees are attracted to the smell of flowers","describe how robots are used to protect beehives","present a challenge to von Frisch's findings and show how it was answered","argue that von Frisch did not deserve the Nobel Prize"],"a":2,"ex":"הפסקה האחרונה מציגה חוקרים שפקפקו בממצאים (טענו שהדבורים מוצאות אוכל לפי ריח), ואז מספרת איך ניסוי הרובוט הכריע את הוויכוח. «explain why bees are attracted to the smell» מפתה, אבל הריח מוזכר רק כטענה של המתנגדים.","w":[["challenge","ערעור, אתגר"],["proof","הוכחה"],["merely","רק, לא יותר מ..."]]}]},{"type":"rs","qs":[{"q":"Although the city's population has nearly doubled over the past thirty years, the number of public libraries has remained the same, leaving many neighborhoods without one.","o":["Because the city's population has nearly doubled over the past thirty years, the number of public libraries has also grown, so every neighborhood now has one.","Despite the fact that the city's population has almost doubled in thirty years, no public libraries have been added, so many neighborhoods still have none.","The city's population has hardly changed in thirty years, which explains why no new public libraries have been built in its neighborhoods.","Although many public libraries have opened over the past thirty years, the city's growing population still leaves a few neighborhoods without one."],"a":1,"ex":"במקור: האוכלוסייה כמעט הוכפלה, אבל מספר הספריות לא השתנה, ולכן בהרבה שכונות אין ספרייה. התשובה הנכונה מחליפה «Although» ב-«Despite the fact that». האפשרות הראשונה הופכת את ההיגיון (הספריות גדלו), והשלישית משנה את הכמות («hardly changed»).","w":[["although","למרות ש... (+משפט)"],["despite","למרות (+שם עצם)"],["hardly","כמעט לא"]]},{"q":"The company decided to delay the launch of its new phone in order to fix a battery problem that had been discovered only a week before the planned date.","o":["The company launched its new phone on the planned date as promised, although a serious battery problem had been discovered only a week earlier.","A battery problem in the company's new phone was actually caused by the decision to delay its launch until a week after the planned date.","The company postponed the launch of its new phone for a week because customers in a preview program had complained about its battery.","The company's new phone launch was postponed so that a battery fault found just a week before the due date could be repaired."],"a":3,"ex":"במקור: החברה דחתה את ההשקה כדי לתקן תקלה בסוללה שהתגלתה שבוע לפני המועד. התשובה הנכונה עוברת לסביל («was postponed») ומחליפה «in order to» ב-«so that». האפשרות השנייה הופכת סיבה ותוצאה, והשלישית מוסיפה תלונות של לקוחות שלא מופיעות במקור.","w":[["in order to","כדי ל... (+פועל)"],["so that","כדי ש... (+משפט)"],["postpone","לדחות"]]},{"q":"Only a small minority of the patients who took part in the study reported side effects, and in most of those cases the symptoms disappeared within a few days.","o":["Few of the study's participants said they suffered side effects, and these generally lasted no longer than a few days.","Most of the patients in the study reported side effects, although these usually disappeared within a few days.","A small number of patients reported side effects, and in every case the symptoms lasted for several weeks.","Only a few patients agreed to take part in the study, because most of them were afraid of its side effects."],"a":0,"ex":"במקור: רק מעטים דיווחו על תופעות לוואי, ובדרך כלל הן עברו תוך כמה ימים. «Few» מחליף את «a small minority», ו-«generally» מחליף את «in most of those cases». האפשרות השנייה משנה את הכמות («Most»), והשלישית משנה את משך התסמינים.","w":[["minority","מיעוט"],["few","מעט (כמעט אין)"],["side effects","תופעות לוואי"]]}]},{"type":"rs","qs":[{"q":"Unless the dam is repaired before the rainy season begins, engineers warn, the nearby villages could be flooded, forcing thousands of residents to leave their homes.","o":["Engineers warn that repairing the dam before the rainy season could itself cause flooding in the nearby villages and force thousands of residents to leave.","Because the dam was not repaired before the rainy season began, thousands of residents of the nearby villages have already been forced to leave their homes.","According to engineers, if the dam is not fixed before the rains start, nearby villages may flood and thousands of people may have to leave.","Engineers say that even if the dam is repaired in time, the nearby villages will still be flooded during the rainy season."],"a":2,"ex":"«Unless» = אלא אם כן, כלומר «if ... not». התשובה הנכונה אומרת: אם הסכר לא יתוקן לפני הגשמים, הכפרים עלולים להיות מוצפים. האפשרות השנייה מתארת משהו שכבר קרה, בעוד שבמקור זו רק אזהרה לעתיד, והרביעית («even if») משנה את התנאי.","w":[["unless","אלא אם כן"],["even if","גם אם, אפילו אם"],["resident","תושב"]]},{"q":"Unlike most birds, which build a new nest every year, eagles often return to the same nest for decades, adding fresh material to it each season.","o":["Like most other birds, eagles build a completely new nest every year, often using material taken from the old nests they have abandoned.","Eagles rarely return to the same nest year after year, since most birds, unlike them, add new material to their nests each season.","Most birds return to the same nest for decades and add fresh material to it, whereas eagles prefer to build a new one each year.","Eagles frequently use the same nest for many years, adding new material each season, while most other birds build a new one annually."],"a":3,"ex":"«Unlike» = בניגוד ל. התשובה הנכונה מחליפה אותו ב-«while» ומשנה את סדר החלקים, אבל המשמעות זהה: נשרים חוזרים לאותו קן, ורוב הציפורים בונות קן חדש. האפשרות השלישית מחליפה בין הנשרים לשאר הציפורים, והראשונה הופכת ניגוד לדמיון («Like»).","w":[["unlike","בניגוד ל... (+שם עצם)"],["while","בעוד ש... (ניגוד)"],["annually","מדי שנה"]]},{"q":"The researchers' findings were not published for several years, mainly because the journal's editors doubted whether such a small sample could support such a bold conclusion.","o":["The journal's editors published the researchers' findings immediately, although they privately doubted whether such a small sample could really support so bold a conclusion.","The main reason the researchers' findings remained unpublished for years was that the editors questioned whether so small a sample could justify so bold a conclusion.","The researchers chose to delay publishing their findings for several years because they wanted to collect a much larger sample before drawing such a bold conclusion.","The researchers' findings were finally published after several years, once the journal's editors realized that the sample was much larger than they had thought."],"a":1,"ex":"במקור: המאמר לא פורסם שנים, בעיקר כי העורכים פקפקו אם מדגם קטן יכול לתמוך במסקנה נועזת. התשובה הנכונה מחליפה «mainly because» ב-«The main reason ... was that». האפשרות השלישית משנה מי עשה מה: כאן החוקרים עצמם דחו את הפרסום.","w":[["doubt","לפקפק"],["bold","נועז"],["sample","מדגם"]]}]},{"type":"sc","qs":[{"q":"The two species of frog look almost identical; ___, genetic tests show that they separated from each other millions of years ago.","o":["however","therefore","for example","in addition"],"a":0,"ex":"«however» = עם זאת. הצפרדעים נראות כמעט זהות, אבל הבדיקות הגנטיות מראות שהן נפרדו מזמן: זה ניגוד. «therefore» (לכן) לא מתאים, כי מראה זהה לא מוביל למסקנה שהן רחוקות זו מזו.","w":[["however","עם זאת, אולם"],["identical","זהה"],["species","מין (בביולוגיה)"]]},{"q":"The architect insisted on using local stone ___ imported materials, arguing that it suited the region's hot climate far better.","o":["as well as","rather than","such as","along with"],"a":1,"ex":"«rather than» = במקום, ולא. האדריכל העדיף אבן מקומית על פני חומרים מיובאים, כי לטענתו היא מתאימה יותר לאקלים. «as well as» (וגם) היה אומר שהשתמש בשניהם, וזה סותר את ההעדפה.","w":[["rather than","במקום, ולא"],["insist on","להתעקש על"],["imported","מיובא"]]},{"q":"Although scientists had long ___ that the lakes in the region were shrinking, they lacked clear proof until satellite images became available.","o":["demonstrated","denied","suspected","established"],"a":2,"ex":"«suspected» = חשדו. המדענים חשדו שהאגמים מצטמקים, אבל לא הייתה להם הוכחה. «demonstrated» ו-«established» (הוכיחו, ביססו) סותרים את זה שלא הייתה הוכחה.","w":[["suspect","לחשוד"],["demonstrate","להוכיח, להראות"],["lack","לחסור, להיות חסר"]]},{"q":"The new trade agreement is expected to be ___ beneficial, since both countries will gain access to markets that were previously closed to them.","o":["mutually","hardly","unequally","rarely"],"a":0,"ex":"«mutually» = הדדית. ההסכם מועיל לשני הצדדים, כי שתי המדינות ירוויחו גישה לשווקים חדשים. «hardly» (כמעט לא) סותר את ההסבר שאחרי «since».","w":[["mutually","הדדית"],["beneficial","מועיל"],["previously","קודם לכן, בעבר"]]}]}]},{"id":"s8","title":"בינוני · מבחן 3","tier":1,"tierHe":"בינוני","hi":132,"chapters":[{"type":"sc","qs":[{"q":"The committee's final report was so ___ that even experts in the field struggled to follow its main argument.","o":["concise","obscure","accessible","entertaining"],"a":1,"ex":"«obscure» = לא ברור, מעורפל. אם אפילו מומחים התקשו לעקוב אחרי הטיעון, הדוח היה לא ברור. «concise» (תמציתי) ו-«accessible» (נגיש) אומרים את ההפך: דוח כזה קל להבנה.","w":[["obscure","לא ברור, מעורפל"],["struggle","להתקשות, להיאבק"],["concise","תמציתי"]]},{"q":"The company did not announce any layoffs this year; ___, it hired two hundred new workers last month.","o":["on the contrary","as a result","for instance","otherwise"],"a":0,"ex":"«on the contrary» = להפך. החברה לא פיטרה, ולהפך: היא אפילו גייסה עובדים חדשים. «as a result» (כתוצאה מכך) לא מתאים, כי היעדר פיטורים לא גורם לגיוס של מאתיים עובדים.","w":[["on the contrary","להפך (דוחה את מה שנאמר)"],["layoff","פיטורים"]]},{"q":"To ___ the spread of the disease, health officials closed schools and banned large public gatherings.","o":["accelerate","document","curb","justify"],"a":2,"ex":"«curb» = לרסן, לבלום. סוגרים בתי ספר ואוסרים התקהלויות כדי לבלום את התפשטות המחלה. «accelerate» (להאיץ) הוא ההפך הגמור ממה שהפקידים רצו.","w":[["curb","לרסן, לבלום"],["spread","התפשטות"],["accelerate","להאיץ"]]},{"q":"The new phone sold out within hours, ___ its unusually high price and a number of poor reviews.","o":["because of","in spite of","in order to","instead of"],"a":1,"ex":"«in spite of» = למרות. מחיר גבוה וביקורות רעות היו אמורים להרחיק קונים, ובכל זאת הטלפון אזל: זה ויתור. «because of» (בגלל) לא הגיוני, כי ביקורות רעות לא גורמות למכירות.","w":[["in spite of","למרות (+שם עצם)"],["sell out","לאזול מהמלאי"]]}]},{"type":"sc","qs":[{"q":"The witness's account was ___ by security camera footage, which showed exactly what she had described.","o":["contradicted","exaggerated","verified","postponed"],"a":2,"ex":"«verified» = אומת. המצלמה הראתה בדיוק את מה שהעדה תיארה, ולכן הסרטון אישר את דבריה. «contradicted» (הוכחש, נסתר) היה מתאים רק אם הסרטון היה מראה משהו אחר.","w":[["verify","לאמת"],["account","תיאור, דיווח"],["contradict","לסתור"]]},{"q":"___ the region's mild climate, it attracts thousands of retirees every winter.","o":["Owing to","Regardless of","Unlike","Apart from"],"a":0,"ex":"«Owing to» = בשל, עקב. האקלים הנוח הוא הסיבה שפנסיונרים מגיעים בחורף. «Regardless of» (בלי קשר ל...) מנתק את הקשר בין האקלים לבין המבקרים, וזה לא הגיוני.","w":[["owing to","בשל, עקב"],["mild","מתון, נוח"],["retiree","פנסיונר"]]},{"q":"Although the two paintings look ___ at first glance, a closer look reveals dozens of small differences.","o":["distinct","ancient","valuable","identical"],"a":3,"ex":"«identical» = זהים. «Although» מראה ניגוד: במבט ראשון הציורים נראים זהים, אבל מקרוב יש הבדלים. «distinct» (שונים זה מזה) לא יוצר ניגוד להבדלים, ולכן לא מתאים ל-«Although».","w":[["identical","זהה"],["although","למרות ש... (+משפט)"],["reveal","לחשוף, לגלות"]]},{"q":"Visitors may enter the nature reserve ___ they stay on the marked trails and do not feed the animals.","o":["unless","provided that","so that","even if"],"a":1,"ex":"«provided that» = בתנאי ש. מותר להיכנס בתנאי שנשארים בשבילים ולא מאכילים את החיות. «unless» (אלא אם כן) הופך את ההיגיון: לפיו אסור להיכנס דווקא כשמתנהגים כמו שצריך.","w":[["provided that","בתנאי ש..."],["unless","אלא אם כן"],["reserve","שמורה"]]}]},{"type":"rc","title":"Tomorrow's Problem","text":["Almost everyone has postponed an important task while knowing that the delay would only make things worse. For a long time, procrastination was viewed as a simple matter of laziness or poor time management. Psychologists now regard this explanation as incomplete. Studies suggest that many people who procrastinate are not lazy at all; in fact, they often work hard on other, less urgent tasks while the one that really matters is left waiting. This observation led researchers to look for the causes elsewhere.","According to a growing body of research, procrastination is primarily a problem of managing emotions rather than time. When a task makes us feel anxious, bored or doubtful about our abilities, avoiding it brings immediate relief. That relief, however, is temporary, and it comes at a cost: the unpleasant feelings return, often stronger, as the deadline approaches. Because the brain tends to value an immediate reward more highly than a distant one, the short-term comfort of delay frequently wins over the long-term benefit of finishing the work.","Researchers have also noticed that people tend to think of their future selves almost as strangers. In one study, brain scans showed that when participants imagined themselves ten years from now, their pattern of brain activity resembled the pattern produced when they thought about other people. This may explain why it feels so easy to leave a difficult job for \"tomorrow's me\": it is, in a sense, someone else's problem.","Fortunately, these findings also point to practical solutions. Breaking a large project into small, concrete steps makes it seem less threatening, so getting started requires less emotional effort; writing a single paragraph, for example, feels far easier than writing an entire report. Another useful strategy is to forgive oneself for past delays. In one experiment, students who did so procrastinated less before their next exam, presumably because they felt less guilt and anxiety. Finally, picturing one's future self in vivid detail can make that person feel closer and more worth protecting."],"qs":[{"q":"The passage mainly discusses","o":["how to manage time more efficiently at work","the differences between lazy people and hard-working people","how brain scans are used to study long-term memory","why people delay tasks and what can help them do so less"],"a":3,"ex":"הקטע מסביר למה אנשים דוחים משימות (רגשות, תגמול מיידי, ה«אני» העתידי כזר) ובפסקה האחרונה מה עוזר. ניהול זמן מוזכר רק כהסבר הישן שהחוקרים דוחים, ולכן זו לא התשובה.","w":[["procrastinate","לדחות משימות, להתמהמה"],["delay","לדחות; עיכוב"]]},{"q":"According to the second paragraph, people often avoid an unpleasant task because","o":["avoiding it makes them feel better for a short time","they do not know how to plan their schedule","they believe the deadline is still very far away","they prefer to complete tasks together with others"],"a":0,"ex":"בפסקה 2 כתוב שהימנעות מהמשימה נותנת «immediate relief» (הקלה מיידית), אבל זמנית. תכנון לוח זמנים הוא בדיוק ההסבר שהפסקה דוחה: הבעיה היא רגשות, לא זמן.","w":[["relief","הקלה"],["temporary","זמני"],["rather than","במקום, ולא"]]},{"q":"In paragraph 3, the word \"it\" (in \"it is, in a sense, someone else's problem\") refers to","o":["the brain scan","the difficult job","the study","the pattern of activity"],"a":1,"ex":"המשפט אומר שקל להשאיר עבודה קשה ל«אני של מחר», כי היא בעצם הבעיה של מישהו אחר. «it» חוזר אל «a difficult job». סריקת המוח והמחקר הם לא «בעיה» שמשאירים למחר.","w":[["in a sense","במובן מסוים"],["resemble","להיות דומה ל..."]]},{"q":"It can be inferred from paragraph 3 that people procrastinate partly because they","o":["spend too much time thinking about other people","have less brain activity when they plan ahead","do not feel strongly connected to the person they will become","expect to have more free time ten years from now"],"a":2,"ex":"לפי פסקה 3, המוח מתייחס ל«אני» העתידי כמו לאדם זר, ולכן קל להעביר אליו את העבודה. כלומר, אין חיבור חזק לאדם שנהיה בעתיד. הפסקה לא אומרת שהפעילות במוח חלשה יותר, רק שהיא דומה לחשיבה על אחרים.","w":[["infer","להסיק"],["stranger","זר"]]},{"q":"The main purpose of the last paragraph is to","o":["present ways of reducing procrastination that are based on the research","argue that procrastination cannot really be changed","describe in detail an experiment on brain activity","criticize the older view that procrastination is laziness"],"a":0,"ex":"הפסקה נפתחת ב-«these findings also point to practical solutions» ומונה שלוש דרכים: לפרק משימה לצעדים, לסלוח לעצמך, ולדמיין את ה«אני» העתידי. הביקורת על ההסבר של עצלות מופיעה בפסקה 1, לא באחרונה.","w":[["strategy","אסטרטגיה, דרך פעולה"],["forgive","לסלוח"],["presumably","ככל הנראה"]]}]},{"type":"rs","qs":[{"q":"Because the factory's machines had become too old to repair, the owners decided to replace them all, although this required a large loan from the bank.","o":["Because the owners took a large loan from the bank, they were able to repair all of the factory's old machines instead of replacing them with new ones.","The owners replaced only some of the factory's old machines, since the rest could still be repaired cheaply without taking a large loan from the bank.","Since the old machines in the factory could no longer be fixed, the owners chose to replace every one of them, even though this meant borrowing heavily from the bank.","Because the factory's machines were too old to repair, the bank required the owners to replace them all before it would agree to give them a loan."],"a":2,"ex":"במקור: המכונות ישנות מדי לתיקון, ולכן הבעלים החליפו את כולן למרות שנדרשה הלוואה גדולה. בתשובה הנכונה «Because» הופך ל-«Since», «although» ל-«even though», ו-«a large loan» ל-«borrowing heavily». «only some» משנה את הכמות, ובאפשרות האחרונה הבנק הוא שדורש, וזה לא במקור.","w":[["since","מכיוון ש..."],["even though","אף על פי ש..."],["loan","הלוואה"]]},{"q":"Researchers at the university have shown that regular exposure to natural light during the morning can significantly improve the quality of sleep among night-shift workers.","o":["University researchers have shown that night-shift workers actually sleep worse when they are regularly exposed to natural light in the morning hours.","It has been shown by university researchers that night-shift workers may sleep considerably better if regularly exposed to natural light in the morning.","University researchers have shown that regular exposure to natural light in the morning considerably improves the sleep of all workers except those who work at night.","University researchers have shown that night-shift workers need considerably fewer hours of sleep if they regularly spend their mornings outdoors in natural light."],"a":1,"ex":"התשובה הנכונה עוברת לסביל («It has been shown by») ומחליפה «significantly» ב-«considerably». «sleep worse» הופך את התוצאה, והאפשרות השלישית מוציאה דווקא את עובדי הלילה, שהם הנושא של המחקר.","w":[["exposure","חשיפה"],["significantly","באופן משמעותי"],["considerably","במידה ניכרת"]]},{"q":"While the aquarium's shark tank draws thousands of visitors every summer, its exhibit on local river fish is rarely visited, even by people who live nearby.","o":["Both the aquarium's shark tank and its exhibit on local river fish attract thousands of visitors every summer, most of them people who live in the nearby towns.","The aquarium's exhibit on local river fish is popular mostly with residents of the area, while tourists prefer to visit the shark tank in summer.","Because its shark tank is so crowded with thousands of visitors in the summer, the aquarium has decided to close its exhibit on local river fish.","Hardly anyone, not even local residents, visits the aquarium's exhibit on river fish, in contrast to its shark tank, which attracts thousands of visitors each summer."],"a":3,"ex":"התשובה הנכונה מתחילה מהחלק השני של המקור ומחליפה «While» ב-«in contrast to», ו-«rarely» ב-«Hardly anyone». «Both» הופך ניגוד להוספה, והאפשרות השנייה טוענת שתושבי האזור כן מבקרים, בניגוד למקור.","w":[["while","בעוד ש... (ניגוד)"],["rarely","לעיתים רחוקות"],["hardly","כמעט לא"]]}]},{"type":"rs","qs":[{"q":"The study's conclusions should be treated with caution, since the number of participants was small and all of them came from the same neighborhood.","o":["Only a few people took part in the study, and they all lived in the same neighborhood; therefore, its conclusions must be treated carefully.","The researchers were very cautious about choosing participants, so they deliberately selected a small group of people who all came from a single neighborhood.","Although only a few people took part in the study, its conclusions are fully reliable, since all of the participants came from the same neighborhood.","The study included a large number of participants, but only some of them came from the same neighborhood, so its conclusions are uncertain."],"a":0,"ex":"במקור «since» מציג את הסיבה (מעט משתתפים מאותה שכונה) אחרי המסקנה. בתשובה הנכונה הסיבה באה קודם והמסקנה מגיעה עם «therefore». האפשרות השלישית הופכת את המסקנה ל«אמינות», והרביעית משנה את הכמות («large number», «only some»).","w":[["caution","זהירות"],["since","מכיוון ש..."],["therefore","לכן"]]},{"q":"Unless farmers in the region find new sources of water within the next decade, many of them will have to stop growing crops that need heavy irrigation.","o":["Even if farmers in the region find new sources of water in the next decade, most of them will still stop growing crops that need a lot of irrigation.","Farmers in the region have already found new sources of water, so in the next decade they will be able to grow more crops that need heavy irrigation.","If farmers in the region do not find new water sources in the next ten years, many of them will have to stop growing crops that depend on heavy irrigation.","Unless farmers in the region stop growing crops that need heavy irrigation, they will have used up all of the region's available water within the next ten years."],"a":2,"ex":"«Unless» = אלא אם כן, כלומר «if ... not». התשובה הנכונה מחליפה את «Unless» ב-«If ... do not» ושומרת על אותו תנאי ואותה תוצאה. «Even if» מבטל את התנאי, והאפשרות האחרונה הופכת את מה שתלוי במה.","w":[["unless","אלא אם כן"],["if","אם"],["irrigation","השקיה"]]},{"q":"The city planted thousands of trees along its main streets not only to provide shade for pedestrians but also to lower the temperature of the surrounding buildings.","o":["The city planted thousands of trees along its main streets to shade pedestrians from the sun, rather than to lower the temperature of the nearby buildings.","In addition to giving pedestrians shade, the thousands of trees that the city planted along its main streets were meant to cool the nearby buildings.","Since pedestrians had complained about the heat, the city planted a few trees on its main streets to cool the surrounding buildings.","The temperature of the buildings along the city's main streets dropped, so pedestrians began planting thousands of trees themselves to create more shade."],"a":1,"ex":"במקור יש שתי מטרות יחד («not only... but also»). התשובה הנכונה שומרת על שתיהן עם «In addition to». «rather than» משאיר רק מטרה אחת, והאפשרות השלישית משנה את הכמות («a few») ומוסיפה סיבה שלא במקור.","w":[["not only... but also","לא רק... אלא גם"],["in addition to","בנוסף ל... (+שם עצם)"],["pedestrian","הולך רגל"]]}]},{"type":"sc","qs":[{"q":"The scientist's early findings were ___ at best; only later experiments produced clear and reliable results.","o":["conclusive","celebrated","fraudulent","tentative"],"a":3,"ex":"«tentative» = זמני, לא סופי, לא בטוח. רק ניסויים מאוחרים יותר נתנו תוצאות ברורות, ולכן הממצאים הראשונים היו לא חד-משמעיים. «conclusive» (חד-משמעי, מכריע) הוא בדיוק ההפך.","w":[["tentative","זמני, לא ודאי"],["conclusive","חד-משמעי, מכריע"],["reliable","אמין"]]},{"q":"The medicine works quickly, but its effect lasts ___ two hours, which is why some patients must take it as often as ten times a day.","o":["at most","at least","far beyond","no less than"],"a":0,"ex":"«at most» = לכל היותר. ההשפעה קצרה, ולכן צריך לקחת את התרופה הרבה פעמים ביום. «at least» (לפחות) ו-«no less than» מרמזים על השפעה ארוכה, וזה לא מסביר למה צריך עשר מנות ביום.","w":[["at most","לכל היותר"],["at least","לפחות"]]},{"q":"Critics argued that the new law would ___ the rights of workers rather than protect them.","o":["safeguard","expand","clarify","erode"],"a":3,"ex":"«erode» = לשחוק, לכרסם. «rather than protect» מראה שהמבקרים חששו מההפך מהגנה: פגיעה הדרגתית בזכויות. «safeguard» (לשמור על) הוא כמעט מילה נרדפת ל-«protect», ולכן לא יוצר ניגוד.","w":[["erode","לשחוק, לכרסם"],["rather than","במקום, ולא"],["safeguard","לשמור על, להגן"]]},{"q":"The novel was completed in 1920; ___, it remained unpublished until 1965, long after the author's death.","o":["accordingly","likewise","nonetheless","for instance"],"a":2,"ex":"«nonetheless» = בכל זאת, למרות זאת. הרומן היה גמור, ולמרות זאת לא פורסם עשרות שנים: יש כאן ניגוד. «accordingly» (בהתאם לכך) לא מתאים, כי סיום הכתיבה לא גורם לכך שהספר לא יפורסם.","w":[["nonetheless","בכל זאת, למרות זאת"],["accordingly","בהתאם לכך, לכן"]]}]}]},{"id":"s4","title":"מתקדם · מבחן 1","tier":2,"tierHe":"מתקדם","hi":142,"chapters":[{"type":"sc","qs":[{"q":"Because fresh water had become ___ in the region after three dry winters, farmers were forced to ration it among their crops.","o":["abundant","transparent","scarce","fragile"],"a":2,"ex":"«scarce» = נדיר, מועט. אחרי שלושה חורפים יבשים יש מעט מים, ולכן החקלאים נאלצו לחלק אותם במנות. «abundant» (בשפע) הוא ההפך: אם היו מים בשפע לא היה צורך לקצוב אותם.","w":[["scarce","נדיר, מועט"],["ration","לחלק במנות קצובות"],["abundant","שופע, בשפע"]]},{"q":"___ the strong objections of local residents, the city council voted to build the new highway along the river.","o":["Notwithstanding","Owing to","In view of","By virtue of"],"a":0,"ex":"«notwithstanding» = על אף, למרות. התושבים התנגדו, ובכל זאת המועצה הצביעה בעד הכביש: זה ניגוד, ולכן צריך מילת ויתור. «owing to» ו-«in view of» נותנים סיבה, וזה לא הגיוני שההתנגדות היא הסיבה לבנות.","w":[["notwithstanding","על אף, למרות"],["owing to","בשל, עקב"],["objection","התנגדות"]]},{"q":"Without regular maintenance, the old wooden bridge continued to ___ until engineers finally declared it unsafe for traffic.","o":["flourish","accelerate","comply","deteriorate"],"a":3,"ex":"«deteriorate» = להידרדר, להתבלות. גשר בלי תחזוקה הולך ומתקלקל עד שהוא לא בטוח. «flourish» (לשגשג) הוא ההפך הגמור.","w":[["deteriorate","להידרדר, להתבלות"],["maintenance","תחזוקה"],["flourish","לשגשג, לפרוח"]]},{"q":"The new drug lowered blood pressure in most of the patients who took it, ___ reducing their risk of suffering a heart attack.","o":["despite","thereby","instead of","unlike"],"a":1,"ex":"«thereby» = ובכך, על ידי כך. הורדת לחץ הדם היא הדרך שבה ירד הסיכון להתקף לב, כלומר זו תוצאה. «despite» (למרות) יוצר ניגוד שאין כאן, ו-«instead of» אומר שהסיכון לא ירד.","w":[["thereby","ובכך, על ידי כך"],["instead of","במקום"]]}]},{"type":"sc","qs":[{"q":"The lawyer's argument was so ___ that even the judge, who had seemed doubtful at first, was eventually persuaded.","o":["tedious","compelling","ambiguous","reluctant"],"a":1,"ex":"«compelling» = משכנע, חזק. הטיעון שכנע אפילו שופט שהיה בספק. «ambiguous» (דו-משמעי) הוא תכונה שמחלישה טיעון, לא כזו שמשכנעת.","w":[["compelling","משכנע, חזק"],["persuade","לשכנע"],["ambiguous","דו-משמעי"]]},{"q":"The museum agreed to lend the famous painting to the exhibition, ___ only for a limited period of three weeks.","o":["hence","whereby","lest","albeit"],"a":3,"ex":"«albeit» = אם כי. המוזיאון הסכים להשאיל, אבל עם הגבלה (רק לשלושה שבועות): זה ויתור חלקי. «hence» (ולכן) היה הופך את ההגבלה לתוצאה של ההסכמה, וזה לא הגיוני.","w":[["albeit","אם כי"],["hence","מכאן, ולכן"]]},{"q":"Planting trees along the river banks can ___ the damage caused by floods, although it cannot prevent flooding altogether.","o":["mitigate","intensify","precede","conceal"],"a":0,"ex":"«mitigate» = למתן, להקל. העצים מקטינים את הנזק, אבל (although) לא מונעים את השיטפון לגמרי. «intensify» (להגביר) הוא ההפך, ואז החלק השני עם «although» לא מתחבר.","w":[["mitigate","למתן, להקל"],["intensify","להגביר, להחריף"],["altogether","לגמרי"]]},{"q":"Unlike the old system, ___ every student was given exactly the same exam, the new program allows teachers to adapt tests to individual needs.","o":["whereas","thereby","whereby","hence"],"a":2,"ex":"«whereby» = שבאמצעותו, שלפיו. הוא מתאר את השיטה הישנה: שיטה שלפיה כל תלמיד קיבל אותו מבחן. «whereas» (בעוד ש) מוסיף ניגוד שני, אבל הניגוד כבר נאמר במילה «Unlike».","w":[["whereby","שבאמצעותו, שלפיו"],["whereas","בעוד ש..., ואילו"],["adapt","להתאים"]]}]},{"type":"rc","title":"Counting the Invisible: Microplastics in the Deep Sea","text":["For decades, public concern about plastic in the ocean focused on what could be seen: bottles floating on the surface and bags washed up on beaches. In recent years, however, researchers have turned their attention to the deep sea. Microplastics, fragments smaller than five millimeters, have been found in sediments thousands of meters below the surface, and even at the bottom of the deepest trenches. Many scientists now suspect that the ocean floor holds far more plastic than the surface does, although no one can yet say how much.","One reason for this uncertainty is that the deep sea is vast and expensive to reach. Collecting a single core of sediment may require a research ship, a trained crew and specialized equipment for several weeks. Hence, samples are scarce, and most come from a handful of locations that may not represent the ocean floor as a whole. Moreover, the particles themselves are tiny. The smallest cannot be seen even under an ordinary microscope, and all of them must first be separated from sand, shells and organic matter. This is a slow process whereby a sample is treated with chemicals, some of which can damage certain types of plastic and make them harder to identify.","A further difficulty is contamination. Researchers' clothing, their equipment and even the air in the laboratory constantly shed tiny plastic fibers. Unless strict precautions are taken, a sample may end up containing fibers from the laboratory, as opposed to the seabed. Several early studies were later found to have overestimated the amount of plastic for exactly this reason. Consequently, many laboratories now process 'blank' samples, containers of clean water handled in exactly the same way as the real ones, in order to estimate how much contamination occurs.","Notwithstanding these obstacles, accurate measurements matter. Microplastics on the seafloor may be swallowed by the creatures that live there and passed up the food chain. Some researchers argue that efforts to reduce plastic waste should not wait for precise figures; others caution that without reliable data it will be impossible to judge whether such efforts are working. Both groups agree, however, that standardized methods are needed so that results from different laboratories can be compared."],"qs":[{"q":"The main purpose of the passage is to","o":["argue that microplastics are more harmful in the deep sea than at the surface","describe a new technology for removing plastic from the ocean floor","show that all studies of deep-sea microplastics are unreliable","explain why the amount of microplastics in the deep sea is hard to determine"],"a":3,"ex":"כל הקטע עוסק בקשיים במדידה: המקום רחוק ויקר (פסקה 2), החלקיקים זעירים (פסקה 2), זיהום במעבדה (פסקה 3). הקטע לא משווה כמה הפלסטיק מזיק בכל מקום, ולא אומר שכל המחקרים לא אמינים, רק כמה מחקרים מוקדמים.","w":[["determine","לקבוע, לברר"],["unreliable","לא אמין"]]},{"q":"According to the second paragraph, one reason deep-sea samples may give a misleading picture is that","o":["they are collected from only a small number of places","the chemicals used to treat them add plastic particles","the particles in them are too large to separate from sand","research ships often lose them during long journeys"],"a":0,"ex":"בפסקה 2 כתוב שרוב הדגימות מגיעות מ-«a handful of locations» (מעט מקומות) שאולי לא מייצגים את כל קרקעית האוקיינוס. הכימיקלים לא מוסיפים פלסטיק, הם עלולים לפגוע בו, והחלקיקים זעירים ולא גדולים.","w":[["a handful of","קומץ, מעט"],["represent","לייצג"],["misleading","מטעה"]]},{"q":"In the third paragraph, the word 'shed' could best be replaced by","o":["store","hide","release","collect"],"a":2,"ex":"בגדים, ציוד ואוויר המעבדה «shed» סיבי פלסטיק, כלומר משחררים ומפזרים אותם, וכך הסיבים נכנסים לדגימות. «collect» (לאסוף) הוא כמעט ההפך: אם הם היו אוספים סיבים, לא היה זיהום.","w":[["shed","להשיר, לשחרר"],["release","לשחרר"],["contamination","זיהום"]]},{"q":"The third paragraph mainly serves to","o":["suggest that laboratory research on microplastics should be abandoned","point out a source of error in measurement and how scientists deal with it","compare the amount of plastic in clothing with the amount in the ocean","prove that early estimates of deep-sea plastic were too low"],"a":1,"ex":"פסקה 3 מציגה בעיה (זיהום מהמעבדה שמגדיל את הכמות שנמדדת) ואת הפתרון (דגימות «blank»). המחקרים המוקדמים העריכו יותר מדי (overestimated) ולא פחות מדי, ולכן התשובה האחרונה הפוכה.","w":[["overestimate","להעריך יותר מדי"],["consequently","כתוצאה מכך, לפיכך"],["as opposed to","בניגוד ל..."]]},{"q":"According to the last paragraph, researchers who disagree about when to act","o":["share the view that laboratories need common methods of measurement","agree that the current figures are accurate enough","believe that creatures on the seafloor do not swallow microplastics","argue that plastic waste cannot be reduced"],"a":0,"ex":"בסוף הפסקה: «Both groups agree» שצריך שיטות אחידות (standardized) כדי להשוות בין מעבדות. הם לא מסכימים שהנתונים מדויקים מספיק: קבוצה אחת אומרת במפורש שאין עדיין נתונים אמינים.","w":[["standardized","אחיד, תקני"],["caution","להזהיר"],["notwithstanding","על אף, למרות"]]}]},{"type":"rs","qs":[{"q":"Although the new irrigation method reduced water use on most of the farms that adopted it, researchers caution that it has not yet been tested in regions where rainfall is extremely scarce.","o":["Because the new irrigation method has already been tested in very dry regions, researchers believe that it will reduce water use on all farms.","The new irrigation method cut water use on most farms using it; nevertheless, researchers warn that it has yet to be tried in areas with very little rain.","Researchers warn that the new irrigation method reduced water use on only a few farms, since it was mainly used in regions with very little rainfall each year.","Although researchers have tested the new irrigation method in extremely dry regions, it failed to reduce water use on most of the farms that actually adopted it."],"a":1,"ex":"התשובה הנכונה שומרת על שני החלקים: חיסכון ברוב החוות (most = the majority), ואזהרה שהשיטה עוד לא נבדקה באזורים יבשים (not yet = has yet to). התשובה השלישית משנה «most» ל-«only a few» ומוסיפה סיבה שלא הייתה במקור.","w":[["not yet","עוד לא"],["caution","להזהיר"],["scarce","נדיר, מועט"]]},{"q":"Children who eat breakfast regularly tend to perform better at school, but this does not necessarily mean that eating breakfast is what causes their higher grades, as other factors may be involved.","o":["Since eating breakfast is clearly what improves children's grades, schools should make sure that every student eats a healthy breakfast regularly before class.","Children who eat breakfast regularly do not actually perform any better at school than other children, because other factors determine their grades.","Other factors, rather than breakfast, are certainly what cause some children both to eat breakfast regularly and to get higher grades at school.","Eating breakfast regularly is linked to doing well at school; however, it is possible that something other than breakfast explains the better results."],"a":3,"ex":"המשפט אומר שיש קשר (מתאם) בין ארוחת בוקר לציונים, אבל לא בהכרח שהיא הסיבה. התשובה הנכונה אומרת בדיוק את זה (it is possible). התשובה השלישית מלכודת: היא קובעת בוודאות שגורמים אחרים הם הסיבה, בעוד שבמקור כתוב רק «may».","w":[["tend to","נוטה ל..."],["necessarily","בהכרח"],["account for","להסביר, להיות הגורם ל..."]]},{"q":"The museum's ancient manuscripts are extremely fragile and deteriorate quickly when exposed to light; hence, only a small number of them are displayed to the public at any given time.","o":["Because only a few of the museum's ancient manuscripts are displayed at once, they deteriorate quickly when exposed to light.","Although the museum's ancient manuscripts are very fragile, most of them are displayed to the public, since light hardly affects them.","Since light causes the museum's very delicate ancient manuscripts to decay rapidly, just a few of them are shown to visitors at once.","The museum displays all of its ancient manuscripts to the public, even though light causes a small number of them to deteriorate."],"a":2,"ex":"«hence» = ולכן: הסיבה היא שהאור הורס את כתבי היד, והתוצאה היא שמציגים מעט מהם. התשובה הנכונה שומרת על הכיוון הזה עם «Since». התשובה הראשונה הופכת סיבה ותוצאה.","w":[["hence","מכאן, ולכן"],["deteriorate","להידרדר, להתבלות"],["fragile","שביר, עדין"]]}]},{"type":"rs","qs":[{"q":"The new tax is likely to reduce pollution only insofar as companies find it cheaper to adopt cleaner technologies than to keep paying the tax on their emissions.","o":["The new tax will probably lower pollution only to the extent that switching to cleaner technologies costs companies less than paying the tax.","The new tax will certainly reduce pollution, because companies will always prefer switching to cleaner technologies over paying any tax on their emissions.","Companies will adopt cleaner technologies only if the new tax fails to reduce pollution, regardless of how much the tax costs them.","Since cleaner technologies are already much cheaper than the new tax, most companies have stopped paying the tax on their emissions altogether."],"a":0,"ex":"«insofar as» = במידה ש..., ככל ש... = «to the extent that». המס יוריד זיהום רק בתנאי שטכנולוגיה נקייה זולה יותר מהמס. התשובה השנייה הופכת «likely» (סביר) ל-«certainly» (בוודאות) ומבטלת את התנאי.","w":[["insofar as","במידה ש..., ככל ש..."],["emissions","פליטות"],["adopt","לאמץ"]]},{"q":"The treaty, albeit signed by nearly every country in the region, has had little effect so far, since few of the signatories have passed the laws needed to enforce it.","o":["Because almost every country in the region signed the treaty, it has already had a considerable effect, although a few countries have not yet passed laws to enforce it.","Few countries in the region agreed to sign the treaty, and as a result it has had hardly any effect so far, even though the laws needed to enforce it were passed.","Although almost all the region's countries signed the treaty, it has achieved very little so far, as only a small number of them have enacted the laws required to enforce it.","The treaty has had little effect so far, since nearly every country in the region refused to sign it until the necessary laws were passed."],"a":2,"ex":"«albeit» = אם כי, «little» ו-«few» = מעט, כמעט אין. כמעט כולן חתמו, ובכל זאת להסכם כמעט אין השפעה כי רק מעט מדינות חוקקו חוקים. התשובה הראשונה מלכודת: «a few» (כמה) רומז שרוב המדינות כבר חוקקו, והיא גם הופכת «little effect» להשפעה ניכרת.","w":[["albeit","אם כי"],["few","מעט (כמעט אין)"],["enforce","לאכוף"]]},{"q":"As opposed to earlier surveys, which relied on what people reported about their own diets, the new study used blood tests, thereby providing a more objective measure of what participants actually ate.","o":["Like earlier surveys, the new study relied on participants' own reports of their diets, and therefore its measure of what they ate was more objective.","The new study combined blood tests with what people reported about their own diets, so as to confirm the results that earlier surveys had obtained.","Earlier surveys used blood tests to measure what people actually ate, whereas the new study relied on participants' reports, which are less objective.","Unlike previous surveys, which depended on people's self-reports, the new study used blood tests and in this way measured more objectively what participants really ate."],"a":3,"ex":"«as opposed to» = «unlike» (בניגוד ל...), ו-«thereby» = «in this way» (ובכך). הסקרים הקודמים נשענו על דיווח עצמי, והמחקר החדש על בדיקות דם. התשובה השלישית מחליפה בין הסקרים הישנים למחקר החדש.","w":[["as opposed to","בניגוד ל..."],["thereby","ובכך, על ידי כך"],["objective","אובייקטיבי, לא מוטה"]]}]},{"type":"sc","qs":[{"q":"Since the instructions were ___, half of the participants understood the task one way and the other half understood it in a completely different way.","o":["concise","ambiguous","accurate","compelling"],"a":1,"ex":"«ambiguous» = דו-משמעי. הוראות שאפשר להבין בשתי דרכים גרמו לכל קבוצה להבין אחרת. «accurate» (מדויק) היה מוביל להבנה אחידה, ההפך ממה שקרה.","w":[["ambiguous","דו-משמעי"],["concise","תמציתי"]]},{"q":"The professor's explanation was so ___ that even students with no background in the field could follow it with ease.","o":["lucid","obscure","redundant","hostile"],"a":0,"ex":"«lucid» = ברור, צלול. גם תלמידים בלי רקע הבינו בקלות, ולכן ההסבר היה ברור מאוד. «obscure» (מעורפל, לא ברור) הוא ההפך.","w":[["lucid","ברור, צלול"],["obscure","מעורפל, לא ברור"],["background","רקע"]]},{"q":"During a storm, the flash of lightning always ___ the sound of thunder, because light travels much faster than sound.","o":["follows","imitates","outlasts","precedes"],"a":3,"ex":"«precede» = לבוא לפני. האור מהיר מהקול, ולכן רואים את הברק לפני ששומעים את הרעם. «follows» (בא אחרי) הופך את הסדר ומתנגש עם הסיבה שבסוף המשפט.","w":[["precede","לבוא לפני, להקדים"],["outlast","להחזיק מעמד יותר מ..."]]},{"q":"The plan will succeed ___ the residents are willing to cooperate; without their support, it is likely to fail.","o":["although","unless","insofar as","whereas"],"a":2,"ex":"«insofar as» = במידה ש..., ככל ש... ההצלחה תלויה בשיתוף הפעולה של התושבים, וזה מה שהחלק השני אומר (בלי תמיכה זה ייכשל). «unless» (אלא אם כן) הופך את התנאי: התוכנית תצליח רק אם התושבים לא ישתפו פעולה.","w":[["insofar as","במידה ש..., ככל ש..."],["unless","אלא אם כן"],["cooperate","לשתף פעולה"]]}]}]},{"id":"s9","title":"מתקדם · מבחן 2","tier":2,"tierHe":"מתקדם","hi":142,"chapters":[{"type":"sc","qs":[{"q":"The scientist's early findings were met with doubt, but they were later ___ by several larger studies that reached exactly the same conclusion.","o":["refuted","corroborated","fabricated","overlooked"],"a":1,"ex":"«corroborate» = לאשש, לחזק. מחקרים גדולים שהגיעו בדיוק לאותה מסקנה מאשרים את הממצאים. «refuted» (הופרכו) הוא ההפך: מחקרים שמגיעים לאותה מסקנה לא מפריכים.","w":[["corroborate","לאשש, לחזק"],["refute","להפריך"],["fabricate","לבדות, לזייף"]]},{"q":"The new hiring policy has, ___, caused some confusion among employees; on the whole, though, it has made the process considerably fairer.","o":["consequently","likewise","namely","admittedly"],"a":3,"ex":"«admittedly» = יש להודות ש... הכותב מודה בחיסרון (בלבול), ואחר כך אומר «though» שבסך הכול המדיניות טובה. «consequently» (כתוצאה מכך) דורש סיבה קודמת, ואין כזו במשפט.","w":[["admittedly","יש להודות ש..."],["consequently","כתוצאה מכך, לפיכך"],["considerably","במידה ניכרת"]]},{"q":"Because the ancient poem survives only in a few ___ copies, scholars must often guess at the words that have been lost.","o":["fragmentary","pristine","voluminous","legible"],"a":0,"ex":"«fragmentary» = חלקי, מקוטע. החוקרים צריכים לנחש מילים שאבדו, ולכן ההעתקים חסרים. «pristine» (שמור בשלמותו) הוא ההפך: בהעתק שלם לא היה צורך לנחש.","w":[["fragmentary","חלקי, מקוטע"],["pristine","שמור בשלמותו, כחדש"],["legible","קריא"]]},{"q":"Most residents could barely afford the rising rents, ___ buy a home in the neighborhood where they had grown up.","o":["as well as","rather than","let alone","apart from"],"a":2,"ex":"«let alone» = ובטח שלא, קל וחומר. אם בקושי יכלו לשלם שכירות, בטח שלא יכלו לקנות בית. «as well as» (וגם) היה אומר שהם כן יכלו לקנות בית, וזה סותר את «barely».","w":[["let alone","ובטח שלא, קל וחומר"],["barely","בקושי, כמעט לא"],["as well as","וגם, בנוסף ל..."]]}]},{"type":"sc","qs":[{"q":"Talks between the two unions reached a complete ___ when neither side was willing to make any further concessions.","o":["outset","milestone","impasse","consensus"],"a":2,"ex":"«impasse» = מבוי סתום. כשאף צד לא מוכן לוותר, השיחות נתקעות. «consensus» (הסכמה כללית) הוא ההפך: בלי ויתורים לא מגיעים להסכמה.","w":[["impasse","מבוי סתום"],["concession","ויתור"],["consensus","הסכמה כללית"]]},{"q":"The bridge will reopen to traffic ___ engineers confirm that its supports can bear the weight; until then, it will remain closed.","o":["provided that","even if","lest","whereas"],"a":0,"ex":"«provided that» = בתנאי ש... הגשר ייפתח רק אחרי שהמהנדסים יאשרו, וזה מה שהחלק השני אומר (עד אז הוא סגור). «even if» (גם אם) היה אומר שהאישור לא משנה, וזה סותר את «until then».","w":[["provided that","בתנאי ש..."],["even if","גם אם, אפילו אם"],["bear","לשאת, לעמוד ב..."]]},{"q":"The side effects of the treatment proved ___: in most patients they disappeared completely within a few days.","o":["substantial","permanent","cumulative","transient"],"a":3,"ex":"«transient» = חולף, זמני. מה שבא אחרי הנקודתיים מסביר: תופעות הלוואי נעלמו תוך כמה ימים. «permanent» (קבוע) הוא ההפך הגמור.","w":[["transient","חולף, זמני"],["cumulative","מצטבר"],["permanent","קבוע"]]},{"q":"Emissions from the factory fell sharply after new filters were installed, ___ air quality in the town improved only slightly, since most pollution came from traffic.","o":["thus","whereas","so that","inasmuch as"],"a":1,"ex":"«whereas» = בעוד ש..., ואילו. הפליטות ירדו בחדות, ואילו האוויר השתפר רק מעט: זה ניגוד. «thus» (לפיכך) היה הופך את השיפור הקטן לתוצאה של הירידה, אבל המשפט אומר שהסיבה היא התנועה בכבישים.","w":[["whereas","בעוד ש..., ואילו"],["thus","לפיכך, כך"],["emissions","פליטות"]]}]},{"type":"rc","title":"The Price of a Free Ride","text":["Over the past two decades, a growing number of cities have experimented with abolishing fares on buses and trams. The appeal is easy to understand. Supporters argue that free transport benefits low-income residents, who spend a larger share of their earnings on travel, and that it persuades drivers to leave their cars at home, which in turn eases congestion and cuts emissions. Yet the experience of the cities that have actually tried the policy suggests that its effects are more modest, and more complicated, than its advocates often claim.","The first lesson concerns ridership. In almost every case, the number of passengers rose once fares were removed, sometimes considerably. However, surveys of the new riders revealed that relatively few of them had previously driven. Most had formerly walked or cycled, or had simply made fewer trips. In other words, the policy did increase the use of public transport, but it did little to reduce traffic, which was one of its central goals. Some planners concluded that the price of a ticket matters less to drivers than the speed, frequency and reliability of the service.","The second lesson concerns money. Fares rarely cover the full cost of running a transport system, but in many cities they still provide a substantial portion of its budget. Once that income disappears, it must be replaced, usually by raising local taxes or by cutting other public services. Moreover, the additional passengers place further strain on vehicles that may already be crowded, so a city that abolishes fares may soon have to buy more buses and hire more drivers. Critics point out that the same funds could instead be invested in improving the service itself.","None of this means that free transport is necessarily a mistake. In small towns, where ticket sales bring in little revenue and collecting fares is itself costly, eliminating them can make financial sense. Furthermore, some researchers maintain that the policy should be judged by its social benefits, such as greater mobility for elderly and poor residents, rather than by its impact on traffic. The debate, then, is not simply about whether free transport works, but about what, exactly, it is supposed to achieve."],"qs":[{"q":"Which of the following is the best title for the passage?","o":["Why Every City Should Abolish Bus Fares","Free Public Transport: Promises and Results","How Ticket Prices Shape Drivers' Choices","The Rise of the Tram in Small Towns"],"a":1,"ex":"הקטע מציג מה תומכי התחבורה החינמית מבטיחים (פסקה 1) ומה קרה בפועל בערים שניסו (פסקאות 2-4). הוא לא ממליץ לכל עיר לבטל תשלום, ו«מחירי הכרטיסים והנהגים» הוא רק פרט אחד מפסקה 2.","w":[["abolish","לבטל"],["advocate","תומך, חסיד"]]},{"q":"According to the second paragraph, most of the new passengers attracted by free transport","o":["had stopped driving to work","used the service only occasionally","complained that the vehicles were crowded","had not previously traveled by car"],"a":3,"ex":"בפסקה 2 כתוב שמעטים מהנוסעים החדשים נהגו קודם, ורובם הלכו ברגל, רכבו על אופניים או נסעו פחות. לכן רובם לא הגיעו מהרכב. הצפיפות מוזכרת רק בפסקה 3, ולא כתלונה של נוסעים.","w":[["relatively","יחסית"],["formerly","לשעבר, בעבר"],["in other words","במילים אחרות"]]},{"q":"In the third paragraph, 'that income' refers to","o":["the money collected from fares","the money raised through local taxes","the full cost of running a transport system","the funds needed to buy more buses"],"a":0,"ex":"המשפט הקודם מדבר על דמי הנסיעה (fares) שמממנים חלק ניכר מהתקציב. «that income» היא ההכנסה הזו, שנעלמת כשמבטלים את התשלום. המסים המקומיים הם מה שמחליף אותה, לא היא עצמה.","w":[["income","הכנסה"],["substantial","ניכר, משמעותי"],["portion","חלק"]]},{"q":"The last paragraph mainly serves to","o":["argue that free transport should be limited to large cities","show that free transport has failed in every city that tried it","suggest that the value of free transport depends partly on what it is meant to achieve","explain why collecting fares costs little in small towns"],"a":2,"ex":"הפסקה האחרונה מאזנת את הביקורת: בעיירות קטנות זה יכול להשתלם, ויש מי שמודד את המדיניות לפי התועלת החברתית. המשפט האחרון אומר שהוויכוח הוא על המטרה. הפסקה מדברת על עיירות קטנות ולא על ערים גדולות, ושם גביית דמי נסיעה דווקא יקרה.","w":[["necessarily","בהכרח"],["maintain","לטעון; לשמר"],["rather than","במקום, ולא"]]},{"q":"It can be inferred from the second paragraph that some planners believe drivers would be more willing to use public transport if","o":["buses and trams came more often and kept to their schedules","fares were reduced rather than abolished completely","more residents chose to walk or cycle instead","the cities spent less money on new vehicles"],"a":0,"ex":"בסוף פסקה 2 המתכננים אומרים שלנהגים המחיר חשוב פחות מהמהירות, התדירות והאמינות של השירות. מכאן שבשירות תדיר ואמין יותר הם היו עוברים. הוזלה חלקית במקום ביטול לא מוזכרת בכלל, וגם לפי הקטע המחיר הוא לא העיקר.","w":[["infer","להסיק"],["frequency","תדירות"],["reliability","אמינות"]]}]},{"type":"rs","qs":[{"q":"Although the reform was intended to benefit all small businesses, only those with fewer than ten employees saw any meaningful reduction in their administrative costs during its first year.","o":["The reform, which aimed to help every small business, lowered administrative costs for most of them in its first year, particularly for firms with fewer than ten workers.","Only businesses with fewer than ten employees were meant to benefit from the reform, and as a result they alone saw their administrative costs fall in its first year.","Though designed to help every small business, the reform meaningfully cut administrative costs in its first year solely for firms that employed fewer than ten people.","Small businesses with fewer than ten employees benefited from the reform during its first year, yet their administrative costs rose more sharply than those of larger firms."],"a":2,"ex":"במקור: הרפורמה נועדה לעזור לכל העסקים הקטנים, אבל רק עסקים עם פחות מעשרה עובדים נהנו ממנה (only = solely). התשובה הראשונה מלכודת: «most of them» אומר שרוב העסקים נהנו. השנייה משנה את הכוונה: לפי המקור הרפורמה נועדה לכולם.","w":[["solely","אך ורק, בלעדית"],["intend","להתכוון, לייעד"],["meaningful","משמעותי"]]},{"q":"Neighborhoods with more street trees tend to report lower rates of anxiety, but researchers stress that wealthier areas usually have both more trees and better access to health care.","o":["Planting more street trees lowers residents' anxiety, which is why researchers recommend that wealthier neighborhoods should also improve their residents' access to health care.","Lower rates of anxiety are found where street trees are common; however, researchers emphasize that richer areas generally have not only more trees but also better health care.","Researchers stress that street trees reduce anxiety only in wealthier neighborhoods, where residents also tend to enjoy better access to health care than people living elsewhere.","Because wealthier neighborhoods have better access to health care, researchers have concluded that street trees have no effect whatsoever on the anxiety levels of residents."],"a":1,"ex":"המקור מתאר קשר (מתאם) בין עצים לחרדה נמוכה, ומזהיר שבשכונות עשירות יש גם עצים וגם רפואה טובה, כלומר אולי העושר הוא הגורם. התשובה הראשונה הופכת את הקשר לסיבה ותוצאה. האחרונה מגזימה: החוקרים לא קבעו שלעצים אין שום השפעה.","w":[["tend to","נוטה ל..."],["not only... but also","לא רק... אלא גם"],["stress","להדגיש"]]},{"q":"Few of the volunteers who completed the language course became fluent, yet nearly all of them reported that it had made them more confident when speaking with native speakers.","o":["Hardly any of the volunteers who finished the language course achieved fluency; nevertheless, almost all of them said it had increased their confidence with native speakers.","Nearly all the volunteers who finished the language course became fluent, and as a result they reported feeling much more confident when speaking with native speakers.","A few of the volunteers who completed the language course became fluent, which explains why almost all of them felt more confident when speaking with native speakers.","Although most volunteers who completed the language course felt more confident, few of them were actually willing to speak with native speakers once it had ended."],"a":0,"ex":"«few» = מעט (כמעט אין) = «hardly any», ו-«yet» = «nevertheless». מעטים הגיעו לשטף, ובכל זאת כמעט כולם הרגישו בטוחים יותר. התשובה השלישית מלכודת: היא הופכת את השטף של מעטים לסיבה לביטחון של כולם, קשר שאין במקור.","w":[["few","מעט (כמעט אין)"],["nevertheless","למרות זאת, אף על פי כן"],["fluent","שוטף (בשפה)"]]}]},{"type":"rs","qs":[{"q":"The newly discovered settlement is not merely older than archaeologists had assumed; it also appears to have been inhabited continuously for several centuries rather than for a few decades.","o":["Archaeologists had assumed that the newly discovered settlement was inhabited for several centuries, but it now turns out to have been occupied for only a few decades.","The newly discovered settlement is somewhat older than archaeologists had assumed, although it was probably abandoned and resettled several times over the centuries.","Because the newly discovered settlement was inhabited continuously for several centuries, archaeologists had correctly assumed that it was older than the other sites nearby.","Besides being older than archaeologists had believed, the newly discovered settlement seems to have been occupied without interruption for centuries, not just for several decades."],"a":3,"ex":"«not merely... also» = לא רק... אלא גם, ולכן «Besides». היישוב עתיק יותר מהצפוי, וגם היה מיושב ברציפות (continuously = without interruption) מאות שנים. התשובה השנייה מלכודת: «abandoned and resettled» סותר את הרציפות.","w":[["merely","רק, לא יותר מ..."],["continuously","ברציפות"],["inhabit","לגור, לאכלס"]]},{"q":"The decline in the lake's fish population was initially blamed on overfishing, but subsequent studies indicated that rising water temperatures were largely responsible for it.","o":["Subsequent studies showed that overfishing, rather than rising water temperatures, was the main reason why the number of fish in the lake had declined.","Later studies indicated that the lake's fish population had shrunk solely because of warmer water, and that overfishing had in fact never taken place there.","At first, overfishing was held responsible for the shrinking number of fish in the lake; later research, however, pointed mainly to warmer water.","Rising water temperatures were partly caused by overfishing, according to the studies that examined why the lake's fish population had declined."],"a":2,"ex":"בהתחלה האשימו את הדיג המופרז, ואחר כך המחקרים הצביעו בעיקר (largely = mainly) על התחממות המים. התשובה השנייה מלכודת: «solely» (אך ורק) חזק מ-«largely», והיא גם מוסיפה שלא היה דיג מופרז בכלל. הראשונה הופכת את המסקנה.","w":[["subsequent","שלאחר מכן, מאוחר יותר"],["largely","במידה רבה, בעיקר"],["solely","אך ורק, בלעדית"]]},{"q":"The new vaccine offers strong protection to adults under sixty, whereas its effectiveness in older patients remains uncertain, since too few of them took part in the clinical trials.","o":["Since few patients over sixty took part in the clinical trials, the new vaccine turned out to be less effective for them than it is for younger adults.","The new vaccine protects adults under sixty well, but how effective it is for older patients is still unclear, as the trials included too few of them.","The new vaccine offers strong protection to adults of all ages, although older patients were somewhat less willing to take part in the clinical trials.","Because the new vaccine proved ineffective in older patients, only a small number of them were included in the trials, which focused on younger adults."],"a":1,"ex":"במקור: החיסון מגן היטב על צעירים מ-60, ואצל מבוגרים יותר פשוט לא יודעים (uncertain = unclear), כי היו מעט מהם בניסויים. התשובה הראשונה מלכודת: היא הופכת «לא ידוע» ל«פחות יעיל». הרביעית הופכת סיבה ותוצאה.","w":[["whereas","בעוד ש..., ואילו"],["uncertain","לא ודאי, לא ידוע"],["take part in","להשתתף ב..."]]}]},{"type":"sc","qs":[{"q":"Rather than relying on a single source, the historian ___ evidence from dozens of letters, diaries and official records.","o":["compiled","discarded","concealed","fabricated"],"a":0,"ex":"«compile» = לאסוף ולרכז. במקום מקור אחד, ההיסטוריון אסף ראיות מעשרות מקורות. «discarded» (השליך) הוא ההפך: מי שזורק את המקורות לא מפסיק להסתמך על מקור אחד.","w":[["compile","לאסוף, לרכז"],["discard","להשליך, לזנוח"],["rather than","במקום, ולא"]]},{"q":"The museum's collection, ___ its famous sculptures, includes thousands of ancient coins that are rarely shown to the public.","o":["instead of","by virtue of","aside from","in favor of"],"a":2,"ex":"«aside from» = מלבד. מלבד הפסלים המפורסמים, באוסף יש גם אלפי מטבעות. «instead of» (במקום) היה אומר שאין באוסף פסלים, וזה סותר את «its famous sculptures».","w":[["aside from","מלבד"],["instead of","במקום"],["by virtue of","מתוקף, בזכות"]]},{"q":"To many listeners, the senator's apology sounded ___, since he went on to repeat the very claims he was apologizing for.","o":["heartfelt","hollow","timely","explicit"],"a":1,"ex":"«hollow» = חלול, ריק מתוכן. מי שמתנצל וממשיך לחזור על אותן טענות לא באמת מתכוון. «heartfelt» (כן, מכל הלב) הוא ההפך, וסותר את הסיבה שבסוף המשפט.","w":[["hollow","חלול, ריק מתוכן"],["heartfelt","כן, מכל הלב"],["the very","אותו עצמו, בדיוק אותו"]]},{"q":"Workers are required to wear protective masks at all times, ___ they inhale the toxic dust produced by the machines.","o":["so that","unless","whereas","lest"],"a":3,"ex":"«lest» = פן, כדי שלא. חובשים מסכה כדי שלא ינשמו את האבק הרעיל. «so that» (כדי ש) הופך את המטרה: כאילו המסכה נועדה לגרום להם לנשום אבק.","w":[["lest","פן, שמא, כדי שלא"],["so that","כדי ש..."],["inhale","לשאוף, לנשום פנימה"]]}]}]},{"id":"s10","title":"מתקדם · מבחן 3","tier":2,"tierHe":"מתקדם","hi":142,"chapters":[{"type":"sc","qs":[{"q":"The committee's report was deliberately ___, offering broad recommendations while avoiding any specific commitment that might later prove embarrassing.","o":["meticulous","candid","vague","lavish"],"a":2,"ex":"«vague» = מעורפל, לא ברור. הדוח נמנע בכוונה מהתחייבות ספציפית ונתן רק המלצות כלליות, כלומר הוא מעורפל. «meticulous» (קפדני, מדוקדק) ו-«candid» (גלוי, כן) הם בדיוק ההפך מדוח שמתחמק מפרטים.","w":[["vague","מעורפל, לא ברור"],["deliberately","בכוונה"],["commitment","התחייבות"]]},{"q":"The theory was widely ridiculed when it was first proposed; ___, within two decades it had become the accepted explanation among geologists.","o":["consequently","nonetheless","likewise","namely"],"a":1,"ex":"«nonetheless» = למרות זאת. בהתחלה לעגו לתיאוריה, ובכל זאת היא התקבלה: יש כאן ניגוד. «consequently» (כתוצאה מכך) לא מתאים, כי הלעג לא גרם לתיאוריה להתקבל.","w":[["nonetheless","בכל זאת, למרות זאת"],["ridicule","ללעוג ל..."]]},{"q":"Years of drought had so ___ the soil that even after heavy rains, the farmers' crops failed to recover.","o":["depleted","enriched","replenished","insulated"],"a":0,"ex":"«deplete» = לרוקן, לדלדל. הבצורת דלדלה את האדמה, ולכן היבולים לא התאוששו גם אחרי גשם. «enriched» ו-«replenished» (העשיר, מילא מחדש) הם ההפך, ואז היבול היה אמור להצליח.","w":[["deplete","לדלדל, לרוקן"],["replenish","למלא מחדש"]]},{"q":"___ the museum receives additional funding, several of its galleries will have to close by the end of the year.","o":["Provided that","Since","Whereas","Unless"],"a":3,"ex":"«Unless» = אלא אם כן. האולמות ייסגרו, אלא אם כן המוזיאון יקבל עוד כסף. «Provided that» (בתנאי ש...) היה אומר שהכסף הנוסף הוא מה שיגרום לסגירה, וזה לא הגיוני.","w":[["unless","אלא אם כן"],["provided that","בתנאי ש..."]]}]},{"type":"sc","qs":[{"q":"The senator's remarks were widely condemned as ___, since they appeared to encourage hostility toward an entire community.","o":["conciliatory","tedious","inconspicuous","inflammatory"],"a":3,"ex":"«inflammatory» = מסית, מלבה יצרים. דברים שמעודדים עוינות כלפי קהילה שלמה הם מסיתים. «conciliatory» (מפייס) הוא ההפך, ו-«tedious» (משעמם) לא קשור לעידוד עוינות.","w":[["inflammatory","מסית, מלבה יצרים"],["conciliatory","מפייס"],["hostility","עוינות"]]},{"q":"The novel received little attention from critics when it first appeared, ___ it went on to sell millions of copies and was translated into forty languages.","o":["so","for","yet","as"],"a":2,"ex":"«yet» = ובכל זאת, אך. המבקרים כמעט התעלמו מהספר, ובכל זאת הוא נמכר במיליונים: ניגוד. «so» (לכן) היה אומר שההתעלמות גרמה להצלחה, וזה לא הגיוני.","w":[["yet","ובכל זאת, אך"]]},{"q":"Although the two scientists worked independently on different continents, they arrived at remarkably ___ conclusions about the origin of the disease.","o":["divergent","analogous","obscure","tentative"],"a":1,"ex":"«analogous» = דומה, מקביל. המילה «Although» מראה שמשהו מפתיע: למרות שעבדו בנפרד, הם הגיעו למסקנות דומות. «divergent» (שונות זו מזו) לא היה מפתיע בכלל, ולכן לא מתאים ל-«Although».","w":[["analogous","דומה, מקביל"],["divergent","שונה, מתפצל"],["although","למרות ש..."]]},{"q":"The city has introduced strict water quotas ___ its reservoirs run dry before the rainy season arrives.","o":["lest","once","so that","whereas"],"a":0,"ex":"«lest» = כדי שלא, פן. העירייה הגבילה את המים כדי שהמאגרים לא יתרוקנו. «so that» (כדי ש...) היה אומר שהמטרה היא לרוקן את המאגרים, וזה הפוך מההיגיון.","w":[["lest","פן, כדי שלא"],["quota","מכסה"],["reservoir","מאגר מים"]]}]},{"type":"rc","title":"After the Bleaching: Why Some Reefs Return and Others Do Not","text":["Coral reefs owe their existence to a partnership. Inside the tissues of each coral live microscopic algae that, through photosynthesis, supply the coral with most of the energy it needs. This arrangement, however, is remarkably sensitive to heat. When the water stays only one or two degrees above its usual summer maximum for several weeks, the corals expel their algae and, stripped of their color, turn white. A bleached coral is not yet dead. If temperatures drop quickly, the algae can return within weeks; if the heat persists, the coral gradually starves, and its skeleton is soon covered by seaweed.","When large numbers of corals die, a reef's recovery depends largely on new arrivals. Surviving colonies release larvae, which drift with the currents until they settle on a hard surface. Reefs that are well connected to healthy reefs upstream therefore tend to recover faster than isolated ones. Yet larvae are demanding: they attach readily to clean, bare rock but struggle where seaweed has taken over. This is why plant-eating fish, which graze the seaweed down, play a surprisingly important role: reefs where catching them is restricted often recover faster.","Even under favorable conditions, recovery is slow and uneven. Fast-growing branching corals may restore much of a reef's cover within a decade, whereas massive, dome-shaped species, some of which are several centuries old, may need far longer to replace themselves. A return of coral cover can therefore be deceptive. A reef may appear healthy while its composition has shifted toward a few fast-growing species, and these happen to be among the most vulnerable to heat.","The greatest threat, scientists argue, is no longer the severity of individual bleaching events but their frequency. Until recently, severe episodes were separated by decades, which gave reefs time to rebuild. As the oceans warm, that interval has shrunk in some regions to only a few years. Local measures, such as protecting grazing fish and reducing pollution, can speed recovery, but they cannot on their own make up for gaps that are simply too short. Some researchers are now trying to breed corals that tolerate higher temperatures; others warn that such efforts can, at best, buy reefs time."],"qs":[{"q":"Which of the following is the best title for the passage?","o":["Why Corals Turn White in Warm Water","What Determines Whether Reefs Recover from Bleaching","How Overfishing Has Destroyed the World's Reefs","Heat-Tolerant Corals: A Solution Within Reach"],"a":1,"ex":"הקטע עוסק כולו בשאלה מה קובע אם שונית מתאוששת אחרי הלבנה: זרמים, דגים, קצב גדילה ותדירות האירועים. «Why Corals Turn White» מתאים רק לפסקה הראשונה, ולכן הוא צר מדי.","w":[["recover","להתאושש"],["bleaching","הלבנה (של אלמוגים)"]]},{"q":"According to the second paragraph, plant-eating fish help reefs recover because they","o":["carry coral larvae from healthy reefs to damaged ones","feed on the algae that bleached corals expel","protect young corals from fish that eat them","keep the rock clear enough for larvae to attach to it"],"a":3,"ex":"בפסקה 2 כתוב שהלרוות נאחזות בסלע נקי וחשוף ומתקשות במקום שהאצות השתלטו עליו, והדגים אוכלים את האצות. כלומר הם שומרים על הסלע נקי. את הלרוות מביאים הזרמים, לא הדגים.","w":[["graze","ללחך, לאכול צמחייה"],["larvae","זחלים, לרוות"],["attach","להיצמד"]]},{"q":"In the third paragraph, the word 'deceptive' could best be replaced by","o":["misleading","encouraging","temporary","accurate"],"a":0,"ex":"«deceptive» = מטעה. המשפט שאחריו מסביר: השונית נראית בריאה, אבל בפועל היא השתנתה. «encouraging» (מעודד) מפתה, כי כיסוי אלמוגים שחוזר נראה חיובי, אבל הפסקה מדגישה שהמראה מטעה.","w":[["deceptive","מטעה"],["composition","הרכב"]]},{"q":"The third paragraph mainly serves to","o":["explain why branching corals withstand heat better than massive ones","show that all coral species need about a decade to recover","warn that a reef that looks recovered may have changed in important ways","describe how scientists determine the age of massive corals"],"a":2,"ex":"עיקר הפסקה: שונית שנראית מבריאה יכולה להיות מורכבת ממינים אחרים, רגישים יותר לחום. התשובה הראשונה הפוכה: לפי הקטע, האלמוגים המהירים דווקא מהפגיעים ביותר לחום.","w":[["uneven","לא אחיד"],["vulnerable","פגיע"]]},{"q":"It can be inferred from the last paragraph that local measures such as protecting grazing fish","o":["have become unnecessary now that heat-tolerant corals can be bred","are the main reason that bleaching events now occur more often","work only in regions where bleaching occurs every few years","can help reefs recover but are not enough if bleaching becomes too frequent"],"a":3,"ex":"כתוב שהצעדים המקומיים מאיצים התאוששות, אבל לא יכולים לבדם לפצות על מרווחים קצרים מדי. כלומר הם עוזרים אבל לא מספיקים. אין בקטע שום טענה שהגידול של אלמוגים עמידים כבר מצליח או שהוא מייתר אותם.","w":[["make up for","לפצות על"],["frequency","תדירות"],["at best","במקרה הטוב"]]}]},{"type":"rs","qs":[{"q":"Cities with more public parks tend to report lower rates of depression among their residents, although researchers have not established whether the parks themselves are responsible for this difference.","o":["Researchers have shown that public parks lower rates of depression, which explains why residents of cities with more parks report being less depressed than others.","Residents of cities with fewer public parks tend to report lower rates of depression, a pattern that researchers have so far been unable to fully explain.","Depression is generally less common in cities that have more public parks, but it remains unclear whether the parks actually cause residents to be less depressed.","Although cities with more public parks have lower rates of depression, researchers are convinced that the parks have nothing to do with their residents' mental health."],"a":2,"ex":"במשפט המקורי יש קשר (יותר פארקים, פחות דיכאון) אבל לא הוכח שהפארקים הם הסיבה. התשובה הנכונה שומרת על זה: «it remains unclear whether the parks actually cause». התשובה הראשונה מציגה את הקשר כהוכחה של סיבה ותוצאה, וזה לא נאמר.","w":[["although","למרות ש..."],["establish","לקבוע, להוכיח"],["be responsible for","להיות הגורם ל..."]]},{"q":"Only a handful of the ancient city's original buildings survived the earthquake intact, yet archaeologists were able to reconstruct much of its layout from the foundations that remained beneath the rubble.","o":["Although very few of the ancient city's original buildings came through the earthquake undamaged, archaeologists managed to recreate a large part of its plan using the foundations left under the ruins.","Most of the ancient city's original buildings survived the earthquake undamaged, so archaeologists could easily reconstruct its layout without having to dig through the rubble to reach the foundations.","Because only a few of the ancient city's buildings survived the earthquake, archaeologists could reconstruct barely any of its layout, even though the foundations beneath the rubble remained.","Archaeologists reconstructed the entire layout of the ancient city from its foundations, and as a result, a handful of its original buildings were restored to their condition before the earthquake."],"a":0,"ex":"«Only a handful» = רק מעט מאוד, ו-«much of its layout» = חלק גדול מהתוכנית. התשובה הנכונה שומרת על שתי הכמויות. «Most» הופך את «מעט» ל«רוב», ו-«barely any» הופך את «הרבה» ל«כמעט כלום».","w":[["a handful","קומץ, מעט מאוד"],["intact","שלם, ללא פגע"],["yet","ובכל זאת, אך"]]},{"q":"The new vaccine proved highly effective among adults under sixty, but the trial included too few elderly participants to determine whether it offers the same protection to older people.","o":["The trial showed that the new vaccine is highly effective among adults under sixty but offers considerably less protection to older people, who took part in smaller numbers.","The new vaccine proved highly effective among people of all ages, although the trial included fewer elderly participants than the researchers had originally planned to recruit.","Because too many elderly people took part in the trial, researchers were unable to determine how effective the new vaccine is among adults who are younger than sixty.","Although the new vaccine worked very well for adults younger than sixty, too few older participants took part in the trial to show whether it protects them equally well."],"a":3,"ex":"המקור אומר שלגבי המבוגרים פשוט אין מספיק מידע. התשובה הראשונה טוענת שהחיסון מגן עליהם פחות, וזו טענה שלא נאמרה. התשובה השנייה מרחיבה את ההצלחה ל«all ages», וזו טעות בהיקף.","w":[["participant","משתתף"],["determine","לקבוע"],["elderly","קשישים"]]}]},{"type":"rs","qs":[{"q":"Owing to a sharp rise in the cost of imported grain, many small bakeries have been forced to raise their prices, while several others have closed altogether.","o":["Many small bakeries have raised their prices or closed altogether, and as a result, the cost of imported grain has risen sharply over the past several months.","Since imported grain has become much more expensive, a large number of small bakeries have had to charge more, and some have even shut down completely.","In spite of a sharp rise in the cost of imported grain, most small bakeries have managed to keep their prices low, and only a few have closed down.","A sharp rise in the cost of imported grain has forced all small bakeries to raise their prices, and many of them are now considering closing altogether."],"a":1,"ex":"«Owing to» = בשל, עקב: התייקרות הדגן היא הסיבה, והעלאת המחירים והסגירה הן התוצאה. בתשובה הראשונה הסיבה והתוצאה התהפכו. בתשובה האחרונה «many» הפך ל«all», והמאפיות שנסגרו הפכו למאפיות ש«שוקלות» להיסגר.","w":[["owing to","בשל, עקב"],["as a result","כתוצאה מכך"],["in spite of","למרות"]]},{"q":"Far from discouraging further research, the failure of the first experiment led the team to question an assumption that had previously been accepted by almost everyone in the field.","o":["Rather than putting the team off further research, the unsuccessful first experiment caused the researchers to doubt an assumption that nearly all experts in the field had formerly taken for granted.","The failure of the first experiment discouraged the team from carrying out further research, since it showed that an assumption accepted by almost everyone in the field was in fact correct.","Although the first experiment failed, the team continued its research, largely because almost everyone in the field had warned them not to question an assumption that was widely accepted.","The team questioned an assumption accepted by only a few researchers in the field, and this eventually caused the first experiment to fail and all further research to come to a stop."],"a":0,"ex":"«Far from discouraging» = לא רק שלא ריפה את ידיהם, אלא להפך. הכישלון גרם לצוות לפקפק בהנחה מקובלת. «Rather than» שומר על המשמעות הזו. התשובה השנייה הופכת את ההיגיון (הכישלון כן עצר את המחקר), והאחרונה הופכת את «almost everyone» ל«only a few».","w":[["rather than","במקום, ולא"],["far from","רחוק מ..., להפך מ..."],["take for granted","לקבל כמובן מאליו"]]},{"q":"The committee's findings, while by no means conclusive, lend considerable support to the view that the bridge collapsed because of design flaws rather than poor maintenance.","o":["The committee's findings prove beyond any doubt that the bridge collapsed because of design flaws, although poor maintenance may also have played some part in its collapse.","Although the committee's findings are not conclusive, they strongly suggest that the bridge collapsed mainly because it was poorly maintained over time rather than because it was badly designed.","Although they do not settle the matter, the committee's findings strongly back the claim that defects in the bridge's design, and not inadequate upkeep, caused it to collapse.","The committee's findings offer little support to the view that design flaws caused the bridge to collapse, since they are by no means conclusive about its maintenance."],"a":2,"ex":"«by no means conclusive» = בשום אופן לא חד משמעיים, ובכל זאת הממצאים תומכים מאוד בכך שהסיבה היא תכנון לקוי ולא תחזוקה. התשובה הראשונה טוענת «prove beyond any doubt», וזה סותר את «not conclusive». התשובה השנייה הופכת את הסיבה.","w":[["by no means","בשום אופן לא"],["conclusive","חד משמעי, מכריע"],["rather than","במקום, ולא"]]}]},{"type":"sc","qs":[{"q":"Critics argued that the new regulations were merely ___, designed to reassure the public rather than to bring about any real change.","o":["radical","cosmetic","rigorous","retroactive"],"a":1,"ex":"«cosmetic» = שטחי, למראית עין. תקנות שנועדו רק להרגיע את הציבור ולא לשנות באמת הן קוסמטיות. «radical» (קיצוני, יסודי) ו-«rigorous» (קפדני) הם ההפך משינוי שאינו אמיתי.","w":[["cosmetic","שטחי, למראית עין"],["merely","רק, לא יותר מ..."],["reassure","להרגיע"]]},{"q":"The region's economy relies ___ on tourism, so the sudden drop in foreign visitors has had devastating consequences.","o":["seldom","barely","solely","hardly"],"a":2,"ex":"«solely» = אך ורק. אם הכלכלה נשענת רק על תיירות, ירידה בתיירים הרסנית, ולכן «so» הגיוני. «barely» ו-«hardly» (כמעט לא) היו אומרים שהתיירות כמעט לא חשובה, ואז הירידה לא הייתה הרסנית.","w":[["solely","אך ורק, בלעדית"],["barely","בקושי, כמעט לא"],["devastating","הרסני"]]},{"q":"The negotiations reached a ___ when neither side was willing to make any further concessions.","o":["consensus","milestone","prerequisite","deadlock"],"a":3,"ex":"«deadlock» = מבוי סתום. כששני הצדדים מסרבים לוותר, המשא ומתן נתקע. «consensus» (הסכמה כללית) הוא ההפך: כשאף צד לא מוותר, אין הסכמה.","w":[["deadlock","מבוי סתום, קיפאון"],["concession","ויתור"],["consensus","הסכמה רחבה"]]},{"q":"___, the new method is more expensive than the traditional one, but the savings it produces over time more than justify the initial cost.","o":["Admittedly","Consequently","Likewise","Conversely"],"a":0,"ex":"«Admittedly» = יש להודות ש... מודים בחיסרון (השיטה יקרה יותר), ואז ה-«but» מציג את היתרון שגובר עליו. «Consequently» (כתוצאה מכך) לא מתאים, כי אין כאן תוצאה של משהו שנאמר קודם.","w":[["admittedly","יש להודות ש..."],["justify","להצדיק"]]}]}]},{"id":"s5","title":"פטור · מבחן 1","tier":3,"tierHe":"פטור","hi":150,"chapters":[{"type":"sc","qs":[{"q":"The evidence linking the drug to the side effect remains ___ at best: a handful of small studies, none of which took the patients' age into account.","o":["compelling","abundant","tenuous","conclusive"],"a":2,"ex":"«Tenuous» = קלוש, חלש. אחרי הנקודתיים מתוארות ראיות דלות (כמה מחקרים קטנים ולא מבוקרים), ולכן הראיות חלשות. «compelling» ו-«conclusive» אומרות ההפך: ראיות משכנעות וחד-משמעיות.","w":[["tenuous","קלוש, רופף"],["at best","במקרה הטוב"],["conclusive","חד-משמעי, מכריע"]]},{"q":"Researchers stored a second copy of the data on a separate server ___ the original be lost in a power failure.","o":["lest","unless","provided that","so that"],"a":0,"ex":"«Lest» = כדי שלא, פן. שמרו עותק נוסף כדי שהמקור לא יאבד. «so that» היה אומר שהמטרה היא שהמקור יאבד, וזה לא הגיוני.","w":[["lest","פן, שמא, כדי שלא"],["so that","כדי ש..."]]},{"q":"Far from being ___, the senator's position on the issue has shifted at least three times in the past year.","o":["erratic","fickle","controversial","steadfast"],"a":3,"ex":"«Far from being» = רחוק מלהיות. העמדה השתנתה שלוש פעמים, כלומר היא רחוקה מלהיות יציבה: «steadfast» = יציב, נחוש. «erratic» ו-«fickle» (הפכפך) מתארות בדיוק את מה שקרה, ולכן לא מתאימות אחרי «far from».","w":[["steadfast","יציב, איתן, נחוש"],["fickle","הפכפך"],["erratic","לא יציב, הפכפך"]]},{"q":"The committee's report was ___ a full endorsement of the plan; it praised the plan's goals but rejected nearly every one of its proposed methods.","o":["undoubtedly","by no means","above all","in particular"],"a":1,"ex":"«By no means» = בשום אופן לא. הדוח דחה כמעט את כל השיטות, ולכן הוא בשום אופן לא תמיכה מלאה. «undoubtedly» היה אומר שזו ללא ספק תמיכה מלאה, וזה סותר את החלק השני.","w":[["by no means","בשום אופן לא"],["endorsement","תמיכה, אישור"]]}]},{"type":"sc","qs":[{"q":"Although the virus was first detected in a single village, it managed to ___ across the region within weeks, overwhelming local clinics.","o":["proliferate","dwindle","subside","stagnate"],"a":0,"ex":"«Proliferate» = להתרבות, להתפשט במהירות. המרפאות הוצפו, כלומר הנגיף התפשט. «dwindle» ו-«subside» פירושן להצטמצם ולשכוך, ההפך ממה שמתואר.","w":[["proliferate","להתרבות, להתפשט במהירות"],["dwindle","להצטמצם, לפחות"],["subside","לשכוך, לרדת"]]},{"q":"The study's findings are relevant to our school ___ they were based on students of the same age and background as ours.","o":["lest","whereas","inasmuch as","albeit"],"a":2,"ex":"«Inasmuch as» = מאחר ש..., במידה ש.... החלק השני הוא הסיבה לכך שהממצאים רלוונטיים. «whereas» מציין ניגוד, ואין כאן ניגוד בין שני החלקים.","w":[["inasmuch as","מאחר ש..., במידה ש..."],["whereas","בעוד ש..., ואילו"]]},{"q":"Auditors found a striking ___ between the figures the company reported to investors and those it submitted to the tax authorities: the first showed a large profit, the second a loss.","o":["resemblance","consensus","correlation","discrepancy"],"a":3,"ex":"«Discrepancy» = פער, אי-התאמה. סט אחד הראה רווח והשני הפסד, כלומר המספרים לא מתאימים זה לזה. «resemblance» (דמיון) אומרת ההפך.","w":[["discrepancy","פער, אי-התאמה"],["resemblance","דמיון"]]},{"q":"The plan had several obvious flaws; the board, ___, approved it unanimously, hoping to fix the details at a later stage.","o":["accordingly","nonetheless","likewise","namely"],"a":1,"ex":"«Nonetheless» = למרות זאת. לתוכנית היו פגמים ברורים, ובכל זאת הדירקטוריון אישר אותה. «accordingly» (בהתאם לכך) היה אומר שהאישור נבע מהפגמים, וזה לא הגיוני.","w":[["nonetheless","בכל זאת, למרות זאת"],["accordingly","בהתאם לכך, לכן"],["flaw","פגם"]]}]},{"type":"rc","title":"The Long Road from Invention to Adoption","text":["It is tempting to assume that a superior technology wins as soon as it appears. History suggests otherwise. The gap between an invention and its widespread use is often measured not in months but in decades, and economists have long tried to explain why tools that seem obviously beneficial in hindsight were, at the time, adopted with remarkable reluctance.","One reason is that a new technology rarely arrives in finished form. Early versions tend to be expensive, unreliable and difficult to repair, and their advantages over existing methods may be modest at first. A farmer who already owns horses and knows how to care for them has little reason to buy an early tractor that breaks down frequently and requires fuel he cannot easily obtain. Only after years of gradual improvement, much of it carried out by people other than the original inventor, does the new tool become clearly worth its price.","A second obstacle lies in what economists call complementary investments. A technology is seldom useful on its own; it depends on other things being in place. Electric motors, for example, offered factories little benefit as long as buildings were designed around a single steam engine that drove every machine through long belts and shafts. The real gains appeared only when owners redesigned entire factories, a costly process that many postponed until their old buildings wore out. In such cases, the delay reflects not ignorance but a reasonable calculation.","Finally, adoption is a social process. People learn about new methods mainly from neighbors, colleagues and competitors, and they tend to trust what they can observe directly. When the benefits of an innovation are hard to see, or appear only after many years, even well-informed individuals may hesitate. Institutions can slow matters further: regulations written for an older technology, or workers whose skills would lose their value, may resist a change that threatens established interests.","None of this means that slow adoption is simply wasteful. Waiting allows a technology to mature and its problems to surface before large sums are committed. Nonetheless, understanding the sources of delay can help governments and firms decide when intervention, such as training programs or shared infrastructure, might shorten a wait that serves no one."],"qs":[{"q":"The passage mainly discusses","o":["why inventors often fail to profit from their own inventions","the reasons that beneficial technologies may take a long time to be widely used","how electricity transformed the design of factories","the ways in which governments can speed up the adoption of new technologies"],"a":1,"ex":"כל הקטע מסביר למה טכנולוגיות מועילות מתפשטות לאט: מוצר לא מוגמר, השקעות משלימות ותהליך חברתי. המנועים החשמליים הם רק דוגמה בפסקה 3, והממשלות מוזכרות רק בסוף.","w":[["adoption","אימוץ"],["widespread","נפוץ, רחב היקף"]]},{"q":"According to the second paragraph, the farmer in the example would probably not buy an early tractor because","o":["he did not trust the people who sold it","the government had restricted its use","it could not do the work of a horse","it often broke down and its fuel was hard to get"],"a":3,"ex":"בפסקה 2 כתוב שהטרקטור המוקדם «breaks down frequently» ודורש דלק שקשה להשיג. אמון במוכרים ותקנות של הממשלה לא מוזכרים בפסקה הזו.","w":[["unreliable","לא אמין"],["obtain","להשיג"]]},{"q":"In the fourth paragraph, the word 'established' could best be replaced by","o":["proven","founded","existing","confirmed"],"a":2,"ex":"«Established interests» = האינטרסים הקיימים והמבוססים, של מי שנהנה מהמצב הנוכחי. לכן «existing». «proven» (מוכח) מפתה, אבל לא מדובר באינטרסים שהוכחו אלא באינטרסים שכבר קיימים.","w":[["established","מבוסס, קיים, מושרש"],["threaten","לאיים על"]]},{"q":"The example of electric motors in the third paragraph is used to show that","o":["the benefit of a new technology may depend on other costly changes being made","factory owners were generally unaware of new technologies","steam engines were more efficient than electric motors","electric motors were adopted more quickly than tractors"],"a":0,"ex":"הפסקה עוסקת ב«complementary investments»: המנוע החשמלי הועיל רק אחרי שתכננו מחדש את כל המפעל, תהליך יקר. הקטע אומר במפורש שהעיכוב «not ignorance», ולכן התשובה על חוסר מודעות שגויה.","w":[["complementary","משלים"],["postpone","לדחות"]]},{"q":"It can be inferred from the last paragraph that the author believes that","o":["some delays in adoption serve a useful purpose, while others might reasonably be shortened","governments should avoid any involvement in the spread of new technologies","every delay in adopting a useful technology is a waste of resources","most new technologies are adopted too quickly to be properly tested"],"a":0,"ex":"הכותב אומר שהמתנה מאפשרת לטכנולוגיה להבשיל (כלומר יש בה תועלת), ובכל זאת אפשר לקצר המתנה «that serves no one». «every delay is a waste» סותרת את המשפט «None of this means that slow adoption is simply wasteful».","w":[["nonetheless","בכל זאת, למרות זאת"],["mature","להבשיל"],["intervention","התערבות"]]}]},{"type":"rs","qs":[{"q":"Granted that the new vaccine is more expensive than the old one, its far greater effectiveness makes it the better choice for the national health service.","o":["Because the new vaccine is more expensive than the old one, the national health service should continue to prefer the old one, despite its considerably lower effectiveness.","Although the new vaccine costs more than the old one, the national health service would do better to choose it, since it is considerably more effective.","The new vaccine is both cheaper and more effective than the old one, so the national health service should choose it.","Although the new vaccine is more effective than the old one, its higher price makes it the less sensible choice for the national health service."],"a":1,"ex":"«Granted that» = נכון ש..., גם אם נודה ש.... המשפט מודה שהחיסון החדש יקר יותר, ובכל זאת קובע שהוא עדיף כי הוא יעיל בהרבה. התשובה הנכונה שומרת על שני החלקים עם «Although» ו-«since». התשובה האחרונה הופכת את המסקנה (המחיר מכריע).","w":[["granted that","נכון ש..., גם אם נודה ש..."],["although","למרות ש..."],["effectiveness","יעילות"]]},{"q":"The town's economic decline was caused not so much by the closure of the mine as by the failure of local leaders to develop any alternative source of employment in the years that followed.","o":["The closure of the mine was the main reason for the town's economic decline, although local leaders also failed to create any new jobs in the years that followed.","The closure of the mine and the local leaders' failure to create new jobs afterwards contributed in equal measure to the town's economic decline.","Local leaders failed to develop new sources of employment because the closure of the mine had already ruined the town's economy.","It was chiefly the local leaders' failure to create other jobs after the mine closed, rather than the closure itself, that caused the town's economic decline."],"a":3,"ex":"«Not so much X as Y» = לא כל כך X אלא בעיקר Y. הסיבה העיקרית היא כישלון המנהיגים, לא סגירת המכרה. התשובה הראשונה הופכת את הדגש, והשנייה אומרת שהשתיים תרמו באותה מידה.","w":[["not so much X as Y","לא כל כך X אלא Y"],["chiefly","בעיקר"],["rather than","במקום, ולא"]]},{"q":"Officials delayed announcing the results of the inquiry, lest premature disclosure should provoke public panic before the full extent of the water contamination had been established.","o":["Officials held back the inquiry's results, fearing that releasing them too early might cause public panic before the full extent of the water contamination was known.","Because the public had already panicked over the water contamination, officials decided to delay announcing the results of the inquiry until the situation had calmed down.","Officials released the results of the inquiry as early as possible in order to prevent public panic over the extent of the water contamination in the area.","Officials delayed announcing the results of the inquiry until they had confirmed that the water contamination was far too limited to cause any serious public panic."],"a":0,"ex":"«Lest» = מחשש ש..., כדי שלא. הפקידים עיכבו את הפרסום כדי שלא תפרוץ בהלה לפני שהיקף הזיהום ידוע. בתשובה השנייה הבהלה כבר קרתה, והאחרונה מוסיפה טענה שלא נאמרה (שהזיהום מוגבל).","w":[["lest","פן, שמא, כדי שלא"],["premature","מוקדם מדי"],["extent","היקף"]]}]},{"type":"rs","qs":[{"q":"Hardly had the company launched its new smartphone when reports of overheating batteries began to appear, forcing it to recall nearly a quarter of a million devices within a month.","o":["The company recalled nearly a quarter of a million of its new smartphones before any reports of overheating batteries had appeared.","Several years after the company launched its new smartphone, reports of overheating batteries forced it to recall nearly a quarter of a million devices.","Almost as soon as the company's new smartphone went on sale, reports of overheating batteries emerged, and within a month the company had to recall almost 250,000 devices.","Almost as soon as the company's new smartphone went on sale, reports of overheating batteries emerged, but the company refused to recall any of the devices it had sold."],"a":2,"ex":"«Hardly had... when» = אך ורק... וכבר, מיד אחרי ש.... הדיווחים הופיעו מיד אחרי ההשקה והובילו לריקול. התשובה השנייה משנה את הזמן (כמה שנים אחרי), והאחרונה הופכת את התוצאה (סירבה לריקול).","w":[["hardly","כמעט לא"],["recall","להחזיר מוצר מהשוק, ריקול"],["as soon as","ברגע ש..., מיד כש..."]]},{"q":"Inasmuch as the survey relied solely on volunteers, who tend to be more health-conscious than the general population, its conclusions about national eating habits should be treated with considerable caution.","o":["The survey's conclusions about national eating habits are reliable, since its volunteers were more health-conscious than the general population.","Since the survey was based only on volunteers, who are generally more health-conscious than most people, its findings about the nation's eating habits may not be fully trustworthy.","Since the survey was based only on volunteers, who are generally less health-conscious than most people, its findings about the nation's eating habits may not be fully trustworthy.","Since the survey's findings about the nation's eating habits may not be trustworthy, researchers decided to rely only on volunteers."],"a":1,"ex":"«Inasmuch as» = מאחר ש.... מכיוון שהסקר נשען רק על מתנדבים שמקפידים יותר על בריאות, צריך להיזהר במסקנות. התשובה השלישית הופכת את ההשוואה (פחות מקפידים), והרביעית הופכת סיבה ותוצאה.","w":[["inasmuch as","מאחר ש..., במידה ש..."],["solely","אך ורק, בלעדית"],["caution","זהירות"]]},{"q":"The treaty was by no means the first attempt to limit the arms race; it was, nonetheless, the first to include a system for verifying that both sides were actually keeping their commitments.","o":["The treaty was the first attempt ever made to limit the arms race, and it also included a system for checking that both sides actually kept their commitments.","Several earlier agreements had tried to limit the arms race, and, just like the treaty, they included a system for checking that both sides kept their commitments.","Earlier agreements had tried to limit the arms race, but this treaty was the first to provide a way of checking whether both sides honored their commitments.","Since earlier agreements had failed to limit the arms race, the treaty's authors abandoned the idea of checking whether both sides were actually keeping their commitments."],"a":2,"ex":"«By no means the first» = בשום אופן לא הראשון, כלומר היו ניסיונות קודמים. «nonetheless» = ובכל זאת, הוא הראשון עם מנגנון פיקוח. התשובה הראשונה אומרת שזה הניסיון הראשון, והשנייה אומרת שגם להסכמים הקודמים היה פיקוח.","w":[["by no means","בשום אופן לא"],["nonetheless","בכל זאת, למרות זאת"],["verify","לאמת, לוודא"]]}]},{"type":"sc","qs":[{"q":"The government introduced strict measures to ___ water use during the drought, including fines for watering gardens during the day.","o":["boost","subsidize","curtail","justify"],"a":2,"ex":"«Curtail» = לצמצם, לקצץ. קנסות על השקיה בשעות היום נועדו להפחית צריכת מים בזמן בצורת. «boost» ו-«subsidize» היו מעודדות צריכה, ההפך מהמטרה.","w":[["curtail","לצמצם, לקצץ"],["drought","בצורת"],["subsidize","לסבסד"]]},{"q":"The new rules had ___ taken effect when several companies announced they would challenge them in court, so swift was the opposition.","o":["eventually","gradually","long since","hardly"],"a":3,"ex":"«Hardly... when» = רק... וכבר, מיד אחרי ש.... סוף המשפט אומר שההתנגדות הייתה מהירה מאוד, ולכן החברות הודיעו כמעט מיד. «long since» (מזמן) סותרת את המהירות.","w":[["hardly","כמעט לא"],["swift","מהיר"],["take effect","להיכנס לתוקף"]]},{"q":"The scale of the flooding was ___: in more than two centuries of record-keeping, the river had never risen so high.","o":["unprecedented","predictable","negligible","routine"],"a":0,"ex":"«Unprecedented» = חסר תקדים. הנהר מעולם לא עלה כל כך גבוה ב-200 שנות תיעוד, כלומר לא היה כדבר הזה. «routine» ו-«predictable» אומרות שזה רגיל וצפוי, ההפך.","w":[["unprecedented","חסר תקדים"],["negligible","זניח"]]},{"q":"For decades, a reliable treatment for the disease remained ___: each drug that looked promising in early tests failed in later trials.","o":["accessible","elusive","affordable","obsolete"],"a":1,"ex":"«Elusive» = חמקמק, קשה להשגה. כל תרופה נכשלה, כך שטיפול אמין לא נמצא. «accessible» (נגיש) אומרת ההפך, ו-«affordable» עוסקת במחיר, שלא מוזכר כאן.","w":[["elusive","חמקמק, קשה להשגה"],["obsolete","מיושן, שאבד עליו הכלח"]]}]}]},{"id":"s11","title":"פטור · מבחן 2","tier":3,"tierHe":"פטור","hi":150,"chapters":[{"type":"sc","qs":[{"q":"Critics dismissed the chief executive's apology as ___, noting that it came only after the scandal had begun to hurt the company's sales.","o":["candid","disingenuous","spontaneous","magnanimous"],"a":1,"ex":"«disingenuous» = לא כן, מעמיד פנים. המבקרים טוענים שההתנצלות הגיעה רק כשהמכירות נפגעו, כלומר היא לא אמיתית. «candid» (גלוי לב) ו-«spontaneous» (ספונטני) הם ההפך ממה שהמשפט רומז.","w":[["disingenuous","לא כן, צבוע"],["dismiss","לבטל, לפטור כלא חשוב"],["candid","גלוי לב"]]},{"q":"The museum will lend the painting to the exhibition ___ it is insured for its full value and kept at a constant temperature throughout the tour.","o":["even though","whereas","on condition that","in case"],"a":2,"ex":"«on condition that» = בתנאי ש. הביטוח והטמפרטורה הם התנאים שבלעדיהם המוזיאון לא ישאיל את הציור. «in case» (למקרה ש) נותן אמצעי זהירות ולא תנאי, ו-«even though» יוצר ויתור שאין לו היגיון כאן.","w":[["on condition that","בתנאי ש..."],["in case","למקרה ש..."]]},{"q":"The once-thriving fishing village has become ___, its harbor silted up and most of its houses standing empty for much of the year.","o":["bustling","affluent","pristine","desolate"],"a":3,"ex":"«desolate» = שומם, עזוב. נמל סתום ובתים ריקים מתארים מקום נטוש. «bustling» (הומה) ו-«affluent» (אמיד) מתאימים לכפר המשגשג של פעם, לא למצבו היום.","w":[["desolate","שומם, נטוש"],["thriving","משגשג"],["bustling","הומה, שוקק"]]},{"q":"The new policy did little to reduce traffic in the city center; ___, by making parking cheaper on the outskirts, it seems to have encouraged even more people to drive.","o":["on the contrary","likewise","accordingly","for instance"],"a":0,"ex":"«on the contrary» = להפך. החלק השני אומר שהמדיניות לא רק שלא הפחיתה תנועה אלא אף הגבירה אותה, וזה ההפך מהמטרה. «accordingly» (לכן) לא מתאים, כי אי ההצלחה להפחית תנועה איננה סיבה לכך שיותר אנשים נוסעים.","w":[["on the contrary","להפך"],["accordingly","בהתאם לכך, לכן"],["outskirts","פאתי העיר"]]}]},{"type":"sc","qs":[{"q":"The professor's argument was so ___ that even students with no background in philosophy could follow each step without difficulty.","o":["convoluted","esoteric","lucid","spurious"],"a":2,"ex":"«lucid» = בהיר, צלול. אם גם מי שלא למד פילוסופיה הבין כל שלב, הטיעון היה ברור. «convoluted» (מסובך) ו-«esoteric» (מובן רק למעטים) הם ההפך.","w":[["lucid","בהיר, צלול"],["convoluted","מסובך, מפותל"],["esoteric","מובן רק ליודעי ח״ן"]]},{"q":"The reform did raise literacy rates in rural areas, ___ far more slowly and at a far higher cost than its architects had promised.","o":["let alone","thereby","not to mention","albeit"],"a":3,"ex":"«albeit» = אם כי. הרפורמה הצליחה, אבל עם הסתייגות: לאט ויקר יותר מהמתוכנן. «not to mention» מוסיף עוד דבר באותו כיוון ולא מסייג, ו-«let alone» בא רק אחרי משפט שלילי.","w":[["albeit","אם כי"],["not to mention","שלא לדבר על"],["let alone","ובטח שלא, קל וחומר"]]},{"q":"Rather than resolving the dispute, the court's ambiguous ruling only served to ___ it, as both sides claimed that the decision supported their position.","o":["alleviate","exacerbate","settle","preclude"],"a":1,"ex":"«exacerbate» = להחמיר. «Rather than resolving» אומר שהפסיקה לא פתרה את הסכסוך אלא עשתה משהו הפוך, ושני הצדדים טוענים לניצחון. «alleviate» (להקל) ו-«settle» (ליישב) הם בדיוק מה שלא קרה.","w":[["exacerbate","להחמיר"],["alleviate","להקל"],["rather than","במקום, ולא"]]},{"q":"___ its modest budget, the documentary attracted a larger audience than any of the big-studio productions released that year.","o":["Notwithstanding","By virtue of","In view of","Owing to"],"a":0,"ex":"«notwithstanding» = על אף, למרות. תקציב צנוע הוא סיבה לצפות להצלחה קטנה, ובכל זאת הסרט הצליח יותר מהפקות גדולות. שלוש האפשרויות האחרות נותנות סיבה, כאילו התקציב הקטן גרם להצלחה.","w":[["notwithstanding","על אף, למרות"],["by virtue of","מתוקף, בזכות"],["owing to","בשל, עקב"]]}]},{"type":"rc","title":"When a Language Falls Silent","text":["Of the roughly 7,000 languages spoken in the world today, linguists estimate that close to half may fall out of use by the end of this century. Popular accounts tend to picture such a loss as sudden, as though a language vanished at the moment its last speaker died. In reality, that death is usually only the final step in a process that began generations earlier.","The process typically starts when a community comes under pressure, whether economic, political or social, to adopt a more dominant language. Parents who see that the dominant language opens the way to schooling and employment may stop speaking their ancestral tongue to their children, often out of a sincere wish to spare them disadvantage. Once a single generation grows up without it, the language is in serious danger: it may still be heard among the elderly, but it is no longer being passed on. Linguists call such a language 'moribund' long before its final speaker is gone.","Revival movements have tried to reverse this decline, with uneven results. The case most often cited as a success is Hebrew, which, although it had been preserved for centuries in prayer and scholarship, had not been anyone's everyday language. Within a few decades it acquired millions of native speakers. Yet Hebrew's case is in many respects exceptional: its revivers could draw on an extensive written tradition, and they were building a new society in which a shared language met an urgent practical need.","Most communities attempting revival enjoy neither advantage. Programs in which young children are taught entirely in the threatened language, known as 'language nests', have produced a new generation of speakers among the Maori of New Zealand and in Hawaii. Even there, however, many graduates use the language mainly at school and turn to English at home and with friends. Teaching a language, it seems, is considerably easier than restoring the conditions under which people choose to speak it.","For languages whose last speakers have already died, the goals are necessarily more modest. Recordings, dictionaries and grammars compiled by linguists cannot by themselves bring a language back to life, but they can preserve enough of it for later generations to reclaim, should they so wish. Some scholars argue that this, rather than the number of fluent speakers, is the more realistic measure of success."],"qs":[{"q":"The passage mainly discusses","o":["why Hebrew is a model that every endangered language can follow","how languages decline and how far efforts to revive them have succeeded","the reasons parents prefer to raise their children in a dominant language","the methods linguists use to record languages that have no living speakers"],"a":1,"ex":"הקטע מתאר איך שפה נעלמת (פסקאות 1-2) ומה הצליחו ולא הצליחו מאמצי ההחייאה (פסקאות 3-5). ההורים, העברית והתיעוד הם רק חלקים מהתמונה, והקטע אף אומר שהעברית היא מקרה חריג ולא מודל.","w":[["revive","להחיות"],["decline","דעיכה; לדעוך"],["endangered","בסכנת הכחדה"]]},{"q":"According to the second paragraph, linguists describe a language as 'moribund' when","o":["its last speaker has died","it is used only in prayer and scholarship","children no longer learn it, although some people still speak it","its community is under economic pressure to adopt another language"],"a":2,"ex":"בפסקה 2: כשדור שלם גדל בלי השפה, היא עדיין נשמעת אצל הזקנים אבל כבר לא עוברת הלאה, ואז קוראים לה «moribund», עוד הרבה לפני שהדובר האחרון מת. לכן התשובה הראשונה שגויה, והלחץ הכלכלי הוא רק תחילת התהליך.","w":[["moribund","גוסס, על סף מוות"],["pass on","להעביר הלאה"],["ancestral","של האבות, מסורתי"]]},{"q":"In the third paragraph, the word 'exceptional' could best be replaced by","o":["atypical","outstanding","admirable","unexplained"],"a":0,"ex":"בפסקה 3 «exceptional» = חריג, יוצא דופן במובן של לא מייצג. המשפט מסביר שלעברית היו יתרונות שאין לשפות אחרות. «outstanding» (מצוין) מפתה, אבל הכותב לא משבח כאן את העברית אלא אומר שהמקרה שלה לא טיפוסי.","w":[["exceptional","חריג; יוצא מן הכלל"],["atypical","לא טיפוסי"],["in many respects","במובנים רבים"]]},{"q":"The main purpose of the fourth paragraph is to","o":["argue that language nests are more effective than the methods used to revive Hebrew","explain why Maori and Hawaiian are no longer considered endangered","suggest that children should not be taught entirely in a threatened language","show that even relatively successful programs have not fully restored everyday use of a language"],"a":3,"ex":"פסקה 4 מביאה את «language nests» כהצלחה יחסית, ואז אומרת «Even there, however»: הבוגרים מדברים בשפה בעיקר בבית הספר. המטרה היא להראות את הגבול של ההצלחה. הפסקה לא משווה לעברית ולא טוענת שהשפות כבר לא בסכנה.","w":[["threatened","מאוים"],["restore","להשיב, לשקם"],["considerably","במידה ניכרת"]]},{"q":"It can be inferred from the last paragraph that some scholars believe that","o":["recordings and dictionaries are enough to bring a language back to life","documenting a language is pointless once its last speakers have died","an effort may count as successful even if it produces few fluent speakers","the number of fluent speakers is the only true measure of a revival's success"],"a":2,"ex":"המשפט האחרון: יש חוקרים שחושבים ששימור השפה לדורות הבאים, «rather than the number of fluent speakers», הוא מדד ההצלחה הריאלי. כלומר אפשר להצליח גם בלי הרבה דוברים. התשובה הראשונה סותרת את «cannot by themselves bring a language back to life».","w":[["reclaim","לדרוש בחזרה, להשיב לעצמו"],["compile","לחבר, לאסוף לכדי"],["measure","מדד; למדוד"]]}]},{"type":"rs","qs":[{"q":"Only after the old bridge had partially collapsed did the city council agree to fund the repairs that engineers had been urging for more than a decade.","o":["The city council agreed to pay for the repairs that engineers had long demanded, so the old bridge, which had been at risk for years, never collapsed.","Although engineers had pressed for repairs for over ten years, the council did not approve the money for them until part of the old bridge had actually collapsed.","Engineers began urging the city council to fund repairs only after part of the old bridge had collapsed, and the council approved the money ten years later.","For more than a decade, the council paid for repairs to the old bridge, but engineers warned that the work could not prevent it from partly collapsing."],"a":1,"ex":"«Only after... did» = רק אחרי ש... המועצה הסכימה לממן את התיקון רק אחרי שהגשר קרס חלקית, למרות שהמהנדסים דרשו זאת יותר מעשור. בתשובה השלישית המהנדסים התחילו לדרוש רק אחרי הקריסה, וזה הפוך מהמקור.","w":[["only after","רק לאחר ש..."],["urge","לדחוק, להפציר"],["although","למרות ש..."]]},{"q":"But for the timely intervention of a handful of volunteers, the archive of rare manuscripts, which the flood had left soaked and scattered across the library floor, would almost certainly have been lost.","o":["The flood scattered the rare manuscripts across the library floor, and although a few volunteers intervened in time, the archive was almost entirely lost.","A few volunteers had moved the rare manuscripts before the flood arrived, so the archive was neither soaked nor scattered across the library floor.","Because a handful of volunteers reacted too slowly, the flood soaked the archive of rare manuscripts and scattered it across the library floor.","The rare manuscripts, soaked and scattered by the flood, would probably have been destroyed had a few volunteers not stepped in just in time."],"a":3,"ex":"«but for» = אלמלא. אלמלא המתנדבים, הארכיון היה אובד, כלומר בזכותם הוא ניצל. התשובה הנכונה משתמשת ב-«had... not» באותה משמעות. בתשובה הראשונה הארכיון אבד, ובשנייה כתבי היד בכלל לא נרטבו, בניגוד למקור.","w":[["but for","אלמלא, לולא"],["timely","בזמן, בעיתוי הנכון"],["intervention","התערבות"]]},{"q":"Far from slowing the rumor's spread, the company's repeated denials appear to have lent it credibility, since many readers assumed that no one would deny a story so vigorously unless it were true.","o":["The company's repeated denials seem to have made the rumor more believable, because many readers took such strong denials as a sign that the story was true.","The company's repeated denials slowed the spread of the rumor, since many readers assumed that a company would not deny a story so firmly unless it were false.","Many readers already believed the rumor before the company denied it, so its repeated denials had no effect at all on how widely the story spread.","Although the company's repeated denials made the rumor seem more credible to some, few readers believed that a story denied so strongly could actually be true."],"a":0,"ex":"«Far from slowing» = רחוק מלהאט, כלומר ההכחשות לא האטו את השמועה אלא חיזקו אותה, כי קוראים הניחו שלא מכחישים כך סיפור אלא אם הוא נכון. התשובה השנייה הופכת את התוצאה, והרביעית אומרת שמעטים האמינו, בסתירה למקור.","w":[["far from","רחוק מ..., ממש לא"],["credibility","אמינות"],["unless","אלא אם כן"]]}]},{"type":"rs","qs":[{"q":"While few economists now dispute that the tariff contributed to the recession, there remains considerable disagreement over whether it was the decisive cause or merely one factor among many.","o":["Most economists now agree that the tariff was the main cause of the recession, though a few still argue that it was only one of several contributing factors.","Few economists now believe that the tariff played any part in the recession, although they still disagree about which of the other factors was the decisive one.","Most economists now accept that the tariff played some part in the recession, but they still differ on whether it was the main cause or one of several.","Economists still disagree about whether the tariff played any part at all in the recession, but most of them accept that it was not the decisive cause."],"a":2,"ex":"«few dispute that» = מעטים חולקים על כך, כלומר רובם מסכימים שהמכס תרם למיתון. המחלוקת היא רק האם הוא היה הסיבה המכרעת. בתשובה הראשונה רובם כבר מסכימים שהוא הסיבה העיקרית, וזו בדיוק הנקודה שעדיין שנויה במחלוקת.","w":[["while","בעוד ש... (ניגוד)"],["dispute","לחלוק על, לערער"],["merely","רק, לא יותר מ..."]]},{"q":"Unless the coral reefs are given at least a decade free from rising water temperatures, scientists warn, even the most ambitious replanting programs will be unable to restore them to their former diversity.","o":["Scientists warn that ambitious replanting programs will restore the coral reefs to their former diversity within a decade, even if water temperatures continue to rise.","According to scientists, replanting programs, however ambitious, can bring back the reefs' former diversity only if water temperatures stop rising for at least ten years.","Scientists warn that rising water temperatures have already damaged the coral reefs so badly that no replanting program could ever restore their former diversity.","According to scientists, the reefs will regain their former diversity after ten years of stable water temperatures, provided that no replanting program interferes with them."],"a":1,"ex":"«unless» = אלא אם כן. בלי עשור של טמפרטורות יציבות, שום תוכנית לא תצליח; התשובה הנכונה אומרת זאת עם «only if» (רק אם). בתשובה השלישית אין בכלל סיכוי, אבל המקור משאיר תנאי שבו ההצלחה אפשרית.","w":[["unless","אלא אם כן"],["only if","רק אם"],["diversity","מגוון"]]},{"q":"The new screening test is no more accurate than the one it replaced; its advantage lies rather in the fact that a nurse can perform it in minutes, without a specialist laboratory.","o":["The new screening test is more accurate than the old one and, unlike it, can be carried out in a few minutes by a nurse rather than in a specialist laboratory.","Although the new screening test is quicker than the old one, it is also less accurate, since it is performed by a nurse rather than in a specialist laboratory.","The new screening test is no more accurate than the old one and, like it, still requires a specialist laboratory, although a nurse can now perform part of it.","What makes the new screening test better than the old one is not greater accuracy but the fact that a nurse can do it quickly, without a specialist laboratory."],"a":3,"ex":"«no more accurate than» = לא מדויק יותר (מדויק באותה מידה). היתרון היחיד: אחות מבצעת אותה בדקות בלי מעבדה. בתשובה הראשונה הבדיקה מדויקת יותר, ובשנייה פחות מדויקת, ושתיהן משנות את נקודת הדיוק.","w":[["no more... than","לא יותר... מ..."],["rather than","במקום, ולא"],["instead of","במקום (+שם עצם / ing)"]]}]},{"type":"sc","qs":[{"q":"Wary of appearing to take sides, the mediator remained scrupulously ___ throughout the negotiations, refusing even to comment on either party's proposals.","o":["impartial","partisan","vehement","gullible"],"a":0,"ex":"«impartial» = לא משוחד, ניטרלי. המתווך נזהר מלהיראות כמי שבוחר צד, ולכן לא הגיב על אף הצעה. «partisan» (מצדד בצד אחד) הוא בדיוק ההפך.","w":[["impartial","ניטרלי, לא משוחד"],["wary","זהיר, חושש"],["partisan","מפלגתי, מצדד"]]},{"q":"Few of the trainees could solve even the basic problems in the manual, ___ the advanced ones that the examiners had added at the end.","o":["apart from","such as","let alone","instead of"],"a":2,"ex":"«let alone» = ובטח שלא. אם מעטים פתרו אפילו את הבעיות הבסיסיות, ודאי שלא פתרו את המתקדמות. «apart from» (חוץ מ) היה אומר שהמתקדמות דווקא נפתרו, וזה לא הגיוני.","w":[["let alone","ובטח שלא, קל וחומר"],["apart from","חוץ מ...; מלבד"],["few","מעט (כמעט אין)"]]},{"q":"The ambassador's ___ remarks, made off the record at a private dinner, caused a diplomatic incident that took both governments months to repair.","o":["prudent","indiscreet","tactful","guarded"],"a":1,"ex":"«indiscreet» = לא זהיר, חסר טקט בדיבור. דברים שגרמו לתקרית דיפלומטית ארוכה לא היו זהירים. «prudent», «tactful» ו-«guarded» כולן אומרות זהירות, ההפך מהתוצאה.","w":[["indiscreet","לא זהיר בדיבור, פטפטן"],["prudent","נבון, זהיר"],["tactful","בעל טקט"]]},{"q":"The study was small and lasted only six weeks; its results, ___, are consistent with those of several much larger and longer trials.","o":["all the same","consequently","that is","similarly"],"a":0,"ex":"«all the same» = בכל זאת. המחקר קטן וקצר (חולשה), ובכל זאת התוצאות שלו תואמות מחקרים גדולים. «consequently» (כתוצאה מכך) לא מתאים, כי היותו קטן איננה הסיבה להתאמה.","w":[["all the same","בכל זאת"],["consequently","כתוצאה מכך, לפיכך"],["consistent with","תואם, עולה בקנה אחד עם"]]}]}]},{"id":"s12","title":"פטור · מבחן 3","tier":3,"tierHe":"פטור","hi":150,"chapters":[{"type":"sc","qs":[{"q":"The new regulations were so ___ that judges in different courts reached opposite conclusions about what they actually required.","o":["ambiguous","stringent","explicit","redundant"],"a":0,"ex":"«Ambiguous» = דו-משמעי, לא ברור. שופטים הגיעו למסקנות הפוכות לגבי מה התקנות דורשות, כלומר אפשר לפרש אותן ביותר מדרך אחת. «explicit» (מפורש) אומרת בדיוק את ההפך, ו-«stringent» (מחמיר) לא מסבירה למה הפרשנויות שונות.","w":[["ambiguous","דו-משמעי, עמום"],["explicit","מפורש"],["stringent","מחמיר, נוקשה"]]},{"q":"The museum agreed to lend the painting to the exhibition ___ it would be kept behind glass at a constant temperature.","o":["even though","on condition that","whereas","lest"],"a":1,"ex":"«On condition that» = בתנאי ש.... המוזיאון הסכים להשאיל את הציור, ובתנאי שישמרו עליו מאחורי זכוכית. «lest» (כדי שלא) היה אומר שהמוזיאון רצה למנוע את השמירה מאחורי זכוכית, וזה לא הגיוני.","w":[["on condition that","בתנאי ש..."],["lest","פן, שמא, כדי שלא"]]},{"q":"Critics dismissed the minister's apology as ___, pointing out that he had repeated the very same remarks in a radio interview the following day.","o":["heartfelt","candid","disingenuous","belated"],"a":2,"ex":"«Disingenuous» = לא כן, מתחסד. השר חזר על אותם דברים כבר למחרת, ולכן המבקרים טענו שההתנצלות לא הייתה אמיתית. «heartfelt» (מכל הלב) אומרת ההפך, ו-«belated» (מאוחר מדי) עוסקת בתזמון, והמשפט לא מדבר על איחור.","w":[["disingenuous","לא כן, צבוע"],["dismiss","לבטל, לפטור כלא חשוב"],["belated","מאוחר, שבא באיחור"]]},{"q":"The reforms did produce a rise in literacy, ___ a far more modest one than their architects had promised.","o":["hence","namely","likewise","albeit"],"a":3,"ex":"«Albeit» = אם כי. הרפורמות אכן העלו את האוריינות, אבל העלייה הייתה קטנה בהרבה ממה שהובטח: זו הסתייגות. «namely» (כלומר) מפרטת ולא מסתייגת, ו-«hence» (לכן) יוצרת קשר של תוצאה שאין כאן.","w":[["albeit","אם כי"],["namely","כלומר, דהיינו"],["modest","צנוע, מתון"]]}]},{"type":"sc","qs":[{"q":"Years without rain had left the land so ___ that even the hardiest crops failed to take root.","o":["fertile","lush","arid","saturated"],"a":2,"ex":"«Arid» = צחיח, יבש מאוד. שנים בלי גשם השאירו את האדמה יבשה, ולכן אפילו הגידולים העמידים לא נקלטו. «fertile» (פורה) ו-«lush» (שופע צמחייה) אומרות ההפך, ו-«saturated» (רווי במים) לא מתאימה לשנים בלי גשם.","w":[["arid","צחיח, יבש"],["fertile","פורה"],["saturated","רווי"]]},{"q":"___ the board's repeated assurances, many employees remained convinced that further layoffs were imminent.","o":["Owing to","In view of","By virtue of","Notwithstanding"],"a":3,"ex":"«Notwithstanding» = על אף, למרות. ההנהלה הרגיעה שוב ושוב, ובכל זאת העובדים היו משוכנעים שיהיו פיטורים. שלוש האפשרויות האחרות מציינות סיבה (בגלל, לאור), וההבטחות לא יכולות להיות הסיבה לחשש מפיטורים.","w":[["notwithstanding","על אף, למרות"],["owing to","בשל, עקב"],["imminent","קרוב, עומד לקרות"]]},{"q":"The professor's lectures were notoriously ___: a single point could take her forty minutes to make, with countless digressions along the way.","o":["verbose","concise","succinct","coherent"],"a":0,"ex":"«Verbose» = מילולי מדי, ארכני. נקודה אחת לקחה ארבעים דקות עם אינספור סטיות מהנושא. «concise» ו-«succinct» פירושן תמציתי, בדיוק ההפך, ו-«coherent» (קוהרנטי, מסודר) לא מתיישבת עם הסטיות הרבות.","w":[["verbose","ארכני, מכביר מילים"],["succinct","תמציתי"],["digression","סטייה מהנושא"]]},{"q":"Few historians accept the chronicle's account of the battle, ___ its author was born nearly a century after the events he describes.","o":["whereas","seeing that","so that","unless"],"a":1,"ex":"«Seeing that» = מאחר ש..., הואיל ו.... המחבר נולד מאה שנה אחרי הקרב, וזו הסיבה שהיסטוריונים לא סומכים על התיאור. «whereas» מציינת ניגוד, ואין ניגוד בין שני החלקים.","w":[["seeing that","מאחר ש..., הואיל ו..."],["whereas","בעוד ש..., ואילו"],["account","תיאור, דיווח"]]}]},{"type":"rc","title":"The Trouble with Sugar Pills","text":["When a patient feels better after swallowing a pill that contains nothing but sugar, the improvement is real in the sense that matters most: the pain has eased or the nausea has passed. This phenomenon, known as the placebo effect, has been documented for over a century, yet it remains one of the most puzzling features of modern medicine. For those who design clinical trials, it is also one of the most troublesome.","The effect appears to arise largely from expectation. A patient who believes that a treatment will work tends to notice signs of improvement and to describe symptoms as less severe. Brain-imaging studies suggest, however, that more than mere reporting is involved: in some patients, an inert pill triggers the release of the body's own pain-relieving chemicals. The details matter, too. Two pills often outperform one, injections tend to outperform pills, and a dummy capsule presented as expensive may relieve more pain than an identical one described as cheap.","It is precisely this power that complicates the testing of new drugs. To show that a medicine works, researchers cannot simply compare patients who take it with patients who receive nothing, since the first group would improve partly because they expect to. Instead, trials give one group the real drug and another an identical-looking placebo, and neither the patients nor their doctors are told who is receiving which. Only if the drug clearly outperforms the dummy can it be considered effective.","Yet even this careful design has weaknesses. Many genuine drugs cause noticeable side effects, which allow participants to guess that they belong to the treatment group; their heightened expectations may then inflate the apparent benefit of the drug. Moreover, placebo responses in certain fields, most notably pain and depression, have grown stronger over recent decades. As a result, several promising compounds have failed not because they were useless but because the placebo did almost as well.","Some researchers argue that the placebo effect should be viewed less as an obstacle than as a resource. If expectation alone can ease suffering, doctors might learn to harness it deliberately, for instance by describing treatments in ways that build confidence. Such proposals, however, raise ethical questions of their own, since deceiving patients, even with good intentions, could undermine the trust on which medicine depends."],"qs":[{"q":"The passage is mainly concerned with","o":["the history of the placebo effect since it was first documented","how the placebo effect works and why it makes the testing of new drugs difficult","the ethical problems raised by giving patients pills that contain only sugar","why drugs for pain and depression have become less effective than they once were"],"a":1,"ex":"הקטע מסביר מה גורם לאפקט הפלצבו (פסקה 2) ולמה הוא מסבך ניסויים קליניים (פסקאות 3-4). השאלות האתיות מופיעות רק בפסקה האחרונה, ולגבי כאב ודיכאון הקטע אומר שהפלצבו התחזק, לא שהתרופות נחלשו.","w":[["be concerned with","לעסוק ב..."],["clinical trial","ניסוי קליני"]]},{"q":"According to the second paragraph, which of the following is true?","o":["A placebo helps only patients who are told that the pill is inert.","Brain-imaging studies show that the effect exists only in what patients report.","A single pill usually relieves more pain than two pills do.","The form and the presented price of a dummy treatment can affect how well it works."],"a":3,"ex":"בפסקה 2 כתוב ששתי גלולות עובדות טוב יותר מאחת, זריקה טוב יותר מגלולה, וגלולה «יקרה» מקלה יותר מגלולה זהה «זולה». התשובה על סריקות המוח הופכת את מה שנאמר: הן מראות שמדובר ביותר מדיווח בלבד.","w":[["inert","לא פעיל, חסר השפעה"],["outperform","להצליח יותר מ..."]]},{"q":"In the third paragraph, the word 'they' (in 'because they expect to') refers to","o":["patients who take the new medicine","patients who receive nothing","researchers","doctors"],"a":0,"ex":"«The first group would improve partly because they expect to»: הקבוצה הראשונה היא המטופלים שלוקחים את התרופה, והם משתפרים בין היתר כי הם מצפים להשתפר. «patients who receive nothing» מפתה, אבל זו הקבוצה השנייה, שאין לה ציפייה כזו.","w":[["refer to","להתייחס ל..."],["since","מכיוון ש..."]]},{"q":"The main purpose of the fourth paragraph is to","o":["argue that placebo-controlled trials should be abandoned","describe how researchers prevent participants from guessing which group they are in","explain why even a carefully designed trial may fail to reveal a drug's true value","show that drugs with side effects are generally more effective than other drugs"],"a":2,"ex":"הפסקה פותחת ב«Yet even this careful design has weaknesses» ומסבירה שתופעות לוואי והתחזקות הפלצבו גורמות לתרופות טובות להיכשל. היא לא מציעה לוותר על הניסויים, ולא מתארת איך מונעים מהמשתתפים לנחש, אלא להפך.","w":[["yet","ובכל זאת, אך"],["as a result","כתוצאה מכך"],["inflate","לנפח, להגזים"]]},{"q":"According to the last paragraph, proposals to make deliberate use of the placebo effect are problematic because","o":["the placebo effect is too weak to relieve real suffering","most doctors lack the training to describe treatments clearly","they would make it impossible to conduct clinical trials","they may involve misleading patients, which could damage trust in medicine"],"a":3,"ex":"בפסקה האחרונה כתוב שהצעות כאלה מעלות שאלות אתיות, כי הטעיה של מטופלים, גם בכוונה טובה, עלולה לפגוע באמון שהרפואה נשענת עליו. האפשרות הראשונה סותרת את הקטע, שאומר שציפייה לבדה יכולה להקל על סבל.","w":[["harness","לרתום, לנצל"],["deceive","להונות, להטעות"],["undermine","לערער, לחתור תחת"]]}]},{"type":"rs","qs":[{"q":"Were it not for the generous grants it received from private foundations during its first decade, the orchestra would almost certainly have been forced to disband long before it gained international recognition.","o":["Although private foundations supported the orchestra generously throughout its first ten years, it was still forced to disband long before it could gain international recognition.","The orchestra gained international recognition during its first ten years, and this success persuaded private foundations to give it the generous grants it needed to survive.","The orchestra probably managed to survive long enough to gain international recognition only because private foundations supported it generously throughout its first ten years.","The orchestra probably managed to survive long enough to gain international recognition even though private foundations refused to support it during its first ten years."],"a":2,"ex":"«Were it not for» = אלמלא. בלי המענקים התזמורת הייתה כמעט בוודאות מתפרקת, כלומר היא שרדה בזכותם. בתשובה הראשונה התזמורת התפרקה בכל זאת, ובשנייה סיבה ותוצאה מתהפכות (ההכרה הביאה את המענקים).","w":[["but for","אלמלא, לולא"],["were it not for","אלמלא"],["disband","להתפרק, להתפזר"]]},{"q":"No sooner had the archaeologists begun excavating the site than heavy rains flooded the trenches, delaying the project by several months and destroying a number of fragile artifacts that had not yet been recorded.","o":["Almost immediately after the archaeologists started digging at the site, heavy rains flooded the trenches, setting the project back by months and ruining several delicate finds that were still undocumented.","The archaeologists started digging at the site immediately after heavy rains had flooded the area, which set the project back by months and ruined several delicate finds that were still undocumented.","Almost immediately after the archaeologists started digging at the site, heavy rains flooded the trenches and set the project back by months, although every delicate find there had already been documented.","The archaeologists' careless digging at the site, rather than the heavy rains that followed it, set the project back by months and ruined several delicate finds that were still undocumented."],"a":0,"ex":"«No sooner... than» = רק... וכבר, מיד אחרי ש.... החפירה התחילה, ומיד אחריה הגשמים הציפו, עיכבו והרסו ממצאים שלא תועדו. בתשובה השנייה סדר האירועים הפוך (הגשם קודם), בשלישית כל הממצאים כבר תועדו, וברביעית הנזק נגרם מהחפירה ולא מהגשם.","w":[["no sooner... than","רק... וכבר, מיד אחרי ש..."],["as soon as","ברגע ש..., מיד כש..."],["excavate","לחפור (חפירה ארכיאולוגית)"]]},{"q":"Much as the committee admired the originality of the proposal, it could not recommend funding a project whose costs had been so poorly estimated and whose benefits remained largely speculative.","o":["Because the committee was greatly impressed by how original the proposal was, it recommended funding the project, even though its costs were badly estimated and its benefits mostly uncertain.","Although the committee was greatly impressed by how original the proposal was, it refused to recommend funding the project, since its costs, though carefully estimated, were too high for its benefits.","Although the committee had serious doubts about how original the proposal was, it refused to recommend funding the project mainly because its costs were badly estimated and its benefits mostly uncertain.","Although the committee was greatly impressed by how original the proposal was, it refused to recommend funding the project, since its costs were badly estimated and its benefits mostly uncertain."],"a":3,"ex":"«Much as» = עד כמה ש..., למרות ש.... הוועדה העריכה מאוד את המקוריות, ובכל זאת לא המליצה, כי העלויות הוערכו גרוע והתועלת ספקולטיבית. בראשונה הוועדה המליצה, בשנייה העלויות הוערכו בקפידה, ובשלישית הוועדה פקפקה במקוריות.","w":[["although","למרות ש..."],["much as","עד כמה ש..., למרות ש..."],["speculative","ספקולטיבי, השערתי"]]}]},{"type":"rs","qs":[{"q":"It was not until the late nineteenth century, when improved microscopes revealed that many diseases were caused by microorganisms, that surgeons began routinely washing their hands and sterilizing their instruments before operating.","o":["Surgeons had been routinely washing their hands and sterilizing their instruments long before better microscopes showed, in the late nineteenth century, that microorganisms were responsible for many diseases.","Surgeons started to wash their hands and sterilize their instruments as a matter of routine only after better microscopes showed, in the late nineteenth century, that microorganisms caused many diseases.","In the late nineteenth century, surgeons who routinely washed their hands and sterilized their instruments helped to improve microscopes, which then showed that microorganisms caused many diseases.","Surgeons started to wash their hands and sterilize their instruments as a matter of routine only after better microscopes showed, in the late nineteenth century, that microorganisms caused all diseases."],"a":1,"ex":"«It was not until X that Y» = רק ב-X התחיל Y. המנתחים התחילו לשטוף ידיים ולעקר רק אחרי שהמיקרוסקופים הראו שמיקרואורגניזמים גורמים למחלות רבות. הראשונה הופכת את הזמן (הרבה לפני), השלישית הופכת סיבה ותוצאה, והרביעית משנה «many» ל-«all».","w":[["until","עד ש..."],["after","אחרי"],["routinely","באופן קבוע, כשגרה"]]},{"q":"Such was the shortage of paper in the besieged city that its only remaining newspaper managed to keep appearing solely by printing each edition on the back of old wallpaper.","o":["Paper had become so scarce in the besieged city that the one newspaper still in operation stopped appearing altogether, even though old wallpaper could have been used instead.","Although paper was plentiful in the besieged city, the one newspaper still in operation chose to print each edition on the reverse side of old wallpaper in order to save money.","Paper had become so scarce in the besieged city that the one newspaper still in operation could go on being published only because it used the reverse side of old wallpaper.","Paper had become so scarce in the besieged city that several newspapers could go on being published only because they used the reverse side of old wallpaper."],"a":2,"ex":"«Such was X that» = כזה היה X ש..., כלומר המחסור היה כל כך גדול ש.... העיתון היחיד שנשאר המשיך לצאת רק בזכות הדפסה על גב טפטים ישנים. בראשונה העיתון הפסיק לצאת, בשנייה לא היה מחסור בנייר, וברביעית מדובר בכמה עיתונים ולא בעיתון אחד.","w":[["such... that","כזה... ש..."],["so... that","כל כך... ש..."],["solely","אך ורק, בלעדית"]]},{"q":"Contrary to what its critics had predicted, the ban on single-use plastic bags did not drive shoppers away from local supermarkets; if anything, sales rose slightly in the months after it took effect.","o":["Critics had expected the ban on single-use plastic bags to drive shoppers away from local supermarkets, but in fact sales went up a little in the months following its introduction.","As its critics had predicted, the ban on single-use plastic bags drove shoppers away from local supermarkets, and sales fell a little in the months following its introduction.","Critics had expected the ban on single-use plastic bags to drive shoppers away from local supermarkets, and although they were wrong, sales did not change at all after its introduction.","Critics had expected the ban on single-use plastic bags to increase sales at local supermarkets, but in fact shoppers stayed away from them in the months following its introduction."],"a":0,"ex":"«Contrary to» = בניגוד ל.... המבקרים חזו שהקונים יברחו, אבל זה לא קרה, ואם כבר, המכירות עלו מעט. «if anything» = אם כבר, דווקא. השנייה מאשרת את התחזית, השלישית אומרת שהמכירות לא השתנו בכלל, והרביעית מחליפה בין התחזית לתוצאה.","w":[["in fact","למעשה, בעצם"],["contrary to","בניגוד ל..."],["if anything","אם כבר, דווקא"]]}]},{"type":"sc","qs":[{"q":"The witness's account was ___ by security footage that showed her leaving the building at exactly the time she had stated.","o":["contradicted","fabricated","undermined","corroborated"],"a":3,"ex":"«Corroborate» = לאשש, לחזק בראיה. המצלמה הראתה אותה יוצאת בדיוק בשעה שאמרה, ולכן הסרטון חיזק את העדות. «contradicted» ו-«undermined» (סתר, ערער) אומרות ההפך.","w":[["corroborate","לאשש, לחזק"],["undermine","לערער"],["fabricate","לבדות, לזייף"]]},{"q":"The two parties could not even agree on a date for their next meeting, ___ on the substance of the proposed reforms.","o":["as well as","rather than","let alone","apart from"],"a":2,"ex":"«Let alone» = ובטח שלא, קל וחומר. אם הצדדים לא הצליחו להסכים אפילו על תאריך, בטח שלא יסכימו על תוכן הרפורמות. «as well as» (וגם) לא מתאימה למבנה השלילי של «could not even».","w":[["let alone","ובטח שלא, קל וחומר"],["substance","מהות, תוכן"]]},{"q":"Rather than resolving the dispute, the court's ruling only served to ___ it, prompting both sides to file new lawsuits within days.","o":["settle","exacerbate","defuse","mitigate"],"a":1,"ex":"«Exacerbate» = להחריף, להחמיר. במקום לפתור את הסכסוך, פסק הדין גרם לתביעות חדשות, כלומר החריף אותו. «settle», «defuse» ו-«mitigate» פירושן ליישב, לנטרל ולהקל, כולן ההפך.","w":[["exacerbate","להחריף, להחמיר"],["mitigate","להקל, למתן"],["defuse","לנטרל, להרגיע"]]},{"q":"Doctors are urged to prescribe antibiotics sparingly; ___, bacteria will continue to develop resistance to them at an alarming rate.","o":["otherwise","accordingly","similarly","in particular"],"a":0,"ex":"«Otherwise» = אחרת. אם הרופאים לא ירשמו אנטיביוטיקה בחסכנות, החיידקים ימשיכו לפתח עמידות. «accordingly» (בהתאם לכך) היה אומר שהעמידות נובעת מהרישום החסכוני, וזה הפוך מההיגיון.","w":[["otherwise","אחרת"],["accordingly","בהתאם לכך, לכן"],["sparingly","בחסכנות, במשורה"]]}]}]}];
